-- LAT batch 2: General Knowledge, Pakistan Studies and Islamiat questions written in our own words from the topics covered by LAT prep guides. Every fact checked against the listed sources.
-- General Knowledge GK-0106 onwards

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0106', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Nicosia is the capital of:', '["Lebanon", "Greece", "Malta", "Cyprus"]', 3, 'Nicosia is the capital of Cyprus, an island in the eastern Mediterranean.', '{"0": "Lebanon''s capital is Beirut.", "1": "Greece''s capital is Athens.", "2": "Malta''s capital is Valletta."}'),
  ('GK-0107', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Stockholm is the capital of:', '["Denmark", "Finland", "Sweden", "Norway"]', 2, 'Stockholm is the capital of Sweden.', '{"0": "Denmark''s capital is Copenhagen.", "1": "Finland''s capital is Helsinki.", "3": "Norway''s capital is Oslo."}'),
  ('GK-0108', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Amman is the capital of:', '["Lebanon", "Yemen", "Jordan", "Syria"]', 2, 'Amman is the capital of the Hashemite Kingdom of Jordan.', '{"0": "Lebanon''s capital is Beirut.", "1": "Yemen''s capital is Sanaa.", "3": "Syria''s capital is Damascus."}'),
  ('GK-0109', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Santiago is the capital of:', '["Peru", "Chile", "Bolivia", "Argentina"]', 1, 'Santiago is the capital of Chile.', '{"0": "Peru''s capital is Lima.", "2": "Bolivia''s seat of government is La Paz.", "3": "Argentina''s capital is Buenos Aires."}'),
  ('GK-0110', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Caracas is the capital of:', '["Colombia", "Cuba", "Venezuela", "Ecuador"]', 2, 'Caracas is the capital of Venezuela.', '{"0": "Colombia''s capital is Bogotá.", "1": "Cuba''s capital is Havana.", "3": "Ecuador''s capital is Quito."}'),
  ('GK-0111', 'World geography and countries', 'Capitals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Freetown is the capital of:', '["Sierra Leone", "Senegal", "Ghana", "Liberia"]', 0, 'Freetown, founded as a home for freed slaves, is the capital of Sierra Leone.', '{"1": "Senegal''s capital is Dakar.", "2": "Ghana''s capital is Accra.", "3": "Liberia''s capital is Monrovia."}'),
  ('GK-0112', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Rabat is the capital of:', '["Algeria", "Libya", "Tunisia", "Morocco"]', 3, 'Rabat is the capital of Morocco; Casablanca is its largest city.', '{"0": "Algeria''s capital is Algiers.", "1": "Libya''s capital is Tripoli.", "2": "Tunisia''s capital is Tunis."}'),
  ('GK-0113', 'World geography and countries', 'Capitals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Taipei is the capital of:', '["Vietnam", "Thailand", "Taiwan", "South Korea"]', 2, 'Taipei is the seat of government of Taiwan.', '{"0": "Vietnam''s capital is Hanoi.", "1": "Thailand''s capital is Bangkok.", "3": "South Korea''s capital is Seoul."}'),
  ('GK-0114', 'World geography and countries', 'Old names', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Formosa is the old name of:', '["Sri Lanka", "Taiwan", "Thailand", "Myanmar"]', 1, 'Portuguese sailors called the island ''Ilha Formosa'' (beautiful island); today it is Taiwan.', '{"0": "Sri Lanka was called Ceylon.", "2": "Thailand was called Siam.", "3": "Myanmar was called Burma."}'),
  ('GK-0115', 'World geography and countries', 'Old names', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Abyssinia is the old name of:', '["Sudan", "Ethiopia", "Kenya", "Somalia"]', 1, 'Abyssinia was the old European name for Ethiopia.', '{"0": "Sudan was not called Abyssinia.", "2": "Kenya was British East Africa.", "3": "Somalia was not called Abyssinia."}'),
  ('GK-0116', 'World geography and countries', 'Old names', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Christiania is the old name of which capital city?', '["Copenhagen", "Helsinki", "Oslo", "Stockholm"]', 2, 'Norway''s capital was called Christiania (later Kristiania) until it took back the name Oslo in 1925.', '{"0": "Copenhagen has kept its name.", "1": "Helsinki was called Helsingfors in Swedish.", "3": "Stockholm has kept its name."}'),
  ('GK-0117', 'World geography and countries', 'Old names', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Angora is the old name of:', '["Baghdad", "Izmir", "Ankara", "Istanbul"]', 2, 'Ankara was known in the West as Angora, which is why Angora goats and cats are named after it.', '{"0": "Baghdad has kept its name.", "1": "Izmir was Smyrna.", "3": "Istanbul was Constantinople."}'),
  ('GK-0118', 'World geography and countries', 'Old names', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Rhodesia (Southern Rhodesia) is now called:', '["Zambia", "Ghana", "Tanzania", "Zimbabwe"]', 3, 'Southern Rhodesia became Zimbabwe in 1980; Northern Rhodesia became Zambia in 1964.', '{"0": "Zambia was Northern Rhodesia.", "1": "Ghana was the Gold Coast.", "2": "Tanzania was Tanganyika and Zanzibar."}'),
  ('GK-0119', 'World geography and countries', 'Old names', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'British Honduras is the old name of:', '["Jamaica", "Honduras", "Belize", "Guyana"]', 2, 'British Honduras, in Central America, became Belize; it gained independence in 1981.', '{"0": "Jamaica has kept its name.", "1": "Honduras was a Spanish colony, not British Honduras.", "3": "Guyana was British Guiana."}'),
  ('GK-0120', 'International organisations and treaties', 'Parliaments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The parliament of Bangladesh is called:', '["Jatiya Sangsad", "Lok Sabha", "Majlis-e-Shoora", "Rashtriya Panchayat"]', 0, 'Bangladesh''s single-chamber parliament is the Jatiya Sangsad (National Parliament).', '{"1": "The Lok Sabha is India''s lower house.", "2": "Majlis-e-Shoora is Pakistan''s parliament.", "3": "This was Nepal''s old legislature."}'),
  ('GK-0121', 'International organisations and treaties', 'Parliaments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The parliament of Norway is called the:', '["Storting", "Folketing", "Riksdag", "Knesset"]', 0, 'Norway''s parliament is the Storting.', '{"1": "The Folketing is Denmark''s parliament.", "2": "The Riksdag is Sweden''s parliament.", "3": "The Knesset is Israel''s parliament."}'),
  ('GK-0122', 'International organisations and treaties', 'Parliaments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The parliament of Spain is called the:', '["Duma", "Cortes Generales", "Diet", "Bundestag"]', 1, 'Spain''s parliament is the Cortes Generales.', '{"0": "The Duma is Russia''s lower house.", "2": "The Diet is Japan''s parliament.", "3": "The Bundestag is Germany''s parliament."}'),
  ('GK-0123', 'International organisations and treaties', 'Parliaments', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The British Parliament has how many houses?', '["Two", "Three", "One", "Four"]', 0, 'The UK Parliament is bicameral: the House of Commons and the House of Lords.', '{"1": "There are only the Commons and the Lords.", "2": "Britain''s parliament is not single-chamber.", "3": "There are only two houses."}'),
  ('GK-0124', 'International organisations and treaties', 'Official residences', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', '10 Downing Street, London, is the official residence of the:', '["British Prime Minister", "British King", "Mayor of London", "Speaker of the Commons"]', 0, '10 Downing Street is the office and home of the UK Prime Minister.', '{"1": "The monarch''s London residence is Buckingham Palace.", "2": "The Mayor works at City Hall.", "3": "The Speaker lives in Speaker''s House at Westminster."}'),
  ('GK-0125', 'International organisations and treaties', 'Official residences', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', '''Temple Trees'' in Colombo is the official residence of the:', '["King of Bhutan", "King of Nepal", "President of Maldives", "Prime Minister of Sri Lanka"]', 3, 'Temple Trees in Colombo is the official residence of Sri Lanka''s Prime Minister.', '{"0": "Bhutan''s king lives in Thimphu.", "1": "Nepal is no longer a monarchy.", "2": "The Maldives president lives in Muleeaage, Malé."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0126', 'World geography and countries', 'Oceans and seas', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The smallest ocean in the world is the:', '["Indian Ocean", "Southern Ocean", "Arctic Ocean", "Atlantic Ocean"]', 2, 'The Arctic Ocean, around the North Pole, is the smallest and shallowest ocean.', '{"0": "The Indian Ocean is the third largest.", "1": "The Southern Ocean is larger than the Arctic.", "3": "The Atlantic is the second largest."}'),
  ('GK-0127', 'World geography and countries', 'Oceans and seas', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Baku, the capital of Azerbaijan, lies on the:', '["Caspian Sea", "Red Sea", "Aral Sea", "Black Sea"]', 0, 'Baku is a port on the western shore of the Caspian Sea, the world''s largest inland body of water.', '{"1": "The Red Sea lies between Africa and Arabia.", "2": "The Aral Sea lies between Kazakhstan and Uzbekistan.", "3": "Ports on the Black Sea include Odesa and Batumi."}'),
  ('GK-0128', 'World geography and countries', 'Oceans and seas', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The Bosporus strait connects the Black Sea with the:', '["Caspian Sea", "Adriatic Sea", "Red Sea", "Sea of Marmara"]', 3, 'The Bosporus runs through Istanbul and joins the Black Sea to the Sea of Marmara; the Dardanelles then lead to the Aegean.', '{"0": "The Caspian Sea is landlocked.", "1": "The Adriatic is an arm of the Mediterranean between Italy and the Balkans.", "2": "The Red Sea is linked to the Mediterranean by the Suez Canal."}'),
  ('GK-0129', 'World geography and countries', 'Oceans and seas', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Suez Canal Authority', 'The Suez Canal is about how long?', '["1,000 km", "193 km", "80 km", "400 km"]', 1, 'The Suez Canal is about 193 km long, joining Port Said on the Mediterranean to Suez on the Red Sea.', '{"0": "The canal is far shorter than this.", "2": "80 km is about the length of the Panama Canal.", "3": "The canal is less than half this."}'),
  ('GK-0130', 'World geography and countries', 'Oceans and seas', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The Bay of Biscay lies between:', '["Sweden and Finland", "England and France", "France and Spain", "Italy and Greece"]', 2, 'The Bay of Biscay is the arm of the Atlantic along the west coast of France and the north coast of Spain.', '{"0": "Between them is the Gulf of Bothnia.", "1": "Between them is the English Channel.", "3": "Between them is the Ionian Sea."}'),
  ('GK-0131', 'World geography and countries', 'Oceans and seas', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Diego Garcia, a US-UK military base, is an island in the:', '["Arctic Ocean", "Atlantic Ocean", "Indian Ocean", "Pacific Ocean"]', 2, 'Diego Garcia is in the Chagos Archipelago in the central Indian Ocean.', '{"0": "Diego Garcia is tropical, south of the equator.", "1": "Ascension Island is a base in the Atlantic.", "3": "Guam is a US base in the Pacific."}'),
  ('GK-0132', 'World geography and countries', 'Oceans and seas', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'A piece of land surrounded by water on all sides is called a/an:', '["Isthmus", "Island", "Delta", "Peninsula"]', 1, 'An island is land with water all around it.', '{"0": "An isthmus is a narrow strip of land joining two larger lands.", "2": "A delta is land built up at a river''s mouth.", "3": "A peninsula has water on three sides only."}'),
  ('GK-0133', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Which mountains are taken as the boundary between Europe and Asia?', '["Andes", "Alps", "Atlas Mountains", "Ural Mountains"]', 3, 'The Ural Mountains in Russia are the usual dividing line between Europe and Asia.', '{"0": "The Andes are in South America.", "1": "The Alps are in central Europe.", "2": "The Atlas Mountains are in north-west Africa."}'),
  ('GK-0134', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The longest mountain range on land is the:', '["Rockies", "Himalayas", "Alps", "Andes"]', 3, 'The Andes run about 7,000 km down the west of South America.', '{"0": "The Rockies are shorter than the Andes.", "1": "The Himalayas are the highest, not the longest.", "2": "The Alps are much shorter."}'),
  ('GK-0135', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The Siachen Glacier lies in which mountain range?', '["Sulaiman Range", "Salt Range", "Hindu Kush", "Karakoram"]', 3, 'Siachen, one of the longest glaciers outside the poles, is in the eastern Karakoram.', '{"0": "The Sulaiman Range is in Balochistan and Khyber Pakhtunkhwa.", "1": "The Salt Range is in Punjab.", "2": "The Hindu Kush runs through Afghanistan and northern Pakistan."}'),
  ('GK-0136', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'After the Nile, the second longest river in the world is the:', '["Yangtze", "Mississippi", "Amazon", "Indus"]', 2, 'The Amazon in South America is the second longest river and carries the most water of any river.', '{"0": "The Yangtze is third.", "1": "The Mississippi is shorter than the Amazon.", "3": "The Indus is about 3,000 km long."}'),
  ('GK-0137', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Mount Ararat is the highest peak of:', '["Turkey", "Armenia", "Georgia", "Iran"]', 0, 'Mount Ararat (5,137 m) in eastern Turkey is the country''s highest peak.', '{"1": "Ararat is visible from Armenia but lies in Turkey.", "2": "Georgia''s highest peak is Shkhara.", "3": "Iran''s highest peak is Damavand."}'),
  ('GK-0138', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Taj Mahal stands on the bank of the river:', '["Yamuna", "Indus", "Brahmaputra", "Ganges"]', 0, 'The Taj Mahal in Agra is on the south bank of the Yamuna.', '{"1": "The Indus flows through Pakistan.", "2": "The Brahmaputra flows through Assam.", "3": "The Ganges flows past Varanasi and Patna."}'),
  ('GK-0139', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'London stands on the river:', '["Danube", "Thames", "Liffey", "Seine"]', 1, 'London grew up on the River Thames.', '{"0": "Vienna and Budapest are on the Danube.", "2": "Dublin is on the Liffey.", "3": "Paris is on the Seine."}'),
  ('GK-0140', 'World geography and countries', 'Mountains and rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Paris stands on the river:', '["Tiber", "Thames", "Seine", "Rhine"]', 2, 'Paris is built on both banks of the Seine.', '{"0": "Rome is on the Tiber.", "1": "London is on the Thames.", "3": "The Rhine flows past Cologne and Basel."}'),
  ('GK-0141', 'World geography and countries', 'Mountains and rivers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Damascus stands on the river:', '["Euphrates", "Jordan", "Orontes", "Barada"]', 3, 'The small Barada river flows through Damascus.', '{"0": "The Euphrates flows through eastern Syria and Iraq.", "1": "The Jordan flows into the Dead Sea.", "2": "The Orontes flows past Homs and Hama."}'),
  ('GK-0142', 'World geography and countries', 'Regions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The grassy plains of Argentina are called the:', '["Prairies", "Steppes", "Pampas", "Downs"]', 2, 'The Pampas are the fertile grasslands of Argentina and Uruguay.', '{"0": "The Prairies are in North America.", "1": "The Steppes are in Central Asia and Russia.", "3": "The Downs are in Australia and England."}'),
  ('GK-0143', 'World geography and countries', 'Regions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The Dasht-e-Lut desert is in:', '["Afghanistan", "Libya", "China", "Iran"]', 3, 'Dasht-e-Lut in south-east Iran is one of the hottest places on Earth.', '{"0": "Afghanistan''s deserts include Registan and Dasht-e-Margo.", "1": "Libya is in the Sahara.", "2": "China''s deserts include the Gobi and Taklamakan."}'),
  ('GK-0144', 'World geography and countries', 'Regions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'A country with no coastline is called a:', '["Landlocked country", "Peninsula", "Buffer state", "Protectorate"]', 0, 'A landlocked country, such as Afghanistan or Nepal, has no sea coast.', '{"1": "A peninsula has water on three sides.", "2": "A buffer state lies between two rival powers.", "3": "A protectorate is protected and partly controlled by a stronger state."}'),
  ('GK-0145', 'World geography and countries', 'Regions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook', 'The smallest Central Asian republic by area is:', '["Uzbekistan", "Turkmenistan", "Tajikistan", "Kazakhstan"]', 2, 'Of the five Central Asian republics, Tajikistan (about 143,000 sq km) is the smallest.', '{"0": "Uzbekistan is larger than Tajikistan.", "1": "Turkmenistan is larger than Tajikistan.", "3": "Kazakhstan is by far the largest."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0146', 'World geography and countries', 'Regions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'The largest country in South America by area is:', '["Argentina", "Peru", "Brazil", "Colombia"]', 2, 'Brazil covers nearly half of South America.', '{"0": "Argentina is second.", "1": "Peru is third.", "3": "Colombia is smaller."}'),
  ('GK-0147', 'World geography and countries', 'Regions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pew Research Center', 'Which is the most populous Muslim-majority country?', '["Egypt", "Pakistan", "Bangladesh", "Indonesia"]', 3, 'Indonesia has the largest Muslim population of any country.', '{"0": "Egypt is the most populous Arab country.", "1": "Pakistan has the second largest Muslim population.", "2": "Bangladesh is smaller."}'),
  ('GK-0148', 'World geography and countries', 'Regions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: CIA World Factbook', 'Among the SAARC countries, the smallest in both area and population is:', '["Sri Lanka", "Bhutan", "Nepal", "Maldives"]', 3, 'The Maldives, a chain of coral islands, is the smallest SAARC member.', '{"0": "Sri Lanka is much larger.", "1": "Bhutan is small but larger than Maldives in both.", "2": "Nepal is much larger."}'),
  ('GK-0149', 'World geography and countries', 'Regions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Bhutan is known as the land of the:', '["Thunder Dragon", "Midnight Sun", "Thousand Lakes", "Rising Sun"]', 0, 'Bhutan calls itself Druk Yul, the land of the Thunder Dragon.', '{"1": "That is Norway.", "2": "That is Finland.", "3": "That is Japan."}'),
  ('GK-0150', 'World geography and countries', 'Measurement', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: International Hydrographic Organization', 'One nautical mile is about:', '["1.609 km", "1 km", "2.5 km", "1.852 km"]', 3, 'A nautical mile is defined as 1,852 metres; a statute mile is 1,609 metres.', '{"0": "1.609 km is an ordinary (statute) mile.", "1": "A nautical mile is longer than a kilometre.", "2": "A nautical mile is less than 2 km."}'),
  ('GK-0151', 'World geography and countries', 'Measurement', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'One metre is about:', '["2.28 feet", "3.28 feet", "3.82 feet", "5.28 feet"]', 1, '1 metre = 3.28 feet (and 1 foot = 0.3048 m).', '{"0": "This is too short.", "2": "The digits are swapped.", "3": "This is closer to 1.6 metres."}'),
  ('GK-0152', 'World geography and countries', 'Disputed places', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Kuril Islands are disputed between:', '["Japan and South Korea", "Russia and Japan", "Russia and China", "China and Japan"]', 1, 'Russia holds the southern Kurils, which Japan calls its Northern Territories.', '{"0": "They dispute Dokdo/Takeshima.", "2": "Their border was settled in 2004–2008.", "3": "China and Japan dispute the Senkaku Islands."}'),
  ('GK-0153', 'World geography and countries', 'Disputed places', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Senkaku (Diaoyu) Islands are disputed between:', '["Japan and South Korea", "China and Vietnam", "Russia and Japan", "China and Japan"]', 3, 'Japan controls the Senkaku Islands; China and Taiwan claim them.', '{"0": "They dispute Dokdo/Takeshima.", "1": "They dispute the Paracel Islands.", "2": "They dispute the Kuril Islands."}'),
  ('GK-0154', 'World geography and countries', 'Disputed places', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Falkland (Malvinas) Islands are disputed between the UK and:', '["Brazil", "Argentina", "Chile", "Spain"]', 1, 'Britain and Argentina fought over the Falklands in 1982; Argentina still claims them.', '{"0": "Brazil is not a party to this dispute.", "2": "Chile is not a party to this dispute.", "3": "Spain disputes Gibraltar with the UK."}'),
  ('GK-0155', 'World geography and countries', 'Disputed places', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Abu Musa and the Greater and Lesser Tunbs islands in the Gulf are disputed between:', '["Saudi Arabia and Kuwait", "Iran and Iraq", "Iran and the UAE", "Qatar and Bahrain"]', 2, 'Iran has held the three islands since 1971; the UAE claims them.', '{"0": "They share a neutral zone, not these islands.", "1": "Iran and Iraq disputed the Shatt al-Arab.", "3": "Their Hawar Islands dispute was settled in 2001."}'),
  ('GK-0156', 'World geography and countries', 'Disputed places', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The McMahon Line is the boundary between:', '["Pakistan and Afghanistan", "India and Pakistan", "China and Russia", "India and China"]', 3, 'The McMahon Line, drawn in 1914, marks the eastern border India claims with China.', '{"0": "That is the Durand Line.", "1": "That is the Radcliffe Line.", "2": "The McMahon Line is in the eastern Himalaya."}'),
  ('GK-0157', 'World geography and countries', 'Disputed places', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'In 1967 Israel captured the Golan Heights from:', '["Lebanon", "Egypt", "Syria", "Jordan"]', 2, 'Israel took the Golan Heights from Syria in the 1967 war.', '{"0": "The Golan was Syrian territory.", "1": "Israel took Sinai from Egypt in 1967 and later returned it.", "3": "Israel took the West Bank from Jordan in 1967."}'),
  ('GK-0158', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The League of Nations, the first worldwide organisation for peace, was set up in:', '["1920", "1919", "1914", "1945"]', 0, 'The League of Nations came into being on 10 January 1920 after the First World War.', '{"1": "The Covenant was signed in 1919, but the League began work in January 1920.", "2": "1914 is when the First World War began.", "3": "1945 is when the United Nations was founded."}'),
  ('GK-0159', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'The United Nations formally came into existence on:', '["10 December 1948", "1 January 1942", "24 October 1945", "26 June 1945"]', 2, 'The UN Charter came into force on 24 October 1945, now marked as UN Day.', '{"0": "That is when the Universal Declaration of Human Rights was adopted.", "1": "That is the ''Declaration by United Nations'' in wartime.", "3": "26 June 1945 is when the Charter was signed."}'),
  ('GK-0160', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'The name ''United Nations'' was coined by:', '["Franklin D. Roosevelt", "Winston Churchill", "Joseph Stalin", "Woodrow Wilson"]', 0, 'US President Franklin D. Roosevelt coined the name, first used in the Declaration by United Nations of 1942.', '{"1": "Churchill supported it, but the name was Roosevelt''s.", "2": "Stalin did not coin the name.", "3": "Wilson founded the idea of the League of Nations."}'),
  ('GK-0161', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'The UN currently has how many member states?', '["200", "193", "185", "195"]', 1, 'South Sudan became the 193rd member in 2011.', '{"0": "The UN has 193 members.", "2": "Membership has grown past 185.", "3": "195 counts the two observer states, which are not members."}'),
  ('GK-0162', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'Which of these is NOT an official language of the United Nations?', '["Arabic", "Spanish", "Russian", "German"]', 3, 'The six official UN languages are Arabic, Chinese, English, French, Russian and Spanish.', '{"0": "Arabic is one of the six official languages.", "1": "Spanish is an official language.", "2": "Russian is an official language."}'),
  ('GK-0163', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: OPEC', 'OPEC has its headquarters in:', '["Vienna", "Tehran", "Riyadh", "Geneva"]', 0, 'The Organization of the Petroleum Exporting Countries is based in Vienna, Austria.', '{"1": "OPEC is not based in Iran.", "2": "OPEC is not based in Saudi Arabia.", "3": "OPEC moved from Geneva to Vienna in 1965."}'),
  ('GK-0164', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Bank', 'The headquarters of the World Bank are in:', '["New York", "Geneva", "Manila", "Washington, D.C."]', 3, 'The World Bank and the IMF are both based in Washington, D.C.', '{"0": "New York hosts the UN headquarters.", "1": "Geneva hosts WHO and WTO.", "2": "Manila hosts the Asian Development Bank."}'),
  ('GK-0165', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'The International Labour Organization (ILO) is based in:', '["Vienna", "Rome", "Paris", "Geneva"]', 3, 'The ILO, founded in 1919, is headquartered in Geneva.', '{"0": "Vienna hosts IAEA.", "1": "Rome hosts FAO.", "2": "Paris hosts UNESCO."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0166', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'UNICEF has its headquarters in:', '["New York", "Nairobi", "Paris", "Geneva"]', 0, 'UNICEF, set up in 1946, is based in New York.', '{"1": "Nairobi hosts UNEP.", "2": "Paris hosts UNESCO.", "3": "Geneva hosts WHO and ILO."}'),
  ('GK-0167', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'The World Meteorological Organization (WMO) is based in:', '["Paris", "Vienna", "Geneva", "London"]', 2, 'The WMO is headquartered in Geneva.', '{"0": "Paris hosts UNESCO.", "1": "Vienna hosts IAEA and UNIDO.", "3": "London hosts the IMO."}'),
  ('GK-0168', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Non-Aligned Movement was founded in 1961 at:', '["Belgrade", "New Delhi", "Cairo", "Bandung"]', 0, 'The first NAM summit was held in Belgrade, Yugoslavia, in September 1961.', '{"1": "New Delhi hosted the 1983 summit.", "2": "Cairo hosted the 1964 summit.", "3": "Bandung hosted the Asian-African Conference of 1955."}'),
  ('GK-0169', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: OIC', 'The Organisation of Islamic Cooperation (OIC) was founded in:', '["1945", "1974", "1981", "1969"]', 3, 'The OIC was founded at the Rabat summit on 25 September 1969, after the arson attack on Al-Aqsa Mosque.', '{"0": "1945 is when the Arab League was set up.", "1": "1974 is the year of the Lahore summit.", "2": "1981 is when the GCC was set up."}'),
  ('GK-0170', 'International organisations and treaties', 'Organisations', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: ICRC', 'The International Committee of the Red Cross was founded in 1863 by:', '["Louis Pasteur", "Alfred Nobel", "Florence Nightingale", "Henry Dunant"]', 3, 'Henry Dunant founded the Red Cross after seeing the wounded at the Battle of Solferino.', '{"0": "Pasteur was a scientist.", "1": "Nobel founded the Nobel Prizes.", "2": "Nightingale founded modern nursing."}'),
  ('GK-0171', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: ICRC', 'The Red Cross flag is the reverse of the national flag of:', '["Sweden", "Switzerland", "Denmark", "England"]', 1, 'A red cross on white honours Switzerland, whose flag is a white cross on red.', '{"0": "Sweden''s flag has a yellow Nordic cross.", "2": "Denmark''s flag has a white Nordic cross.", "3": "England''s flag is a red cross on white, but that is not the source."}'),
  ('GK-0172', 'International organisations and treaties', 'Organisations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Asian Development Bank', 'TAPI is a planned pipeline to carry:', '["Natural gas", "Crude oil", "Water", "Electricity"]', 0, 'TAPI would carry gas from Turkmenistan through Afghanistan and Pakistan to India.', '{"1": "TAPI is not an oil pipeline.", "2": "TAPI is not a water project.", "3": "CASA-1000 carries electricity, not TAPI."}'),
  ('GK-0173', 'International organisations and treaties', 'Intelligence and news agencies', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Britain''s foreign intelligence service is commonly called:', '["KGB", "CIA", "MI6", "Mossad"]', 2, 'The Secret Intelligence Service is known as MI6.', '{"0": "The KGB was the Soviet agency.", "1": "The CIA is the US agency.", "3": "Mossad is Israel''s agency."}'),
  ('GK-0174', 'International organisations and treaties', 'Intelligence and news agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', '''Scotland Yard'' is the name used for the headquarters of:', '["The Scottish Parliament", "MI6", "Britain''s royal family", "London''s Metropolitan Police"]', 3, 'Scotland Yard is the name for the headquarters of the Metropolitan Police in London.', '{"0": "The Scottish Parliament sits at Holyrood, Edinburgh.", "1": "MI6 is based at Vauxhall Cross.", "2": "The royal family lives at Buckingham Palace."}'),
  ('GK-0175', 'International organisations and treaties', 'Intelligence and news agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'BSS (Bangladesh Sangbad Sangstha) is the national news agency of:', '["Bhutan", "Bangladesh", "Belarus", "Brunei"]', 1, 'BSS is Bangladesh''s state news agency.', '{"0": "BSS is not Bhutanese.", "2": "Belarus''s agency is BelTA.", "3": "BSS is not from Brunei."}'),
  ('GK-0176', 'International organisations and treaties', 'Intelligence and news agencies', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Almanac and Book of Facts; CIA World Factbook', 'Petra is the official news agency of:', '["Qatar", "Syria", "Jordan", "Egypt"]', 2, 'Petra, named after the ancient city, is Jordan''s news agency.', '{"0": "Qatar''s agency is QNA.", "1": "Syria''s agency is SANA.", "3": "Egypt''s agency is MENA."}'),
  ('GK-0177', 'Everyday science', 'Physics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'A light-year is a unit of:', '["Time", "Distance", "Brightness", "Speed"]', 1, 'A light-year is the distance light travels in one year, about 9.46 trillion km.', '{"0": "Despite the name, it measures distance.", "2": "Brightness is measured in magnitudes.", "3": "It is the distance light travels, not a speed."}'),
  ('GK-0178', 'Everyday science', 'Physics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'When a storage battery is being charged, electrical energy is changed into:', '["Light energy", "Chemical energy", "Heat energy", "Mechanical energy"]', 1, 'Charging stores energy in the battery''s chemicals; discharging turns it back into electricity.', '{"0": "That happens in a bulb.", "2": "That happens in a heater.", "3": "That happens in a motor."}'),
  ('GK-0179', 'Everyday science', 'Physics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'A mirage is caused by:', '["Reflection from a mirror", "Dispersion of light", "Refraction of light", "Polarisation of light"]', 2, 'Light bends (refracts) as it passes through layers of hot and cooler air, making an image like water.', '{"0": "There is no mirror; light bends through air layers.", "1": "Dispersion makes rainbows.", "3": "Polarisation is not the cause."}'),
  ('GK-0180', 'Everyday science', 'Physics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'The filament of an ordinary electric bulb is made of:', '["Tungsten", "Iron", "Nichrome", "Copper"]', 0, 'Tungsten has a very high melting point (about 3,400 °C), so it can glow white-hot.', '{"1": "Iron melts at too low a temperature.", "2": "Nichrome is used in heaters.", "3": "Copper melts at too low a temperature."}'),
  ('GK-0181', 'Everyday science', 'Physics', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'The energy of the Sun and other stars comes from:', '["Fusion of heavy nuclei", "Fission of heavy nuclei", "Burning of coal", "Fusion of light nuclei"]', 3, 'In stars, hydrogen nuclei fuse into helium and release huge energy.', '{"0": "Stars fuse light nuclei like hydrogen.", "1": "Fission powers nuclear power stations.", "2": "Stars do not burn fuel chemically."}'),
  ('GK-0182', 'Everyday science', 'Physics', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: NASA', 'The gas found in the largest amount in the Sun is:', '["Helium", "Nitrogen", "Oxygen", "Hydrogen"]', 3, 'The Sun is about three-quarters hydrogen by mass.', '{"0": "Helium is second.", "1": "Nitrogen is a small fraction.", "2": "Oxygen is a small fraction."}'),
  ('GK-0183', 'Everyday science', 'Physics', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'A dosimeter measures exposure to:', '["Air pressure", "Ionising radiation", "Earthquakes", "Wind speed"]', 1, 'Workers near X-rays or nuclear material wear dosimeters to track the radiation they receive.', '{"0": "Air pressure is measured by a barometer.", "2": "Earthquakes are recorded by a seismograph.", "3": "Wind speed is measured by an anemometer."}'),
  ('GK-0184', 'Everyday science', 'Earth and space', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'Day and night are caused by:', '["The tilt of the Earth''s axis", "The Earth''s rotation on its axis", "The Moon''s orbit", "The Earth''s revolution around the Sun"]', 1, 'As the Earth spins once in 24 hours, each place turns towards and away from the Sun.', '{"0": "The tilt causes seasons.", "2": "The Moon causes tides and phases.", "3": "Revolution causes the year and seasons."}'),
  ('GK-0185', 'Everyday science', 'Earth and space', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: General Science textbooks (Punjab Textbook Board, classes 9-10)', 'The Earth rotates on its axis from:', '["South to north", "North to south", "East to west", "West to east"]', 3, 'The Earth turns from west to east, so the Sun rises in the east.', '{"0": "The Earth spins around a north–south axis.", "1": "The Earth spins around a north–south axis.", "2": "This is why the Sun appears to move east to west."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
