  ('GK-0206', 'Famous people, books and firsts', 'Books', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', '''Living History'' and ''Hard Choices'' are memoirs by:', '["Benazir Bhutto", "Michelle Obama", "Hillary Clinton", "Madeleine Albright"]', 2, 'Hillary Clinton wrote ''Living History'' (2003) and ''Hard Choices'' (2014).', '{"0": "Benazir wrote ''Daughter of the East''.", "1": "Michelle Obama wrote ''Becoming''.", "3": "Albright wrote ''Madam Secretary''."}'),
  ('GK-0207', 'Famous people, books and firsts', 'Books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The ''Tripitaka'' is the sacred scripture of:', '["Jainism", "Hinduism", "Sikhism", "Buddhism"]', 3, 'The Tripitaka (Three Baskets) is the canon of Buddhist teachings.', '{"0": "Jain scriptures are the Agamas.", "1": "Hindu scriptures include the Vedas.", "2": "The Sikh scripture is the Guru Granth Sahib."}'),
  ('GK-0208', 'Famous people, books and firsts', 'Thinkers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', '''Man is by nature a political animal'' was said by:', '["Aristotle", "Plato", "Karl Marx", "Thomas Hobbes"]', 0, 'Aristotle wrote this in his ''Politics''.', '{"1": "Plato wrote ''The Republic''.", "2": "Marx wrote ''Das Kapital''.", "3": "Hobbes wrote ''Leviathan''."}'),
  ('GK-0209', 'Famous people, books and firsts', 'Thinkers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Democracy as ''government of the people, by the people, for the people'' is from a speech by:', '["Thomas Jefferson", "George Washington", "Winston Churchill", "Abraham Lincoln"]', 3, 'Lincoln used these words in the Gettysburg Address, 1863.', '{"0": "Jefferson wrote the Declaration of Independence.", "1": "Washington was the first US President.", "2": "Churchill was a British Prime Minister."}'),
  ('GK-0210', 'Famous people, books and firsts', 'Thinkers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Which Greek philosopher came first?', '["Socrates", "Epicurus", "Aristotle", "Plato"]', 0, 'The order is Socrates, then his student Plato, then Plato''s student Aristotle.', '{"1": "Epicurus came after Aristotle.", "2": "Aristotle was Plato''s student.", "3": "Plato was Socrates'' student."}'),
  ('GK-0211', 'Famous people, books and firsts', 'Thinkers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UNDP', 'The Human Development Index (HDI) was devised by:', '["Amartya Sen", "Adam Smith", "John Maynard Keynes", "Mahbub ul Haq"]', 3, 'Pakistani economist Mahbub ul Haq launched the HDI in the first UNDP Human Development Report, 1990.', '{"0": "Sen worked with him, but the idea was ul Haq''s.", "1": "Smith wrote ''The Wealth of Nations''.", "2": "Keynes founded Keynesian economics."}'),
  ('GK-0212', 'Famous people, books and firsts', 'Thinkers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Taoism was founded by:', '["Mencius", "Lao Tzu", "Gautama Buddha", "Confucius"]', 1, 'Lao Tzu, author of the Tao Te Ching, is regarded as the founder of Taoism.', '{"0": "Mencius was a Confucian thinker.", "2": "The Buddha founded Buddhism.", "3": "Confucius founded Confucianism."}'),
  ('GK-0213', 'Famous people, books and firsts', 'Thinkers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Maslow''s ''Hierarchy of Needs'' is a theory of:', '["Evolution", "Motivation", "Inflation", "Leadership"]', 1, 'Abraham Maslow arranged human needs from basic survival up to self-actualisation to explain motivation.', '{"0": "Evolution is Darwin''s theory.", "2": "Inflation is an economic idea.", "3": "Leadership theories include trait and situational theory."}'),
  ('GK-0214', 'Famous people, books and firsts', 'Inventors and artists', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Johannes Gutenberg is known for inventing the:', '["Steam engine", "Telephone", "Telescope", "Printing press with movable type"]', 3, 'Gutenberg''s press (about 1440) made books cheap and common in Europe.', '{"0": "James Watt improved the steam engine.", "1": "Bell invented the telephone.", "2": "The telescope came from the Netherlands around 1608."}'),
  ('GK-0215', 'Famous people, books and firsts', 'Inventors and artists', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The ''Mona Lisa'' was painted by:', '["Leonardo da Vinci", "Pablo Picasso", "Michelangelo", "Vincent van Gogh"]', 0, 'Leonardo painted the Mona Lisa in the early 1500s; it hangs in the Louvre.', '{"1": "Picasso painted ''Guernica''.", "2": "Michelangelo painted the Sistine Chapel ceiling.", "3": "Van Gogh painted ''The Starry Night''."}'),
  ('GK-0216', 'Famous people, books and firsts', 'Inventors and artists', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Harvard Mark I computer (1944) was designed by:', '["Howard Aiken", "Bill Gates", "Alan Turing", "Charles Babbage"]', 0, 'Howard Aiken designed the Mark I, built by IBM for Harvard.', '{"1": "Gates co-founded Microsoft.", "2": "Turing worked on code-breaking in Britain.", "3": "Babbage designed the Analytical Engine in the 1830s."}'),
  ('GK-0217', 'Famous people, books and firsts', 'Inventors and artists', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'WikiLeaks was founded by:', '["Julian Assange", "Mark Zuckerberg", "Jimmy Wales", "Edward Snowden"]', 0, 'Australian Julian Assange founded WikiLeaks in 2006.', '{"1": "Zuckerberg founded Facebook.", "2": "Wales co-founded Wikipedia.", "3": "Snowden leaked NSA files separately."}'),
  ('GK-0218', 'Famous people, books and firsts', 'Inventors and artists', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Facebook was launched in:', '["2006", "2010", "1998", "2004"]', 3, 'Mark Zuckerberg and fellow students launched Facebook at Harvard in February 2004.', '{"0": "Twitter was launched in 2006.", "1": "Instagram was launched in 2010.", "2": "Google was founded in 1998."}'),
  ('GK-0219', 'Famous people, books and firsts', 'Leaders', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The last President of the Soviet Union was:', '["Vladimir Putin", "Boris Yeltsin", "Leonid Brezhnev", "Mikhail Gorbachev"]', 3, 'Gorbachev resigned on 25 December 1991 and the USSR was dissolved.', '{"0": "Putin led Russia after 1999.", "1": "Yeltsin was the first President of Russia.", "2": "Brezhnev led the USSR from 1964 to 1982."}'),
  ('GK-0220', 'Famous people, books and firsts', 'Leaders', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Sun Yat-sen was:', '["The first Premier of the People''s Republic", "The last Emperor of China", "The first President of the Republic of China", "The founder of the Chinese Communist Party"]', 2, 'Sun Yat-sen became provisional President of the new Republic of China in 1912.', '{"0": "That was Zhou Enlai.", "1": "The last emperor was Puyi.", "3": "The CCP was founded by Chen Duxiu and others in 1921."}'),
  ('GK-0221', 'Famous people, books and firsts', 'Leaders', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Britain''s Prime Minister for most of the Second World War was:', '["Clement Attlee", "Winston Churchill", "Neville Chamberlain", "Lord Mountbatten"]', 1, 'Churchill was Prime Minister from May 1940 to July 1945.', '{"0": "Attlee took over in July 1945.", "2": "Chamberlain led Britain only until May 1940.", "3": "Mountbatten was the last Viceroy of India."}'),
  ('GK-0222', 'Famous people, books and firsts', 'Leaders', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'Nelson Mandela was born in:', '["1925", "1910", "1932", "1918"]', 3, 'Mandela was born on 18 July 1918, now marked as Nelson Mandela International Day.', '{"0": "Mandela was born earlier.", "1": "Mandela was born later.", "2": "Mandela was born earlier."}'),
  ('GK-0223', 'Famous people, books and firsts', 'Travellers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Faxian (Fa-Hien) was a:', '["Portuguese sailor", "Chinese Buddhist pilgrim and traveller", "Arab geographer", "Mughal historian"]', 1, 'Faxian travelled to India around 400 CE to collect Buddhist texts.', '{"0": "Vasco da Gama was a Portuguese sailor.", "2": "Al-Idrisi was an Arab geographer.", "3": "Abul Fazl was a Mughal historian."}'),
  ('GK-0224', 'Famous people, books and firsts', 'Firsts', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Mount Everest was first climbed in:', '["1953", "1975", "1924", "1963"]', 0, 'Edmund Hillary and Tenzing Norgay reached the summit on 29 May 1953.', '{"1": "1975 was the first ascent by a woman.", "2": "Mallory and Irvine disappeared on Everest in 1924.", "3": "1963 was the first American ascent."}'),
  ('GK-0225', 'Famous people, books and firsts', 'Firsts', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The first person to walk in space (1965) was:', '["Valentina Tereshkova", "Alexei Leonov", "Neil Armstrong", "Yuri Gagarin"]', 1, 'Soviet cosmonaut Alexei Leonov made the first spacewalk on 18 March 1965.', '{"0": "Tereshkova was the first woman in space.", "2": "Armstrong was first on the Moon, in 1969.", "3": "Gagarin was the first in space, in 1961, but did not leave his craft."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
