FROM (VALUES
  ('GK-0226', 'Famous people, books and firsts', 'Firsts', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: KLM', 'The oldest airline still flying under its original name, first flying in 1920, is:', '["British Airways", "Aeroflot", "Lufthansa", "KLM"]', 3, 'KLM Royal Dutch Airlines was founded in 1919 and flew its first flight on 17 May 1920.', '{"0": "British Airways was formed in 1974.", "1": "Aeroflot was founded in 1923.", "2": "The current Lufthansa was formed in 1953."}'),
  ('GK-0227', 'Famous people, books and firsts', 'Firsts', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Which country first used paper money?', '["China", "Britain", "Egypt", "Persia"]', 0, 'Paper money began in China under the Tang and Song dynasties.', '{"1": "Britain''s banknotes came much later.", "2": "Egypt did not invent paper money.", "3": "Persia did not invent paper money."}'),
  ('GK-0228', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Napoleon Bonaparte was finally defeated in 1815 at the Battle of:', '["Austerlitz", "Leipzig", "Waterloo", "Trafalgar"]', 2, 'Napoleon''s final defeat came at Waterloo, in present-day Belgium.', '{"0": "Austerlitz (1805) was Napoleon''s great victory.", "1": "Leipzig (1813) was a defeat but not the final one.", "3": "Trafalgar (1805) was a naval defeat of the French fleet."}'),
  ('GK-0229', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The first atomic bomb used in war was dropped on:', '["Tokyo", "Osaka", "Hiroshima", "Nagasaki"]', 2, 'The US dropped an atomic bomb on Hiroshima on 6 August 1945.', '{"0": "Tokyo was fire-bombed, not atom-bombed.", "1": "Osaka was not atom-bombed.", "3": "Nagasaki was bombed second, on 9 August 1945."}'),
  ('GK-0230', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The immediate cause of the Second World War was Germany''s attack on:', '["Austria", "Russia", "France", "Poland"]', 3, 'Germany invaded Poland on 1 September 1939; Britain and France declared war two days later.', '{"0": "Austria was annexed in 1938 without war.", "1": "Germany invaded the USSR in 1941.", "2": "Germany invaded France in 1940."}'),
  ('GK-0231', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Second World War ended in:', '["1939", "1945", "1944", "1947"]', 1, 'Germany surrendered in May 1945 and Japan in September 1945.', '{"0": "1939 is when it began.", "2": "The war continued into 1945.", "3": "1947 is when Pakistan was created."}'),
  ('GK-0232', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Arab Spring began in 2010–11 in:', '["Tunisia", "Egypt", "Syria", "Libya"]', 0, 'Protests in Tunisia after Mohamed Bouazizi''s self-immolation spread across the Arab world.', '{"1": "Egypt''s protests followed Tunisia''s.", "2": "Syria''s uprising followed.", "3": "Libya''s uprising followed."}'),
  ('GK-0233', 'Famous people, books and firsts', 'World history', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'In the 19th century, which empire was called the ''Sick Man of Europe''?', '["The Spanish Empire", "The Austrian Empire", "The Ottoman Empire", "The Russian Empire"]', 2, 'The weakening Ottoman Empire was called the Sick Man of Europe.', '{"0": "Spain was not given this name.", "1": "Austria was not given this name.", "3": "Russia was a rising power."}'),
  ('GK-0234', 'Famous people, books and firsts', 'World history', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Russia went to war with Georgia in:', '["2008", "2022", "2014", "2001"]', 0, 'The Russia–Georgia war was fought in August 2008 over South Ossetia.', '{"1": "2022 is when Russia invaded Ukraine.", "2": "2014 is when Russia annexed Crimea.", "3": "2001 is the year of the 9/11 attacks."}'),
  ('GK-0235', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'India carried out its first nuclear test in:', '["1971", "1998", "1965", "1974"]', 3, 'India''s first test, ''Smiling Buddha'', was at Pokhran on 18 May 1974.', '{"0": "1971 was a war year.", "1": "India''s second round of tests was in May 1998.", "2": "1965 was a war year, not a test year."}'),
  ('GK-0236', 'Famous people, books and firsts', 'World history', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Pharos, one of the Seven Wonders of the Ancient World, was a lighthouse at:', '["Babylon", "Rome", "Alexandria", "Athens"]', 2, 'The Lighthouse of Alexandria stood on the island of Pharos in Egypt.', '{"0": "Babylon had the Hanging Gardens.", "1": "Rome had the Colosseum, not an ancient wonder.", "3": "Athens had the Parthenon."}'),
  ('GK-0237', 'World geography and countries', 'Places', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Dome of the Rock is in:', '["Makkah", "Jerusalem", "Damascus", "Cairo"]', 1, 'The Dome of the Rock stands on the Haram al-Sharif in Jerusalem, beside Al-Aqsa Mosque.', '{"0": "Makkah has the Kaaba.", "2": "Damascus has the Umayyad Mosque.", "3": "Cairo has Al-Azhar."}'),
  ('GK-0238', 'World geography and countries', 'Places', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Al-Azhar University is in:', '["Damascus", "Baghdad", "Istanbul", "Cairo"]', 3, 'Al-Azhar, founded in 970 CE, is in Cairo, Egypt.', '{"0": "Damascus University is in Syria.", "1": "Baghdad had the House of Wisdom.", "2": "Istanbul University is in Turkey."}'),
  ('GK-0239', 'World geography and countries', 'Places', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The Leaning Tower of Pisa is in:', '["Italy", "Greece", "France", "Spain"]', 0, 'The tower is the bell tower of Pisa Cathedral in Tuscany, Italy.', '{"1": "Greece has the Parthenon.", "2": "France has the Eiffel Tower.", "3": "Spain has the Alhambra."}'),
  ('GK-0240', 'Law, courts and the Constitution', 'Terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary', '''De facto'' means:', '["Against the law", "For this purpose only", "By right or by law", "In fact, though not by law"]', 3, 'A de facto government actually holds power, whether or not it is legally recognised (de jure).', '{"0": "That is ''illegal'' or ''contra legem''.", "1": "That is ''ad hoc''.", "2": "That is ''de jure''."}'),
  ('GK-0241', 'Law, courts and the Constitution', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Oxford Dictionary of Law', 'A ''condominium'' in international law is a territory:', '["Ruled jointly by two or more states", "Under a single protector", "In a state of anarchy", "With a federal government"]', 0, 'A condominium is shared sovereignty, as Britain and France once ruled the New Hebrides (Vanuatu).', '{"1": "That is a protectorate.", "2": "That is not the meaning.", "3": "That is a federation."}'),
  ('GK-0242', 'Law, courts and the Constitution', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Oxford Dictionary of Law', 'A ''vassal state'' is one that:', '["Is under the control of a stronger state", "Is ruled by two powers jointly", "Is completely independent", "Has no coastline"]', 0, 'A vassal state owes allegiance and duties to a more powerful overlord state.', '{"1": "That is a condominium.", "2": "A vassal state is not fully independent.", "3": "That is a landlocked state."}'),
  ('GK-0243', 'Law, courts and the Constitution', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Oxford English Dictionary', '''Jingoism'' means:', '["Rule by the rich", "Extreme and aggressive nationalism", "State control of all industry", "Love of peace"]', 1, 'Jingoism is boastful, warlike patriotism.', '{"0": "That is plutocracy.", "2": "That is socialism or communism.", "3": "Jingoism is warlike."}'),
  ('GK-0244', 'Law, courts and the Constitution', 'Terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Investopedia', 'When share prices are falling, the stock market is said to be:', '["Bullish", "Bearish", "Booming", "Liquid"]', 1, 'A bear market is a falling market; a bull market is a rising one.', '{"0": "A bullish market is rising.", "2": "A booming market is rising.", "3": "Liquidity means ease of buying and selling."}'),
  ('GK-0245', 'Law, courts and the Constitution', 'Terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Oxford English Dictionary', '''Debut'' means:', '["A first public appearance", "A farewell appearance", "A formal debate", "A debt owed"]', 0, 'A debut is someone''s first appearance as a performer or player.', '{"1": "That is a swan song or farewell.", "2": "That is a debate.", "3": "That is ''debt''."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

