FROM (VALUES
  ('GK-0246', 'Law, courts and the Constitution', 'Terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Oxford English Dictionary', 'Choreography is the art of:', '["Beautiful handwriting", "Designing dance steps and movements", "Secret writing", "Map making"]', 1, 'A choreographer plans the steps and movements of a dance.', '{"0": "That is calligraphy.", "2": "Secret writing is cryptography.", "3": "Map making is cartography."}'),
  ('GK-0247', 'Law, courts and the Constitution', 'Terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The economic idea of ''laissez-faire'' (let the market work without government control) is most associated with:', '["Adam Smith", "Thomas Malthus", "Karl Marx", "John Maynard Keynes"]', 0, 'Adam Smith''s ''Wealth of Nations'' made the case for free markets.', '{"1": "Malthus wrote on population.", "2": "Marx argued for collective ownership.", "3": "Keynes argued for government spending in slumps."}'),
  ('GK-0248', 'Sports, awards and days', 'Sports', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Badminton World Federation', 'The Thomas Cup is associated with:', '["Golf", "Tennis", "Badminton", "Table tennis"]', 2, 'The Thomas Cup is the men''s world team badminton championship.', '{"0": "Golf has the Ryder Cup.", "1": "Tennis has the Davis Cup.", "3": "Table tennis has the Swaythling Cup."}'),
  ('GK-0249', 'Sports, awards and days', 'Sports', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Aquatics', 'The ''butterfly stroke'' is used in:', '["Rowing", "Wrestling", "Swimming", "Boxing"]', 2, 'Butterfly is one of the four competitive swimming strokes.', '{"0": "Rowing uses oars.", "1": "Wrestling has holds and throws.", "3": "Boxing has jabs and hooks."}'),
  ('GK-0250', 'Sports, awards and days', 'Sports', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Women''s Tennis Association', 'Serena Williams is a famous player of:', '["Badminton", "Tennis", "Golf", "Athletics"]', 1, 'Serena Williams won 23 Grand Slam singles titles.', '{"0": "Famous badminton players include Lin Dan.", "2": "Famous golfers include Tiger Woods.", "3": "Famous sprinters include Usain Bolt."}'),
  ('GK-0251', 'Sports, awards and days', 'Sports', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: International Hockey Federation', 'The first men''s Hockey World Cup (1971) was won by:', '["India", "Pakistan", "Netherlands", "Australia"]', 1, 'Pakistan won the first Hockey World Cup in Barcelona in 1971.', '{"0": "India won in 1975.", "2": "The Netherlands won in 1973.", "3": "Australia first won in 1986."}'),
  ('GK-0252', 'Sports, awards and days', 'Awards', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Britain''s highest military award for gallantry is the:', '["Nishan-e-Haider", "Victoria Cross", "Medal of Honor", "Iron Cross"]', 1, 'The Victoria Cross was created in 1856.', '{"0": "Nishan-e-Haider is Pakistan''s highest award.", "2": "The Medal of Honor is American.", "3": "The Iron Cross was German."}'),
  ('GK-0253', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'World Teachers'' Day is observed on:', '["10 December", "5 October", "7 April", "8 March"]', 1, 'UNESCO marks World Teachers'' Day on 5 October.', '{"0": "10 December is Human Rights Day.", "2": "7 April is World Health Day.", "3": "8 March is International Women''s Day."}'),
  ('GK-0254', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: United Nations and agency official websites', 'World Water Day is observed on:', '["22 March", "22 April", "5 June", "16 October"]', 0, 'The UN has marked World Water Day on 22 March since 1993.', '{"1": "22 April is Earth Day.", "2": "5 June is World Environment Day.", "3": "16 October is World Food Day."}'),
  ('GK-0255', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: World Health Organization', 'World No Tobacco Day is observed on:', '["1 May", "31 May", "1 December", "7 April"]', 1, 'WHO marks World No Tobacco Day on 31 May.', '{"0": "1 May is Labour Day.", "2": "1 December is World AIDS Day.", "3": "7 April is World Health Day."}'),
  ('GK-0256', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: FAO', 'World Food Day is observed on:', '["5 October", "22 March", "16 October", "24 October"]', 2, 'World Food Day on 16 October marks the founding of FAO in 1945.', '{"0": "5 October is World Teachers'' Day.", "1": "22 March is World Water Day.", "3": "24 October is UN Day."}'),
  ('GK-0257', 'Sports, awards and days', 'Days', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'Labour Day on 1 May honours workers, recalling an 1886 strike and clash in:', '["Paris", "London", "Moscow", "Chicago"]', 3, 'May Day remembers the Haymarket affair in Chicago, 1886, in the campaign for an eight-hour day.', '{"0": "The Second International chose the date in Paris, but the events were in Chicago.", "1": "The events were in the USA.", "2": "The events were in the USA."}'),
  ('GK-0258', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'The United States celebrates its Independence Day on:', '["1 July", "26 January", "4 July", "14 July"]', 2, 'The Declaration of Independence was adopted on 4 July 1776.', '{"0": "1 July is Canada Day.", "1": "26 January is India''s Republic Day.", "3": "14 July is Bastille Day in France."}'),
  ('GK-0259', 'Sports, awards and days', 'Days', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Encyclopaedia Britannica', 'China''s National Day is on:', '["1 October", "4 May", "1 July", "15 August"]', 0, 'Mao Zedong proclaimed the People''s Republic of China on 1 October 1949.', '{"1": "4 May is Youth Day.", "2": "1 July marks the founding of the Chinese Communist Party.", "3": "15 August is India''s Independence Day."}'),
  ('GK-0260', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'As first adopted, the Constitution of Pakistan 1973 had how many Articles?', '["250", "234", "300", "280"]', 3, 'The 1973 Constitution was adopted with 280 Articles in 12 Parts; new Articles are inserted with letters (for example 10A, 19A, 25A).', '{"0": "250 is the 1962 Constitution''s count, not 1973''s.", "1": "234 was the number of Articles in the 1956 Constitution.", "2": "The 1973 Constitution had 280 Articles; later ones were added as ''A'' Articles, such as 25A."}'),
  ('GK-0261', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'The Constitution of Pakistan 1973 was authenticated by the President of the Assembly on:', '["23 March 1973", "10 April 1973", "14 August 1973", "12 April 1973"]', 3, 'The National Assembly passed it on 10 April 1973, it was authenticated on 12 April and came into force on 14 August 1973.', '{"0": "23 March is Pakistan Day, not a date in the 1973 Constitution''s making.", "1": "10 April is when the Assembly passed it; it was authenticated two days later.", "2": "14 August 1973 is the day it came into force."}'),
  ('GK-0262', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Which Article of the Constitution declares Islam the state religion of Pakistan?', '["Article 6", "Article 2", "Article 25", "Article 1"]', 1, 'Article 2: ''Islam shall be the State religion of Pakistan''.', '{"0": "Article 6 is about high treason.", "2": "Article 25 is about equality of citizens.", "3": "Article 1 names the Islamic Republic of Pakistan and its territories."}'),
  ('GK-0263', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'Article 2A, which made the Objectives Resolution a substantive part of the Constitution, was inserted in:', '["2010", "1949", "1973", "1985"]', 3, 'Article 2A was added by the Revival of the Constitution of 1973 Order 1985 (later confirmed by the Eighth Amendment).', '{"0": "2010 is the year of the Eighteenth Amendment.", "1": "1949 is when the Objectives Resolution itself was passed.", "2": "In 1973 the Resolution was only the preamble."}'),
  ('GK-0264', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Fundamental rights are set out in the Constitution of Pakistan in Articles:', '["8 to 28", "29 to 40", "175 to 212", "1 to 7"]', 0, 'Part II, Chapter 1 (Articles 8-28) lists the fundamental rights; Article 8 voids laws that conflict with them.', '{"1": "Articles 29-40 are the Principles of Policy, which courts cannot enforce.", "2": "Articles 175-212 deal with the judiciary.", "3": "Articles 1-7 are introductory: the Republic, Islam, Objectives Resolution and high treason."}'),
  ('GK-0265', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'The right to a fair trial and due process was added to the Constitution as Article:', '["4", "19A", "10A", "25A"]', 2, 'Article 10A was inserted by the Eighteenth Amendment (2010).', '{"0": "Article 4 is the right to be dealt with in accordance with law, an older Article.", "1": "Article 19A is the right to information.", "3": "Article 25A is the right to education."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0266', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'The right of every citizen to have access to information in all matters of public importance is in Article:', '["10A", "20", "19A", "19"]', 2, 'Article 19A was added by the Eighteenth Amendment (2010).', '{"0": "Article 10A is the right to a fair trial.", "1": "Article 20 is freedom of religion.", "3": "Article 19 is freedom of speech and of the press."}'),
  ('GK-0267', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Under Article 25 of the Constitution, all citizens are:', '["exempt from taxes below age 25", "entitled to free university education", "required to vote in every election", "equal before law and entitled to equal protection of law"]', 3, 'Article 25 also forbids discrimination on the basis of sex alone, while allowing special protection for women and children.', '{"0": "No such rule exists.", "1": "Article 25A gives free education only to children aged 5 to 16.", "2": "Voting is a right, not a duty, in Pakistan."}'),
  ('GK-0268', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Writs such as habeas corpus, mandamus and certiorari are issued by the High Courts under Article:', '["199", "184", "175", "209"]', 0, 'Article 199 is the High Courts'' constitutional (writ) jurisdiction against public bodies and officials.', '{"1": "Article 184 deals with the original jurisdiction of the Supreme Court.", "2": "Article 175 sets up the courts and separates the judiciary from the executive.", "3": "Article 209 deals with the Supreme Judicial Council."}'),
  ('GK-0269', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended); Hamid Khan, Constitutional and Political History of Pakistan', 'As Article 175(3) now reads, the judiciary was to be separated from the executive progressively within:', '["7 years", "25 years", "1 year", "14 years"]', 3, 'Article 175(3) set a 14-year deadline; the Supreme Court''s Al-Jehad Trust and Sharaf Faridi judgments pushed it through in the 1990s.', '{"0": "The Article as it now stands gives 14 years.", "1": "The period given was 14 years; separation was finally ordered by the Supreme Court in the 1990s.", "2": "The period given was 14 years."}'),
  ('GK-0270', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Which Article makes decisions of the Supreme Court on a point of law binding on all other courts in Pakistan?', '["Article 189", "Article 260", "Article 201", "Article 199"]', 0, 'Articles 189 and 201 give binding force to precedent (stare decisis) in Pakistan.', '{"1": "Article 260 contains definitions.", "2": "Article 201 makes a High Court''s decisions binding on courts below it.", "3": "Article 199 is the High Courts'' writ jurisdiction."}'),
  ('GK-0271', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Definitions of terms used throughout the Constitution of Pakistan are in Article:', '["1", "260", "280", "2"]', 1, 'Article 260 defines terms such as ''citizen'', ''Muslim'' and ''non-Muslim''.', '{"0": "Article 1 is about the Republic and its territories.", "2": "Article 280 is about the continuation of a Proclamation of Emergency.", "3": "Article 2 is about Islam as the state religion."}'),
  ('GK-0272', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Under the Constitution, the Prime Minister of Pakistan is elected by:', '["the Senate", "the National Assembly", "the President", "the people directly"]', 1, 'Under Article 91 the National Assembly elects the Prime Minister by a majority of its total membership.', '{"0": "The Senate takes no part in electing the Prime Minister.", "2": "The President calls on the member who wins the Assembly''s vote.", "3": "Pakistan has a parliamentary system, so the Prime Minister is chosen by the Assembly."}'),
  ('GK-0273', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Which official has the right to speak in either House of Parliament but not to vote?', '["The Chief Election Commissioner", "The Auditor-General", "The Attorney-General", "The Chief Justice"]', 2, 'Article 57 lets the Prime Minister, Federal Ministers, Ministers of State and the Attorney-General speak in either House, but they vote only where they are members.', '{"0": "The CEC has no right to speak in Parliament.", "1": "The Auditor-General reports to Parliament but does not speak in it.", "3": "Judges take no part in Parliament''s proceedings."}'),
  ('GK-0274', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'The supreme command of the Armed Forces of Pakistan is vested in the:', '["Prime Minister", "Minister of Defence", "Chief of Army Staff", "President"]', 3, 'Article 243: the federal government controls the Armed Forces, and their supreme command is vested in the President.', '{"0": "The federal government controls the forces, but the Constitution vests supreme command in the President.", "1": "The Defence Minister runs the ministry, not the supreme command.", "2": "The service chiefs command their own services under the federal government."}'),
  ('GK-0275', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Which of these is NOT a member of the Council of Common Interests?', '["The four Chief Ministers", "The Prime Minister", "Three members nominated by the federal government", "The provincial Governors"]', 3, 'Article 153: the CCI has the Prime Minister, the Chief Ministers and three federal nominees; Governors are not members.', '{"0": "All four Chief Ministers are members.", "1": "The Prime Minister chairs the Council.", "2": "The federal government nominates three members."}'),
  ('GK-0276', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'A Chief Election Commissioner of Pakistan holds office for:', '["until age 65", "three years", "as long as the President wishes", "five years"]', 3, 'Article 215 fixes a five-year term for the Chief Election Commissioner and the members of the Election Commission.', '{"0": "Unlike judges, the CEC has a fixed term.", "1": "The term under Article 215 is five years.", "2": "The CEC can be removed only like a Supreme Court judge."}'),
  ('GK-0277', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'A judge of a High Court in Pakistan retires at the age of:', '["60", "62", "65", "70"]', 1, 'Article 195: High Court judges retire at 62; Article 179: Supreme Court judges at 65.', '{"0": "60 is the usual civil service retirement age, not that of High Court judges.", "2": "65 is the retirement age of Supreme Court judges.", "3": "No judge in Pakistan serves to 70."}'),
  ('GK-0278', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Judges of the superior courts can be removed for misconduct or incapacity only on an inquiry by the:', '["Supreme Judicial Council", "Law and Justice Commission", "Federal Public Service Commission", "National Assembly"]', 0, 'Article 209 sets up the Supreme Judicial Council to inquire into complaints against superior court judges.', '{"1": "The Law and Justice Commission recommends law reform.", "2": "The FPSC recruits civil servants.", "3": "Pakistan''s judges are not removed by a vote of Parliament."}'),
  ('GK-0279', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'A bill to amend the Constitution of Pakistan must be passed in each House by at least:', '["a simple majority of members present", "two-thirds of its total membership", "a national referendum", "three-quarters of members present"]', 1, 'Article 239 requires the votes of two-thirds of the total membership of the National Assembly and of the Senate.', '{"0": "A simple majority is enough for ordinary laws only.", "2": "No referendum is needed to amend the Constitution.", "3": "The Constitution asks for two-thirds of total membership."}'),
  ('GK-0280', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'The minimum voting age in Pakistan is:', '["16 years", "21 years", "25 years", "18 years"]', 3, 'Article 51 sets the voting age at 18.', '{"0": "Pakistan does not allow voting at 16.", "1": "The age was lowered from 21 to 18 in 2002.", "2": "25 is the minimum age to be elected to the National Assembly."}'),
  ('GK-0281', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'Which constitutional amendment of 2010 abolished the Concurrent Legislative List and gave more autonomy to the provinces?', '["Eighteenth Amendment", "Twentieth Amendment", "Seventeenth Amendment", "Twenty-first Amendment"]', 0, 'After the Eighteenth Amendment, Parliament legislates only on the Federal Legislative List; other matters go to the provinces.', '{"1": "The Twentieth Amendment (2012) dealt with caretaker governments and the Election Commission.", "2": "The Seventeenth Amendment (2003) dealt with Musharraf''s changes and the LFO.", "3": "The Twenty-first Amendment (2015) allowed military courts for terrorism cases."}'),
  ('GK-0282', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'Which law served as Pakistan''s working constitution from independence until 1956?', '["The Objectives Resolution", "The Government of India Act 1919", "The Lahore Resolution", "The Government of India Act 1935, as adapted"]', 3, 'Under the Indian Independence Act 1947, the 1935 Act, with changes, served as the interim constitution.', '{"0": "The Objectives Resolution set out principles but was not a constitution.", "1": "The 1919 Act was replaced by the 1935 Act.", "2": "The Lahore Resolution of 1940 demanded separate states; it was not a law."}'),
  ('GK-0283', 'Law, courts and the Constitution', 'Constitution of Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'How many of Pakistan''s constitutions were abrogated outright?', '["Two (1956 and 1962)", "One (1973)", "Three", "None"]', 0, 'The 1956 Constitution was abrogated in October 1958 and the 1962 Constitution in March 1969.', '{"1": "The 1973 Constitution was suspended or held in abeyance, never abrogated.", "2": "Only the 1956 and 1962 constitutions were abrogated.", "3": "Ayub Khan abrogated the 1956 Constitution in 1958, and Yahya Khan the 1962 one in 1969."}'),
  ('GK-0284', 'Law, courts and the Constitution', 'Courts and cases', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'In Federation of Pakistan v. Maulvi Tamizuddin Khan (1955), the Federal Court:', '["ordered fresh general elections within 90 days", "declared martial law illegal", "upheld the Governor-General''s dissolution of the Constituent Assembly on a technical ground", "restored the Constituent Assembly"]', 2, 'Chief Justice Muhammad Munir held that the Sindh court lacked writ jurisdiction because a law had not received assent; Justice Cornelius dissented.', '{"0": "The court did not order elections.", "1": "No martial law was in force in 1955.", "3": "The Sindh Chief Court had restored it; the Federal Court reversed that."}'),
  ('GK-0285', 'Law, courts and the Constitution', 'Courts and cases', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'In The State v. Dosso (1958), the Supreme Court validated Ayub Khan''s martial law by relying on the theory of:', '["Dicey''s rule of law", "Montesquieu''s separation of powers", "John Austin''s command theory", "Hans Kelsen, that a successful revolution creates a new legal order"]', 3, 'Justice Munir used Kelsen''s ''Grundnorm'' reasoning; the decision was later overruled in Asma Jilani (1972).', '{"0": "Dicey''s rule of law argues against such a result.", "1": "Separation of powers was not the basis of the decision.", "2": "The court cited Kelsen, not Austin."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0286', 'Law, courts and the Constitution', 'Courts and cases', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'Which case of 1972 overruled Dosso and declared Yahya Khan a usurper?', '["Benazir Bhutto v. Federation", "Begum Nusrat Bhutto v. Chief of Army Staff", "Zafar Ali Shah v. Pervez Musharraf", "Asma Jilani v. Government of the Punjab"]', 3, 'The court held that martial law imposed after Ayub handed power to Yahya had no legal basis.', '{"0": "That 1988 case dealt with party registration.", "1": "Nusrat Bhutto (1977) validated Zia''s martial law.", "2": "Zafar Ali Shah (2000) validated Musharraf''s takeover."}'),
  ('GK-0287', 'Law, courts and the Constitution', 'Courts and cases', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'In Begum Nusrat Bhutto v. Chief of Army Staff (1977), the Supreme Court validated General Zia''s martial law under the:', '["doctrine of res judicata", "doctrine of necessity", "rule of law", "doctrine of basic structure"]', 1, 'The court allowed the martial law as a temporary necessity, with power to amend the Constitution.', '{"0": "Res judicata bars re-trying decided cases.", "2": "The decision was an exception to the rule of law, justified as necessary.", "3": "Basic structure limits amendments; it was not used here."}'),
  ('GK-0288', 'Law, courts and the Constitution', 'Courts and cases', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Hamid Khan, Constitutional and Political History of Pakistan', 'Which Chief Justice of Pakistan (1960-1968) is remembered for his dissent in the Tamizuddin Khan case and his writings on Islamic law?', '["Justice A. R. Cornelius", "Justice Hamoodur Rahman", "Justice Muhammad Munir", "Justice Sir Abdul Rashid"]', 0, 'Alvin Robert Cornelius, a Christian, was Chief Justice from 1960 to 1968 and argued for Islamic principles in law.', '{"1": "Hamoodur Rahman headed the 1971 war inquiry commission.", "2": "Munir wrote the majority judgment in Tamizuddin Khan.", "3": "Sir Abdul Rashid was the first Chief Justice."}'),
  ('GK-0289', 'Law, courts and the Constitution', 'Courts and cases', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Supreme Court of Pakistan, profile of judges', 'The first woman judge of the Supreme Court of Pakistan, appointed in 2022, is:', '["Justice Tahira Safdar", "Justice Musarrat Hilali", "Justice Majida Rizvi", "Justice Ayesha Malik"]', 3, 'Justice Ayesha A. Malik moved from the Lahore High Court to the Supreme Court in January 2022.', '{"0": "Justice Tahira Safdar was the first woman Chief Justice of a High Court (Balochistan, 2018).", "1": "Justice Hilali joined the Supreme Court in 2023, after Justice Malik.", "2": "Justice Majida Rizvi was the first woman High Court judge, in Sindh."}'),
  ('GK-0290', 'Law, courts and the Constitution', 'Courts and cases', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'In the civil courts of a district in Pakistan, the court above the Civil Judges is the court of the:', '["Deputy Commissioner", "District Judge", "Judicial Magistrate", "Sessions Judge"]', 1, 'The same officer is usually both District Judge (civil) and Sessions Judge (criminal), so is called the District and Sessions Judge.', '{"0": "The Deputy Commissioner is an executive officer, not a judge.", "2": "Magistrates hear criminal cases at the lowest level.", "3": "The Sessions Judge heads the criminal side of the district."}'),
  ('GK-0291', 'Law, courts and the Constitution', 'Courts and cases', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'In Pakistan, a death sentence passed by a Sessions Court:', '["cannot be carried out until it is confirmed by the High Court", "is final, with no further review", "is confirmed only if the convict appeals", "is confirmed by the President"]', 0, 'Section 374 of the CrPC requires the Sessions Court to send the case to the High Court for confirmation.', '{"1": "Every death sentence must go to the High Court.", "2": "Confirmation is needed whether or not the convict appeals.", "3": "The President may pardon, but confirmation is by the High Court."}'),
  ('GK-0292', 'Law, courts and the Constitution', 'Civil procedure', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'The rule that a matter finally decided between the same parties cannot be tried again is called:', '["lis pendens", "stare decisis", "res sub judice", "res judicata"]', 3, 'Section 11 of the Code of Civil Procedure 1908 states the rule of res judicata.', '{"0": "Lis pendens is about property transferred while a suit is pending.", "1": "Stare decisis is the rule of following precedent.", "2": "Res sub judice stops a second suit while the same matter is pending."}'),
  ('GK-0293', 'Law, courts and the Constitution', 'Civil procedure', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'Section 151 of the Code of Civil Procedure deals with the court''s:', '["power to grant temporary injunctions", "appellate powers", "inherent powers", "power of review"]', 2, 'Section 151 preserves the court''s inherent power to make orders needed for justice or to prevent abuse of process.', '{"0": "Temporary injunctions are under Order 39.", "1": "Appeals are under sections 96-108.", "3": "Review is under section 114 and Order 47."}'),
  ('GK-0294', 'Law, courts and the Constitution', 'Civil procedure', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'Temporary injunctions in civil suits are granted under:', '["Order 39, Rules 1 and 2 of the CPC", "Order 7, Rule 11 of the CPC", "Section 5 of the Limitation Act", "Section 11 of the CPC"]', 0, 'Courts look at a prima facie case, balance of convenience and irreparable loss before granting one.', '{"1": "Order 7, Rule 11 deals with rejection of a plaint.", "2": "Section 5 of the Limitation Act allows delay to be excused for appeals.", "3": "Section 11 is res judicata."}'),
  ('GK-0295', 'Law, courts and the Constitution', 'Civil procedure', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'A court may reject a plaint that does not disclose a cause of action under:', '["Order 39, Rule 1 of the CPC", "Section 151 of the CPC", "Section 9 of the CPC", "Order 7, Rule 11 of the CPC"]', 3, 'Order 7, Rule 11 also allows rejection when the suit is undervalued, under-stamped or barred by law.', '{"0": "Order 39 deals with temporary injunctions.", "1": "Section 151 is the inherent power of the court.", "2": "Section 9 says civil courts try all suits of a civil nature."}'),
  ('GK-0296', 'Law, courts and the Constitution', 'Civil procedure', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'A suit about immovable property must usually be filed in the court:', '["where the plaintiff lives", "of the capital city only", "where the property is situated", "chosen by the plaintiff anywhere"]', 2, 'Section 16 of the CPC: suits about immovable property are filed where the property lies.', '{"0": "The plaintiff''s home is not the test for land suits.", "1": "Any court with jurisdiction over the property''s location can hear it.", "3": "Section 16 of the CPC ties land suits to the property''s location."}'),
  ('GK-0297', 'Law, courts and the Constitution', 'Civil procedure', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'In a civil suit, the written statement of the plaintiff''s claim is called the:', '["decree", "summons", "plaint", "written statement"]', 2, 'Order 7 of the CPC sets out what a plaint must contain.', '{"0": "A decree is the court''s formal decision.", "1": "A summons is the court''s notice to appear.", "3": "The written statement is the defendant''s reply."}'),
  ('GK-0298', 'Law, courts and the Constitution', 'Civil procedure', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'A ''decree-holder'' is:', '["the person in whose favour a decree has been passed", "the court clerk who keeps decrees", "the lawyer who drafted the suit", "the person against whom a decree is passed"]', 0, 'Section 2(3) of the CPC defines decree-holder; the other side is the judgment-debtor.', '{"1": "A court record keeper is the ahalmad.", "2": "Lawyers are not decree-holders.", "3": "That person is the judgment-debtor."}'),
  ('GK-0299', 'Law, courts and the Constitution', 'Civil procedure', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Limitation Act 1908; Pakistan Code (pakistancode.gov.pk)', 'The Limitation Act provision that lets a court excuse delay in filing an appeal for ''sufficient cause'' is:', '["Section 3", "Section 151", "Section 11", "Section 5"]', 3, 'Section 5 of the Limitation Act 1908 applies to appeals and applications, not to suits.', '{"0": "Section 3 says suits filed after the limitation period must be dismissed.", "1": "Section 151 of the CPC is inherent powers.", "2": "Section 11 of the CPC is res judicata."}'),
  ('GK-0300', 'Law, courts and the Constitution', 'Criminal law', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'An FIR (First Information Report) of a cognizable offence is recorded under section:', '["497 of the CrPC", "302 of the PPC", "154 of the CrPC", "164 of the CrPC"]', 2, 'The officer in charge of a police station must write down information about a cognizable offence under section 154.', '{"0": "Section 497 deals with bail in non-bailable offences.", "1": "Section 302 PPC is the punishment for qatl-i-amd.", "3": "Section 164 is for recording confessions and statements by a magistrate."}'),
  ('GK-0301', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'A confession before a Magistrate is recorded under section:', '["164 of the CrPC", "144 of the CrPC", "154 of the CrPC", "161 of the CrPC"]', 0, 'A confession to police is not admissible; it must be made before a Magistrate under section 164.', '{"1": "Section 144 allows orders banning gatherings.", "2": "Section 154 is the FIR.", "3": "Section 161 covers police examination of witnesses, which is not a confession."}'),
  ('GK-0302', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'Orders banning public gatherings in an area for a limited time are usually issued under section:', '["124-A of the PPC", "144 of the CrPC", "199 of the Constitution", "154 of the CrPC"]', 1, 'Section 144 lets a magistrate (now usually the government or DC) issue urgent orders to prevent danger or disturbance.', '{"0": "Section 124-A PPC is sedition.", "2": "Article 199 is the High Courts'' writ jurisdiction.", "3": "Section 154 is the FIR."}'),
  ('GK-0303', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'Bail in non-bailable offences is dealt with in section:', '["497 of the CrPC", "302 of the PPC", "164 of the CrPC", "496 of the CrPC"]', 0, 'Under section 497, bail is at the court''s discretion; women, minors and the sick get special consideration.', '{"1": "Section 302 is the punishment for murder.", "2": "Section 164 is for confessions.", "3": "Section 496 covers bailable offences, where bail is a right."}'),
  ('GK-0304', 'Law, courts and the Constitution', 'Criminal law', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'A court can acquit an accused at any stage of a trial if the charge is groundless under sections:', '["302 and 304 of the PPC", "249-A and 265-K of the CrPC", "76 and 106 of the PPC", "154 and 155 of the CrPC"]', 1, 'Section 249-A applies to magistrates'' courts and 265-K to Courts of Session.', '{"0": "These deal with qatl.", "2": "These are the boundaries of the general exceptions in the PPC.", "3": "These deal with information about offences."}'),
  ('GK-0305', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'The punishment for qatl-i-amd (intentional murder) is given in section:', '["302 of the PPC", "420 of the PPC", "489-F of the PPC", "379 of the PPC"]', 0, 'Section 302 PPC provides death or life imprisonment as qisas or ta''zir.', '{"1": "Section 420 is cheating.", "2": "Section 489-F is dishonour of a cheque.", "3": "Section 379 is theft."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0306', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'Dishonestly issuing a cheque that bounces is an offence under section:', '["406 of the PPC", "489-F of the PPC", "420 of the PPC", "302 of the PPC"]', 1, 'Section 489-F was added in 2002 and carries up to three years'' imprisonment or fine or both.', '{"0": "Section 406 is criminal breach of trust.", "2": "Section 420 is the general offence of cheating.", "3": "Section 302 is murder."}'),
  ('GK-0307', 'Law, courts and the Constitution', 'Criminal law', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'The ''general exceptions'' (acts that are not offences, such as private defence) are in the PPC''s sections:', '["378 to 382", "299 to 338", "76 to 106", "1 to 5"]', 2, 'Chapter IV of the PPC covers mistake of fact, accident, infancy, insanity, intoxication, consent and private defence.', '{"0": "These sections deal with theft.", "1": "These sections deal with offences against the human body (qatl and hurt).", "3": "These are introductory sections."}'),
  ('GK-0308', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'In offences of qatl and hurt under the PPC, the ''wali'' who may forgive or compound the offence is:', '["the judge", "the victim''s heirs (or the victim, in hurt)", "the government only", "the investigating officer"]', 1, 'Section 305 PPC defines wali; the court may still punish as ta''zir after compounding in some cases.', '{"0": "The judge decides the case but is not the wali.", "2": "The government becomes wali only when there is no heir.", "3": "The police have no power to compound qisas offences."}'),
  ('GK-0309', 'Law, courts and the Constitution', 'Criminal law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'Criminal conspiracy is defined in the PPC as:', '["any attempt to commit theft", "hiding an offender from police", "one person planning a crime alone", "an agreement between two or more persons to do an illegal act, or a legal act by illegal means"]', 3, 'Section 120-A PPC defines it; section 120-B punishes it.', '{"0": "Attempt is a separate concept.", "1": "Harbouring an offender is a separate offence.", "2": "A conspiracy needs at least two people."}'),
  ('GK-0310', 'Law, courts and the Constitution', 'Contract law', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Contract Act 1872; Pakistan Code (pakistancode.gov.pk)', 'Under the Contract Act 1872, a contract is:', '["an order from a court", "an agreement enforceable by law", "any promise made in writing", "an agreement between friends"]', 1, 'Section 2(h) of the Contract Act 1872.', '{"0": "A court order is a decree, not a contract.", "2": "Writing alone does not make a contract.", "3": "Social agreements usually are not enforceable."}'),
  ('GK-0311', 'Law, courts and the Constitution', 'Contract law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Contract Act 1872; Pakistan Code (pakistancode.gov.pk)', 'An agreement with a minor is, under the law of Pakistan:', '["void", "valid if in writing", "voidable at the minor''s option", "valid if the minor is over 16"]', 0, 'Section 11 requires parties to be of the age of majority; Mohori Bibee held a minor''s agreement void from the start.', '{"1": "Writing does not cure a minor''s lack of capacity.", "2": "Privy Council in Mohori Bibee v. Dharmodas Ghose (1903) held it void, not voidable.", "3": "Majority is 18 under the Majority Act 1875."}'),
  ('GK-0312', 'Law, courts and the Constitution', 'Contract law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Contract Act 1872; Pakistan Code (pakistancode.gov.pk)', 'When consent to a contract is obtained by undue influence, the contract is voidable at the option of:', '["the party whose consent was so obtained", "the court only", "the party who used the influence", "either party"]', 0, 'Section 19A of the Contract Act 1872.', '{"1": "The wronged party chooses; the court gives effect to it.", "2": "The wrongdoer cannot take advantage of his own wrong.", "3": "Only the wronged party can choose to avoid it."}'),
  ('GK-0313', 'Law, courts and the Constitution', 'Contract law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Contract Act 1872; Pakistan Code (pakistancode.gov.pk)', 'Under the Contract Act, an agreement made without consideration is generally:', '["void, subject to a few exceptions", "valid only if oral", "voidable at either party''s option", "always valid"]', 0, 'Section 25 makes it void, except for registered agreements out of natural love and affection, promises to compensate past voluntary acts, and promises to pay time-barred debts.', '{"1": "Oral or written makes no difference here.", "2": "It is void, not voidable.", "3": "Consideration is needed except in the cases section 25 allows."}'),
  ('GK-0314', 'Law, courts and the Constitution', 'Family law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Muslim Family Laws Ordinance 1961; standard nikahnama', '''Talaq-e-tafwid'' means:', '["the husband delegating his right of divorce to the wife", "divorce sought by the wife in return for property", "divorce by mutual consent", "divorce given in anger"]', 0, 'Delegation is usually written in column 18 of the nikahnama in Pakistan.', '{"1": "That is khul''.", "2": "Divorce by mutual consent is mubara''at.", "3": "Anger is not what tafwid means."}'),
  ('GK-0315', 'Law, courts and the Constitution', 'Family law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Code (pakistancode.gov.pk)', 'The law that lists the grounds on which a Muslim wife may seek a court decree dissolving her marriage is the:', '["Contract Act 1872", "Majority Act 1875", "Dissolution of Muslim Marriages Act 1939", "Guardians and Wards Act 1890"]', 2, 'Grounds include the husband''s absence for four years, failure to maintain her for two years, and cruelty.', '{"0": "The Contract Act deals with contracts in general.", "1": "The Majority Act sets the age of majority.", "3": "That Act deals with custody and guardianship of children."}'),
  ('GK-0316', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'The definition ''law is the command of the sovereign backed by a sanction'' was given by:', '["Ronald Dworkin", "H. L. A. Hart", "John Austin", "Jeremy Bentham"]', 2, 'Austin set out his analytical positivism in The Province of Jurisprudence Determined (1832).', '{"0": "Dworkin argued law includes principles, not just commands.", "1": "Hart criticised the command theory.", "3": "Bentham, Austin''s teacher, is best known for utilitarianism."}'),
  ('GK-0317', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', '''The greatest happiness of the greatest number'' is the principle of utility associated with:', '["Jeremy Bentham", "Thomas Aquinas", "John Rawls", "Friedrich Carl von Savigny"]', 0, 'Bentham argued that laws should be judged by whether they increase overall happiness.', '{"1": "Aquinas is a natural law thinker.", "2": "Rawls criticised utilitarianism in A Theory of Justice.", "3": "Savigny founded the historical school."}'),
  ('GK-0318', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'The idea of a ''Grundnorm'' (basic norm) from which all other legal norms draw their validity comes from:', '["Hans Kelsen", "John Austin", "Roscoe Pound", "Montesquieu"]', 0, 'Kelsen''s Pure Theory of Law treats law as a hierarchy of norms resting on a basic norm.', '{"1": "Austin based law on the sovereign''s command.", "2": "Pound wrote of law as social engineering.", "3": "Montesquieu wrote on separation of powers."}'),
  ('GK-0319', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'The Concept of Law, which describes law as a union of primary and secondary rules, was written by:', '["A. V. Dicey", "John Austin", "H. L. A. Hart", "Hans Kelsen"]', 2, 'Hart (1961) introduced the ''rule of recognition'' as the test for what counts as law.', '{"0": "Dicey wrote on the law of the constitution.", "1": "Austin wrote The Province of Jurisprudence Determined.", "3": "Kelsen wrote the Pure Theory of Law."}'),
  ('GK-0320', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'The historical school of law, which held that law grows from the spirit of a people (Volksgeist), was founded by:', '["Roscoe Pound", "Friedrich Carl von Savigny", "Hans Kelsen", "Jeremy Bentham"]', 1, 'Savigny argued that law, like language, develops from a people''s customs rather than being made by a legislator.', '{"0": "Pound led sociological jurisprudence.", "2": "Kelsen developed the pure theory of law.", "3": "Bentham was a utilitarian reformer."}'),
  ('GK-0321', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'Which jurist described law as a tool of ''social engineering''?', '["Thomas Hobbes", "Savigny", "John Austin", "Roscoe Pound"]', 3, 'Pound, Dean of Harvard Law School, founded American sociological jurisprudence.', '{"0": "Hobbes wrote Leviathan on the social contract.", "1": "Savigny saw law as growing from custom.", "2": "Austin defined law as command."}'),
  ('GK-0322', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'A. V. Dicey is best known for explaining which principle of the British constitution?', '["separation of powers", "federalism", "judicial review of statutes", "the rule of law"]', 3, 'In his Law of the Constitution (1885), Dicey explained the rule of law and the sovereignty of Parliament.', '{"0": "Separation of powers is linked to Montesquieu.", "1": "The UK is not a federation.", "2": "UK courts cannot strike down Acts of Parliament."}'),
  ('GK-0323', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Salmond on Jurisprudence; Dias, Jurisprudence', 'In a judgment, the legal principle on which the decision rests, and which binds later courts, is called the:', '["ratio decidendi", "res judicata", "obiter dictum", "per incuriam"]', 0, 'Only the ratio decidendi is binding precedent; obiter dicta may be persuasive.', '{"1": "Res judicata bars the same dispute from being tried again.", "2": "Obiter dicta are remarks in passing and are not binding.", "3": "Per incuriam means a decision made in ignorance of a binding law."}'),
  ('GK-0324', 'Law, courts and the Constitution', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'A decision given ''per incuriam'' is one that:', '["was given in the defendant''s absence", "was made in ignorance of a binding statute or precedent", "was given on the court''s own motion", "was made by consent of the parties"]', 1, 'A per incuriam decision does not bind later courts.', '{"0": "That is an ex parte decision.", "2": "That is suo motu.", "3": "That is a consent decree."}'),
  ('GK-0325', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Ignorantia juris non excusat'' means:', '["let the buyer beware", "ignorance of the law is no excuse", "hear the other side", "no one is above the law"]', 1, 'A person cannot escape liability by saying they did not know the law.', '{"0": "That is caveat emptor.", "2": "That is audi alteram partem.", "3": "That is a statement of the rule of law."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0326', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Nemo judex in causa sua'' means:', '["the act is not guilty unless the mind is guilty", "no one should be a judge in his own cause", "the safety of the people is the supreme law", "no crime without a law"]', 1, 'It is one of the two rules of natural justice; the other is audi alteram partem.', '{"0": "That is actus non facit reum nisi mens sit rea.", "2": "That is salus populi suprema lex.", "3": "That is nullum crimen sine lege."}'),
  ('GK-0327', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Mens rea'' means:', '["a guilty act", "an alibi", "the body of the crime", "a guilty mind"]', 3, 'Most crimes need both actus reus (the act) and mens rea (the intention or knowledge).', '{"0": "A guilty act is actus reus.", "1": "An alibi is a claim of being elsewhere.", "2": "That is corpus delicti."}'),
  ('GK-0328', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Caveat emptor'' means:', '["goods once sold cannot be returned", "the buyer is always right", "let the buyer beware", "let the seller beware"]', 2, 'The buyer is responsible for checking the goods, subject to the seller''s duties under sale-of-goods law.', '{"0": "That is not what the maxim says.", "1": "This is a business slogan, not a legal maxim.", "3": "That would be caveat venditor."}'),
  ('GK-0329', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Locus standi'' means:', '["a stay order", "the right to bring a case before a court", "the place where a crime happened", "the court''s jurisdiction over a place"]', 1, 'A petitioner must show locus standi; Pakistan''s courts relaxed it for public interest cases.', '{"0": "A stay order suspends proceedings.", "2": "That would be locus delicti.", "3": "That is territorial jurisdiction."}'),
  ('GK-0330', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Prima facie'' means:', '["at first sight; on the face of it", "after full trial", "beyond reasonable doubt", "by the court''s own motion"]', 0, 'A prima facie case is one that seems valid unless disproved.', '{"1": "Prima facie is before a full examination.", "2": "That is the criminal standard of proof.", "3": "That is suo motu."}'),
  ('GK-0331', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'An ''ex parte'' order is one passed:', '["with the consent of both parties", "in the absence of the other party", "by a full bench", "after the case is withdrawn"]', 1, 'Courts may proceed ex parte when a duly summoned party fails to appear.', '{"0": "That is a consent order.", "2": "Bench size is not what ex parte refers to.", "3": "A withdrawn case ends without such an order."}'),
  ('GK-0332', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Bona fide'' means:', '["in bad faith", "by law", "for the public good", "in good faith"]', 3, 'A bona fide purchaser is one who buys honestly without notice of a defect in title.', '{"0": "That is mala fide.", "1": "That is de jure.", "2": "That would be pro bono publico."}'),
  ('GK-0333', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'Legal work done free of charge for the public good is called work done:', '["sine die", "pro bono", "ultra vires", "ad hoc"]', 1, 'Pro bono comes from ''pro bono publico'', for the public good.', '{"0": "Sine die means without a fixed date.", "2": "Ultra vires means beyond powers.", "3": "Ad hoc means for a particular purpose."}'),
  ('GK-0334', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'When an assembly is adjourned ''sine die'', it is adjourned:', '["until the next day", "without fixing a date to meet again", "for exactly one week", "because of a lack of quorum"]', 1, 'Sine die is Latin for ''without a day''.', '{"0": "That would be adjourned to a date.", "2": "No fixed period is meant.", "3": "Lack of quorum may cause adjournment, but sine die means no date is set."}'),
  ('GK-0335', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the Islamic Republic of Pakistan, 1973 (as amended)', 'The minimum number of members who must be present for a meeting to conduct business is the:', '["veto", "caucus", "quorum", "majority"]', 2, 'The National Assembly''s quorum is one quarter of its total membership (Article 55).', '{"0": "A veto is a power to block a decision.", "1": "A caucus is a meeting of party members.", "3": "A majority is more than half of those voting."}'),
  ('GK-0336', 'Law, courts and the Constitution', 'Legal terms', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'An ''alibi'' is a defence that the accused:', '["did not intend the result", "was somewhere else when the crime was committed", "acted in self-defence", "was insane at the time"]', 1, 'Alibi is Latin for ''elsewhere''.', '{"0": "That is lack of mens rea.", "2": "That is private defence.", "3": "That is the defence of insanity."}'),
  ('GK-0337', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'A writ of ''mandamus'' directs a public official to:', '["release a person held unlawfully", "show by what authority they hold office", "stop a lower court from exceeding its jurisdiction", "perform a legal duty they have failed to perform"]', 3, 'Mandamus means ''we command''.', '{"0": "That is habeas corpus.", "1": "That is quo warranto.", "2": "That is prohibition."}'),
  ('GK-0338', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'A writ of ''quo warranto'' asks a person:', '["to appear before the court in person", "by what authority they hold a public office", "to perform a public duty", "to produce a detained person"]', 1, 'Quo warranto is used to remove people who hold public office without legal right.', '{"0": "That is a summons.", "2": "That is mandamus.", "3": "That is habeas corpus."}'),
  ('GK-0339', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'A writ of ''certiorari'' is issued to:', '["command an official to do a duty", "quash an order passed without jurisdiction or against law by a lower court or tribunal", "release an illegally detained person", "ask an office-holder to show his authority"]', 1, 'Certiorari reviews a decision already made; prohibition stops proceedings still going on.', '{"0": "That is mandamus.", "2": "That is habeas corpus.", "3": "That is quo warranto."}'),
  ('GK-0340', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Transfer of Property Act 1882; Black''s Law Dictionary; Oxford Dictionary of Law', '''Lis pendens'' refers to:', '["a dismissed suit", "a criminal trial in absence of the accused", "a pending suit, during which the disputed property should not be transferred to defeat the case", "the principle of following precedent"]', 2, 'Section 52 of the Transfer of Property Act 1882 makes such transfers subject to the result of the suit.', '{"0": "Lis pendens is about a suit still pending.", "1": "That is a trial in absentia.", "3": "That is stare decisis."}'),
  ('GK-0341', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', '''Corpus juris'' means:', '["the body of a crime", "the body of a jurist", "produce the body", "a body of law"]', 3, 'Justinian''s Corpus Juris Civilis is the great compilation of Roman law.', '{"0": "That is corpus delicti.", "1": "This is a literal but wrong reading.", "2": "That is habeas corpus."}'),
  ('GK-0342', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Black''s Law Dictionary; Oxford Dictionary of Law', 'In Pakistan''s courts, the ''ahalmad'' is the official who:', '["presides over the court", "serves summons on parties", "keeps the records and files of the court", "argues cases for the state"]', 2, 'The ahalmad (record keeper) maintains case files and produces them before the judge.', '{"0": "The judge presides.", "1": "Process servers serve summons.", "3": "Public prosecutors argue for the state."}'),
  ('GK-0343', 'Law, courts and the Constitution', 'Legal terms', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Qanun-e-Shahadat Order 1984; Pakistan Code (pakistancode.gov.pk)', 'In a trial, leading questions (questions that suggest the answer) may normally be asked during:', '["framing of charges", "re-examination", "cross-examination", "examination-in-chief"]', 2, 'Under the Qanun-e-Shahadat Order 1984, leading questions are allowed in cross-examination.', '{"0": "Charges are framed by the court; no questioning of witnesses happens then.", "1": "Leading questions are not allowed in re-examination without permission.", "3": "Leading questions are not allowed here if objected to, except on formal points."}'),
  ('GK-0344', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Civil Procedure 1908; Pakistan Code (pakistancode.gov.pk)', 'The Code of Civil Procedure used in Pakistan dates from:', '["1898", "1860", "1872", "1908"]', 3, 'The CPC 1908 governs procedure in civil courts.', '{"0": "1898 is the year of the Code of Criminal Procedure.", "1": "1860 is the year of the Penal Code.", "2": "1872 is the year of the Contract Act."}'),
  ('GK-0345', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Code of Criminal Procedure 1898; Pakistan Penal Code 1860; Pakistan Code (pakistancode.gov.pk)', 'The Code of Criminal Procedure used in Pakistan dates from:', '["1898", "1860", "1984", "1908"]', 0, 'The CrPC 1898 governs investigation, trial and appeals in criminal cases.', '{"1": "1860 is the Pakistan Penal Code.", "2": "1984 is the Qanun-e-Shahadat Order.", "3": "1908 is the CPC (civil procedure)."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0346', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Contract Act 1872; Pakistan Code (pakistancode.gov.pk)', 'The Contract Act in force in Pakistan was enacted in:', '["1872", "1882", "1908", "1930"]', 0, 'The Contract Act 1872 was drafted for British India and still applies in Pakistan.', '{"1": "1882 is the Transfer of Property Act.", "2": "1908 is the CPC and the Limitation Act.", "3": "1930 is the Sale of Goods Act."}'),
  ('GK-0347', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Code (pakistancode.gov.pk)', 'Pakistan''s main law against terrorism, which set up special Anti-Terrorism Courts, is the Anti-Terrorism Act of:', '["1860", "1979", "2016", "1997"]', 3, 'The Anti-Terrorism Act 1997 was passed under Nawaz Sharif''s second government.', '{"0": "1860 is the Penal Code.", "1": "1979 is the year of the Hudood Ordinances.", "2": "2016 is the Prevention of Electronic Crimes Act."}'),
  ('GK-0348', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Code (pakistancode.gov.pk)', 'The National Accountability Bureau (NAB) was set up under the National Accountability Ordinance of:', '["1985", "1999", "2008", "1997"]', 1, 'General Musharraf''s government promulgated the ordinance in November 1999.', '{"0": "1985 is the year of the Eighth Amendment.", "2": "2008 is not the year NAB was set up.", "3": "1997 saw the Ehtesab Act, which NAB replaced."}'),
  ('GK-0349', 'Law, courts and the Constitution', 'Major laws', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Pakistan Code (pakistancode.gov.pk)', 'Pakistan''s main cybercrime law is the:', '["Prevention of Electronic Crimes Act 2016", "Anti-Terrorism Act 1997", "Telegraph Act 1885", "Electronic Transactions Ordinance 2002"]', 0, 'PECA 2016 defines offences such as unauthorised access to data and online harassment; the FIA investigates them.', '{"1": "The ATA deals with terrorism.", "2": "The Telegraph Act is an old communications law.", "3": "The 2002 ordinance gave legal recognition to electronic documents."}'),
  ('GK-0350', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The power of US courts to strike down laws that conflict with the Constitution was established in:', '["Roe v. Wade (1973)", "Marbury v. Madison (1803)", "Brown v. Board of Education (1954)", "Miranda v. Arizona (1966)"]', 1, 'Chief Justice John Marshall held that it is the duty of the courts ''to say what the law is''.', '{"0": "Roe concerned abortion rights and was overturned in 2022.", "2": "Brown ended racial segregation in public schools.", "3": "Miranda gave suspects the right to be told of their rights."}'),
  ('GK-0351', 'Law, courts and the Constitution', 'Other constitutions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The final interpreter of the US Constitution is the:', '["Speaker of the House", "President", "Senate", "Supreme Court"]', 3, 'Since Marbury v. Madison, the US Supreme Court has had the final word on what the Constitution means.', '{"0": "The Speaker leads the House of Representatives.", "1": "The President executes the laws, but the courts interpret the Constitution.", "2": "The Senate confirms judges but does not interpret the Constitution."}'),
  ('GK-0352', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The first ten amendments to the US Constitution are together called the:', '["Articles of Confederation", "Federalist Papers", "Declaration of Independence", "Bill of Rights"]', 3, 'The Bill of Rights was ratified in 1791.', '{"0": "The Articles were the earlier constitution replaced in 1789.", "1": "The Federalist Papers were essays supporting the Constitution.", "2": "The Declaration was made in 1776."}'),
  ('GK-0353', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The US Constitution limits a President to two elected terms under its:', '["1st Amendment", "26th Amendment", "22nd Amendment", "14th Amendment"]', 2, 'The 22nd Amendment was ratified in 1951 after Franklin Roosevelt won four elections.', '{"0": "The 1st Amendment protects speech, religion and the press.", "1": "The 26th Amendment set the voting age at 18.", "3": "The 14th Amendment guarantees equal protection."}'),
  ('GK-0354', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'How many electoral votes are there in the US Electoral College?', '["270", "435", "100", "538"]', 3, '538 = 435 representatives + 100 senators + 3 for Washington, D.C.', '{"0": "270 is the number needed to win, not the total.", "1": "435 is the number of voting members of the House of Representatives.", "2": "100 is the number of senators."}'),
  ('GK-0355', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'In the US Senate, the Vice President:', '["votes on every bill", "presides and votes only to break a tie", "can veto bills", "has no role at all"]', 1, 'Article I, section 3 of the US Constitution.', '{"0": "The Vice President votes only when there is a tie.", "2": "Only the President can veto bills.", "3": "The Constitution makes the Vice President President of the Senate."}'),
  ('GK-0356', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'Which US President took office by succession and was never elected as President or Vice President?', '["Gerald Ford", "Lyndon Johnson", "Harry Truman", "Richard Nixon"]', 0, 'Ford was appointed Vice President in 1973 and became President when Nixon resigned in 1974.', '{"1": "Johnson was elected Vice President in 1960 and President in 1964.", "2": "Truman was elected Vice President in 1944 and President in 1948.", "3": "Nixon was elected twice as Vice President and twice as President."}'),
  ('GK-0357', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'Under the US Constitution, powers not given to the federal government are reserved to the states or the people by the:', '["2nd Amendment", "5th Amendment", "10th Amendment", "19th Amendment"]', 2, 'Residuary powers in the USA lie with the states.', '{"0": "The 2nd Amendment concerns the right to bear arms.", "1": "The 5th Amendment protects against self-incrimination.", "3": "The 19th Amendment gave women the vote."}'),
  ('GK-0358', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'Since 2009, the highest court of appeal in the United Kingdom has been the:', '["House of Lords", "Privy Council", "Supreme Court of the United Kingdom", "Court of Appeal"]', 2, 'The Constitutional Reform Act 2005 created the UK Supreme Court, which began work in October 2009.', '{"0": "The Appellate Committee of the House of Lords was the final court until 2009.", "1": "The Privy Council hears appeals from some Commonwealth countries, not UK cases generally.", "3": "The Court of Appeal sits below the Supreme Court."}'),
  ('GK-0359', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The British constitution is described as:', '["federal", "uncodified, made up of statutes, conventions and case law", "rigid, needing a referendum to amend", "a single written document of 1689"]', 1, 'Because Parliament is sovereign, any Act can change the UK''s constitutional arrangements.', '{"0": "The UK is a unitary state with devolved governments.", "2": "Parliament can change constitutional law by ordinary Acts.", "3": "The Bill of Rights 1689 is one part, not the whole constitution."}'),
  ('GK-0360', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The Parliament Acts of 1911 and 1949 reduced the powers of the:', '["House of Commons", "Monarch", "House of Lords", "Prime Minister"]', 2, 'The Lords can now only delay most bills for about a year and money bills for one month.', '{"0": "The Acts strengthened the Commons.", "1": "The Acts dealt with the Lords'' power to delay bills.", "3": "The Acts did not deal with the Prime Minister''s powers."}'),
  ('GK-0361', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'Who is generally regarded as Britain''s first Prime Minister?', '["Sir Robert Walpole", "Winston Churchill", "Benjamin Disraeli", "William Pitt the Younger"]', 0, 'Walpole led the government from 1721 to 1742.', '{"1": "Churchill led Britain in the Second World War.", "2": "Disraeli was Prime Minister in the 1860s and 1870s.", "3": "Pitt was the youngest Prime Minister, in 1783."}'),
  ('GK-0362', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The Glorious Revolution in England, which led to the Bill of Rights 1689, took place in:', '["1649", "1215", "1832", "1688"]', 3, 'James II was replaced by William and Mary, and Parliament''s supremacy was confirmed.', '{"0": "1649 is when Charles I was executed.", "1": "1215 is the year of Magna Carta.", "2": "1832 is the year of the Great Reform Act."}'),
  ('GK-0363', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'Magna Carta (1215) was sealed by which English king?', '["Edward I", "King John", "Richard I", "Henry VIII"]', 1, 'The barons forced King John to seal the charter at Runnymede.', '{"0": "Edward I ruled later in the 13th century.", "2": "Richard the Lionheart was John''s elder brother and died in 1199.", "3": "Henry VIII ruled in the 16th century."}'),
  ('GK-0364', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The constitution of France''s Fifth Republic (1958) was adopted by:', '["a royal decree", "a referendum", "an Act of Parliament", "a decision of the Constitutional Council"]', 1, 'Drafted under de Gaulle and Michel Debré, it was approved by about 80% of voters on 28 September 1958.', '{"0": "France had no king in 1958.", "2": "It was approved by the voters in September 1958.", "3": "The Council was created by this constitution."}'),
  ('GK-0365', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'France is especially associated with a separate system of courts for disputes with the state, known as:', '["customary law", "common law", "Islamic law", "administrative law (droit administratif)"]', 3, 'The Conseil d''État heads France''s administrative courts.', '{"0": "Custom is not France''s distinctive feature here.", "1": "Common law is the English tradition.", "2": "France does not apply Islamic law."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'General Knowledge', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('GK-0366', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The Constitution of India came into force on:', '["15 August 1947", "26 November 1949", "2 October 1950", "26 January 1950"]', 3, '26 January is celebrated as Republic Day in India.', '{"0": "15 August 1947 is India''s independence day.", "1": "26 November 1949 is when it was adopted.", "2": "2 October is Gandhi''s birthday."}'),
  ('GK-0367', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The chairman of the drafting committee of the Indian Constitution was:', '["B. R. Ambedkar", "Jawaharlal Nehru", "Sardar Patel", "Rajendra Prasad"]', 0, 'Ambedkar is often called the chief architect of the Indian Constitution.', '{"1": "Nehru was Prime Minister and moved the Objectives Resolution.", "2": "Patel led the integration of princely states.", "3": "Prasad was President of the Constituent Assembly."}'),
  ('GK-0368', 'Law, courts and the Constitution', 'Other constitutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: Constitution of the United States; UK Parliament and Supreme Court websites; Constitution of France (1958); Constitution of India', 'The Soviet Union consisted of how many union republics when it broke up in 1991?', '["15", "50", "20", "12"]', 0, 'The 15 republics, including Russia, Ukraine and Kazakhstan, became independent states.', '{"1": "50 is the number of US states.", "2": "There were 15 republics.", "3": "There were 15 republics."}'),
  ('GK-0369', 'International organisations and treaties', 'International law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter; Statute of the ICJ; UNCLOS 1982; Malcolm Shaw, International Law', 'The International Court of Justice has how many judges?', '["15", "5", "9", "18"]', 0, 'ICJ judges are elected by the UN General Assembly and Security Council for nine-year terms.', '{"1": "5 is the number of permanent members of the Security Council.", "2": "9 is the number of US Supreme Court justices.", "3": "18 is the number of judges of the International Criminal Court."}'),
  ('GK-0370', 'International organisations and treaties', 'International law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter; Statute of the ICJ; UNCLOS 1982; Malcolm Shaw, International Law', 'The International Criminal Court, which tries individuals for genocide and war crimes, was created by the:', '["Treaty of Versailles", "UN Charter", "Geneva Conventions", "Rome Statute (1998)"]', 3, 'The ICC sits in The Hague and began work in 2002; Pakistan is not a party.', '{"0": "Versailles ended the First World War.", "1": "The UN Charter created the ICJ, not the ICC.", "2": "The Geneva Conventions set the laws of war."}'),
  ('GK-0371', 'International organisations and treaties', 'International law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter; Statute of the ICJ; UNCLOS 1982; Malcolm Shaw, International Law', 'The Vienna Convention of 1961 deals with:', '["the law of the sea", "the law of treaties", "refugees", "diplomatic relations and immunity"]', 3, 'It protects diplomats from arrest and embassies from entry without consent.', '{"0": "That is UNCLOS 1982.", "1": "The law of treaties is the Vienna Convention of 1969.", "2": "Refugees are covered by the Refugee Convention of 1951."}'),
  ('GK-0372', 'International organisations and treaties', 'International law', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter; Statute of the ICJ; UNCLOS 1982; Malcolm Shaw, International Law', 'A diplomat declared ''persona non grata'' is:', '["appointed to head an embassy", "no longer acceptable to the host country and must leave", "given full honours", "made an honorary citizen"]', 1, 'Article 9 of the Vienna Convention lets a state declare any diplomat persona non grata without giving reasons.', '{"0": "Persona non grata ends a diplomat''s posting.", "2": "It is the opposite of an honour.", "3": "It has nothing to do with citizenship."}'),
  ('GK-0373', 'International organisations and treaties', 'International law', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, General Knowledge. Checked against: UN Charter; Statute of the ICJ; UNCLOS 1982; Malcolm Shaw, International Law', 'The four Geneva Conventions of 1949 deal with:', '["climate change", "diplomatic immunity", "the protection of the wounded, prisoners of war and civilians in armed conflict", "international trade"]', 2, 'They form the core of international humanitarian law; the ICRC helps supervise them.', '{"0": "That is the UNFCCC and the Paris Agreement.", "1": "That is the Vienna Convention of 1961.", "3": "That is the WTO agreements."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'lat', id, subject, chapter FROM questions WHERE id LIKE 'GK-%';

INSERT INTO question_counters (prefix, n) VALUES ('GK', 373) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 373);

-- Pakistan Studies PST-0107 onwards

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0107', 'Ancient and Muslim rule in South Asia', 'Indus Valley', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Indus Valley Civilisation is best known for its:', '["Stone temples", "Iron weapons", "Written history", "Town planning and drainage"]', 3, 'Indus cities had grid streets, baked-brick houses and covered drains.', '{"0": "No large temples have been found.", "1": "The Indus people did not use iron.", "2": "Their script has not been read."}'),
  ('PST-0108', 'Ancient and Muslim rule in South Asia', 'Indus Valley', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The script of the Indus Valley people:', '["Was read by James Prinsep", "Was Sanskrit", "Has not yet been deciphered", "Was Persian"]', 2, 'Short inscriptions on seals survive, but no one has read the Indus script.', '{"0": "Prinsep read the Brahmi script of Ashoka.", "1": "Sanskrit came later, with the Vedic people.", "3": "Persian is much later."}'),
  ('PST-0109', 'Ancient and Muslim rule in South Asia', 'Indus Valley', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Indus Valley people did NOT use:', '["Gold", "Copper", "Bronze", "Iron"]', 3, 'The Indus Civilisation was a Bronze Age culture; iron came to the region later.', '{"0": "They made gold jewellery.", "1": "They used copper tools.", "2": "They made bronze figures, like the Dancing Girl."}'),
  ('PST-0110', 'Ancient and Muslim rule in South Asia', 'Indus Valley', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Lothal, an Indus Valley site with a dockyard, is in:', '["Punjab, Pakistan", "Gujarat, India", "Sindh", "Balochistan"]', 1, 'Lothal in Gujarat had a brick dock, showing sea trade.', '{"0": "Harappa is in Punjab.", "2": "Mohenjo-daro is in Sindh.", "3": "Mehrgarh is in Balochistan."}'),
  ('PST-0111', 'Ancient and Muslim rule in South Asia', 'Muslim conquest', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Which region is called Bab-ul-Islam (Gateway of Islam) in South Asia?', '["Sindh", "Punjab", "Bengal", "Kashmir"]', 0, 'Sindh, conquered by Muhammad bin Qasim in 712, was where Islam first took root in the subcontinent.', '{"1": "Islam reached Punjab later, with the Ghaznavids.", "2": "Bengal was conquered in the 13th century.", "3": "Islam spread in Kashmir in the 14th century."}'),
  ('PST-0112', 'Ancient and Muslim rule in South Asia', 'Muslim conquest', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Muhammad bin Qasim was recalled from Sindh by Caliph:', '["Hisham bin Abdul Malik", "Walid bin Abdul Malik", "Sulaiman bin Abdul Malik", "Umar bin Abdul Aziz"]', 2, 'The new caliph Sulaiman, an enemy of Hajjaj bin Yusuf, recalled Muhammad bin Qasim in 715.', '{"0": "Hisham ruled later.", "1": "Walid sent the expedition; he died in 715.", "3": "Umar II came to power after Sulaiman."}'),
  ('PST-0113', 'Ancient and Muslim rule in South Asia', 'Muslim conquest', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Muhammad bin Qasim''s conquests reached as far north as:', '["Delhi", "Peshawar", "Multan", "Lahore"]', 2, 'After Sindh, Muhammad bin Qasim conquered Multan, the northern limit of Arab rule.', '{"0": "Delhi was taken in the 12th century.", "1": "Peshawar was not part of his conquest.", "3": "Lahore was taken by the Ghaznavids much later."}'),
  ('PST-0114', 'Ancient and Muslim rule in South Asia', 'Ghaznavids', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Al-Biruni came to India with:', '["Mahmud of Ghazni", "Babur", "Muhammad bin Qasim", "Muhammad Ghori"]', 0, 'Al-Biruni travelled with Mahmud''s campaigns and wrote Kitab al-Hind.', '{"1": "Babur came in the 16th century.", "2": "That was three centuries earlier.", "3": "Ghori came in the late 12th century."}'),
  ('PST-0115', 'Ancient and Muslim rule in South Asia', 'Ghaznavids', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Mahmud of Ghazni won his first major battle in India in 1001, near Peshawar, against:', '["Rana Sanga", "Prithviraj Chauhan", "Raja Jaipal", "Raja Dahir"]', 2, 'Mahmud defeated the Hindu Shahi ruler Jaipal near Peshawar in 1001.', '{"0": "Rana Sanga fought Babur.", "1": "Prithviraj fought Muhammad Ghori.", "3": "Dahir fought Muhammad bin Qasim in 712."}'),
  ('PST-0116', 'Ancient and Muslim rule in South Asia', 'Ghaznavids', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The famous temple at Somnath was destroyed by:', '["Aurangzeb", "Muhammad Ghori", "Mahmud of Ghazni", "Alauddin Khilji"]', 2, 'Mahmud raided Somnath in Gujarat in 1025–26.', '{"0": "This was centuries before the Mughals.", "1": "Ghori did not raid Somnath.", "3": "Alauddin''s army later attacked Gujarat, but Somnath is linked to Mahmud."}'),
  ('PST-0117', 'Ancient and Muslim rule in South Asia', 'Saints', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Kashf-ul-Mahjoob, an early Persian book on Sufism, was written by:', '["Hazrat Mujaddid Alf Thani", "Baba Farid", "Hazrat Ali Hujwiri (Data Ganj Bakhsh)", "Bahauddin Zakariya"]', 2, 'Data Ganj Bakhsh of Lahore wrote Kashf-ul-Mahjoob in the 11th century.', '{"0": "His letters are the Maktubat.", "1": "Baba Farid wrote Punjabi verse.", "3": "He did not write this book."}'),
  ('PST-0118', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The official language of the Delhi Sultanate was:', '["Persian", "Arabic", "Turkish", "Urdu"]', 0, 'Persian was the language of court and government under the Sultans and Mughals.', '{"1": "Arabic was the language of religious learning.", "2": "The rulers were Turks, but Persian was the court language.", "3": "Urdu developed later."}'),
  ('PST-0119', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Khilji dynasty was founded by:', '["Balban", "Jalal-ud-Din Khilji", "Ghiyas-ud-Din Tughlaq", "Alauddin Khilji"]', 1, 'Jalal-ud-Din Khilji took the throne in 1290.', '{"0": "Balban was a Slave dynasty sultan.", "2": "He founded the Tughlaq dynasty.", "3": "Alauddin was his nephew and successor."}'),
  ('PST-0120', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Tughlaq dynasty was founded by:', '["Muhammad bin Tughlaq", "Firoz Shah Tughlaq", "Khizr Khan", "Ghiyas-ud-Din Tughlaq"]', 3, 'Ghiyas-ud-Din Tughlaq founded the dynasty in 1320.', '{"0": "He was the founder''s son.", "1": "Firoz ruled later.", "2": "Khizr Khan founded the Sayyid dynasty."}'),
  ('PST-0121', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Which Sultan, called a ''mixture of opposites'', moved his capital to Daulatabad?', '["Iltutmish", "Alauddin Khilji", "Muhammad bin Tughlaq", "Ibrahim Lodi"]', 2, 'Muhammad bin Tughlaq was learned but erratic; he moved the capital and issued token copper coins.', '{"0": "Iltutmish completed the Qutb Minar.", "1": "Alauddin is known for market controls.", "3": "Ibrahim lost to Babur."}'),
  ('PST-0122', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Lodi dynasty was founded by:', '["Bahlul Lodi", "Khizr Khan", "Sikandar Lodi", "Ibrahim Lodi"]', 0, 'Bahlul Lodi founded the Lodi dynasty in 1451; it ended at Panipat in 1526.', '{"1": "Khizr Khan founded the Sayyids.", "2": "Sikandar was the second Lodi.", "3": "Ibrahim was the last Lodi."}'),
  ('PST-0123', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Qutb Minar in Delhi was completed by:', '["Qutb-ud-Din Aibak", "Alauddin Khilji", "Iltutmish", "Babur"]', 2, 'Aibak began the Qutb Minar; his successor Iltutmish completed it.', '{"0": "Aibak began it, but died before it was finished.", "1": "Alauddin started a larger tower that was never finished.", "3": "Babur came three centuries later."}'),
  ('PST-0124', 'Ancient and Muslim rule in South Asia', 'Delhi Sultanate', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Timur invaded India and sacked Delhi in:', '["1739", "1526", "1206", "1398"]', 3, 'Timur sacked Delhi in December 1398, weakening the Tughlaqs.', '{"0": "1739 is Nadir Shah''s invasion.", "1": "1526 is the First Battle of Panipat.", "2": "1206 is the founding of the Delhi Sultanate."}'),
  ('PST-0125', 'Ancient and Muslim rule in South Asia', 'Mughals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'In 1527 Babur defeated Rana Sanga of Mewar at the Battle of:', '["Panipat", "Tarain", "Haldighati", "Khanwa"]', 3, 'Babur''s victory at Khanwa ended the Rajput challenge to his new empire.', '{"0": "Panipat (1526) was against Ibrahim Lodi.", "1": "Tarain was fought in 1191–92.", "2": "Haldighati (1576) was Akbar''s army against Rana Pratap."}'),
  ('PST-0126', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Babur''s memoirs are known as:', '["Tuzk-e-Jahangiri", "Humayunnama", "Akbarnama", "Tuzk-e-Baburi (Baburnama)"]', 3, 'Babur wrote his memoirs in Chaghatai Turkish.', '{"0": "That is Jahangir''s memoir.", "1": "That was written by Gulbadan Begum.", "2": "The Akbarnama is Abul Fazl''s history of Akbar."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0127', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Humayun was driven out of India in 1540 by:', '["Hemu", "Akbar", "Sher Shah Suri", "Ibrahim Lodi"]', 2, 'Sher Shah Suri defeated Humayun at Chausa (1539) and Kannauj (1540).', '{"0": "Hemu fought Akbar in 1556.", "1": "Akbar was Humayun''s son.", "3": "Ibrahim was defeated by Babur."}'),
  ('PST-0128', 'Ancient and Muslim rule in South Asia', 'Mughals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'In the Second Battle of Panipat (1556), Akbar''s army defeated:', '["Ibrahim Lodi", "Hemu", "Sher Shah Suri", "The Marathas"]', 1, 'Under Bairam Khan''s guidance, Akbar''s forces defeated Hemu in 1556.', '{"0": "Ibrahim lost the First Battle of Panipat.", "2": "Sher Shah died in 1545.", "3": "The Marathas lost the Third Battle of Panipat."}'),
  ('PST-0129', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The young Akbar''s guardian and regent was:', '["Bairam Khan", "Man Singh", "Abul Fazl", "Raja Todar Mal"]', 0, 'Bairam Khan ran the empire for Akbar from 1556 to 1560.', '{"1": "Man Singh was his general.", "2": "Abul Fazl was Akbar''s historian.", "3": "Todar Mal was his revenue minister."}'),
  ('PST-0130', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Fatehpur Sikri was built as a new capital by:', '["Babur", "Jahangir", "Akbar", "Shah Jahan"]', 2, 'Akbar built Fatehpur Sikri near Agra in the 1570s.', '{"0": "Babur did not build it.", "1": "Jahangir did not build it.", "3": "Shah Jahan built Shahjahanabad (Old Delhi)."}'),
  ('PST-0131', 'Ancient and Muslim rule in South Asia', 'Mughals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Emperor Akbar is buried at:', '["Shahdara, Lahore", "Sikandra, near Agra", "Delhi", "Khuldabad"]', 1, 'Akbar''s tomb is at Sikandra, near Agra.', '{"0": "Jahangir is buried at Shahdara.", "2": "Humayun is buried in Delhi.", "3": "Aurangzeb is buried at Khuldabad."}'),
  ('PST-0132', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Emperor Jahangir is buried at:', '["Shahdara, Lahore", "Sikandra", "Delhi", "Agra"]', 0, 'Jahangir''s tomb is at Shahdara Bagh, across the Ravi from Lahore.', '{"1": "Akbar is buried at Sikandra.", "2": "Humayun is buried in Delhi.", "3": "Shah Jahan and Mumtaz Mahal lie in the Taj Mahal, Agra."}'),
  ('PST-0133', 'Ancient and Muslim rule in South Asia', 'Mughals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Red Fort in Delhi was built by:', '["Shah Jahan", "Aurangzeb", "Sher Shah Suri", "Akbar"]', 0, 'Shah Jahan built the Red Fort when he moved his capital to Delhi in 1648.', '{"1": "Aurangzeb built the Badshahi Mosque, Lahore.", "2": "Sher Shah built Rohtas Fort.", "3": "Akbar built the Agra Fort."}'),
  ('PST-0134', 'Ancient and Muslim rule in South Asia', 'Mughals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Mumtaz Mahal''s original name was:', '["Gulbadan Begum", "Arjumand Banu Begum", "Nur Jahan", "Jahanara Begum"]', 1, 'Shah Jahan married Arjumand Banu in 1612 and gave her the title Mumtaz Mahal.', '{"0": "Gulbadan was Babur''s daughter.", "2": "Nur Jahan was Jahangir''s wife.", "3": "Jahanara was Mumtaz Mahal''s daughter."}'),
  ('PST-0135', 'Ancient and Muslim rule in South Asia', 'Later period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The capital of Maharaja Ranjit Singh''s Sikh kingdom was:', '["Delhi", "Multan", "Amritsar", "Lahore"]', 3, 'Ranjit Singh took Lahore in 1799 and made it his capital.', '{"0": "Delhi was under the Mughals and later the British.", "1": "Ranjit Singh conquered Multan, but ruled from Lahore.", "2": "Amritsar is the Sikh holy city, not his capital."}'),
  ('PST-0136', 'Ancient and Muslim rule in South Asia', 'Later period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Nadir Shah of Persia sacked Delhi in:', '["1739", "1857", "1707", "1761"]', 0, 'Nadir Shah sacked Delhi in 1739 and took the Peacock Throne and the Koh-i-Noor.', '{"1": "1857 is the War of Independence.", "2": "1707 is Aurangzeb''s death.", "3": "1761 is the Third Battle of Panipat."}'),
  ('PST-0137', 'Ancient and Muslim rule in South Asia', 'Later period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Third Battle of Panipat (1761) was fought between Ahmad Shah Abdali and the:', '["Mughals", "Sikhs", "British", "Marathas"]', 3, 'Ahmad Shah Abdali crushed the Maratha army at Panipat in 1761.', '{"0": "Abdali was invited partly to help the Mughals.", "1": "Abdali fought the Sikhs on other occasions.", "2": "The British were not at Panipat."}'),
  ('PST-0138', 'Ancient and Muslim rule in South Asia', 'Later period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Battle of Buxar (1764), which confirmed British power in Bengal, was fought against:', '["Siraj-ud-Daulah", "Mir Qasim and his allies", "Tipu Sultan", "Ranjit Singh"]', 1, 'At Buxar the British defeated Mir Qasim, the Nawab of Awadh and Mughal Emperor Shah Alam II.', '{"0": "Siraj lost at Plassey in 1757.", "2": "Tipu fought the British in the south.", "3": "Ranjit Singh never fought the British."}'),
  ('PST-0139', 'Ancient and Muslim rule in South Asia', 'Later period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'Tipu Sultan was martyred in 1799 during the:', '["Third Anglo-Mysore War", "First Anglo-Mysore War", "Battle of Plassey", "Fourth Anglo-Mysore War"]', 3, 'Tipu died defending Seringapatam in May 1799.', '{"0": "Tipu survived it, losing half his kingdom (1792).", "1": "That was fought by Haider Ali (1767–69).", "2": "Plassey was in Bengal in 1757."}'),
  ('PST-0140', 'Ancient and Muslim rule in South Asia', 'Later period', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The Portuguese sailor Vasco da Gama reached India in:', '["1600", "1498", "1526", "1492"]', 1, 'Vasco da Gama reached Calicut in May 1498 by sailing round Africa.', '{"0": "1600 is when the English East India Company was chartered.", "2": "1526 is the Battle of Panipat.", "3": "In 1492 Columbus reached the Americas."}'),
  ('PST-0141', 'Ancient and Muslim rule in South Asia', 'Later period', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: S. M. Ikram, Muslim Civilization in India; Pakistan Studies (compulsory), PTB', 'The ''Doctrine of Lapse'', used to annex Indian states, was introduced by:', '["Lord Dalhousie", "Lord Curzon", "Lord Canning", "Warren Hastings"]', 0, 'Under Dalhousie (1848–56), states whose rulers died without a natural heir were taken over.', '{"1": "Curzon partitioned Bengal.", "2": "Canning was Governor-General in 1857.", "3": "Hastings was the first Governor-General."}'),
