  ('PST-0178', 'After 1857 and the Pakistan Movement', 'Early politics', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Gandhi–Irwin Pact was signed in:', '["1942", "1919", "1931", "1928"]', 2, 'Gandhi and Viceroy Irwin agreed in March 1931; Gandhi then attended the second Round Table Conference.', '{"0": "1942 was Quit India.", "1": "1919 was the year of Jallianwala Bagh.", "3": "1928 was the year of the Nehru Report."}'),
  ('PST-0179', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'Chaudhry Rahmat Ali''s 1933 pamphlet that first used the name ''Pakstan'' was titled:', '["Thoughts on Pakistan", "Pakistan or the Partition of India", "The Indian Musalmans", "Now or Never"]', 3, '''Now or Never; Are We to Live or Perish For Ever?'' was issued from Cambridge on 28 January 1933.', '{"0": "That is Ambedkar''s earlier title.", "1": "That is a book by Dr B. R. Ambedkar.", "2": "That is W. W. Hunter''s book."}'),
  ('PST-0180', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Pirpur Report (1938) of the Muslim League listed complaints against:', '["The British Viceroy", "The Unionist Party", "The Princely States", "Congress ministries"]', 3, 'The Raja of Pirpur''s report described the treatment of Muslims under the 1937 Congress governments.', '{"0": "The report was about provincial governments.", "1": "The report was about Congress rule.", "2": "The report was about Congress-ruled provinces."}'),
  ('PST-0181', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'At the Lahore session of 1940, the Pakistan Resolution was seconded from Punjab by:', '["Sir Sikandar Hayat Khan", "Allama Iqbal", "Maulana Zafar Ali Khan", "A. K. Fazlul Haq"]', 2, 'Maulana Zafar Ali Khan of Punjab was among those who seconded the resolution.', '{"0": "Sikandar did not second the resolution.", "1": "Iqbal died in 1938.", "3": "Fazlul Haq moved it."}'),
  ('PST-0182', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'Quaid-e-Azam was called the ''Ambassador of Hindu–Muslim Unity'' by:', '["Sarojini Naidu", "Mahatma Gandhi", "Maulana Muhammad Ali Jauhar", "Allama Iqbal"]', 0, 'Sarojini Naidu used this phrase for Jinnah after the Lucknow Pact of 1916.', '{"1": "Gandhi did not give this title.", "2": "Jauhar did not give this title.", "3": "Iqbal wrote to Jinnah, but the title is Naidu''s."}'),
  ('PST-0183', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Khaksar Tehreek was founded by:', '["Allama Inayatullah Khan Mashriqi", "Maulana Maududi", "Chaudhry Rahmat Ali", "Khan Abdul Ghaffar Khan"]', 0, 'Allama Mashriqi founded the Khaksar movement in 1931.', '{"1": "Maududi founded Jamaat-e-Islami.", "2": "Rahmat Ali founded the Pakistan National Movement.", "3": "He founded the Khudai Khidmatgar."}'),
  ('PST-0184', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Cripps Mission came to India in:', '["1945", "1928", "1942", "1946"]', 2, 'Sir Stafford Cripps brought proposals in March 1942; both parties rejected them.', '{"0": "1945 was the Simla Conference.", "1": "1928 was the Simon Commission.", "3": "1946 was the Cabinet Mission."}'),
  ('PST-0185', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Cabinet Mission of 1946 was headed by:', '["Lord Wavell", "A. V. Alexander", "Lord Pethick-Lawrence", "Sir Stafford Cripps"]', 2, 'Secretary of State Lord Pethick-Lawrence led the three-member mission.', '{"0": "Wavell was the Viceroy.", "1": "Alexander was a member, not the head.", "3": "Cripps was a member, not the head."}'),
  ('PST-0186', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Simla Conference of 1945 was called by Viceroy:', '["Lord Wavell", "Lord Irwin", "Lord Mountbatten", "Lord Linlithgow"]', 0, 'Wavell''s Simla Conference (June–July 1945) failed over who would nominate Muslim members.', '{"1": "Irwin was Viceroy from 1926 to 1931.", "2": "Mountbatten came in 1947.", "3": "Linlithgow left in 1943."}')
) AS s
