INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0187', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'In the 1945–46 elections to the Central Legislative Assembly, the Muslim League won:', '["All general seats", "All 30 Muslim seats", "About half the Muslim seats", "No seats"]', 1, 'The League won every Muslim seat in the centre, proving it spoke for Indian Muslims.', '{"0": "General seats went mostly to Congress.", "2": "It won every one of them.", "3": "It swept the Muslim seats."}'),
  ('PST-0188', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The last Governor of undivided Punjab was:', '["Sir Michael O''Dwyer", "Sir Francis Mudie", "Sir Evan Jenkins", "Sir George Cunningham"]', 2, 'Sir Evan Jenkins governed Punjab from 1946 until partition.', '{"0": "O''Dwyer governed Punjab in 1919.", "1": "Mudie was the first Governor of West Punjab.", "3": "Cunningham governed NWFP."}'),
  ('PST-0189', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'Sindh was separated from the Bombay Presidency in:', '["1936", "1947", "1919", "1906"]', 0, 'Sindh became a separate province on 1 April 1936.', '{"1": "Sindh was already a province before partition.", "2": "That was too early.", "3": "That was too early."}'),
  ('PST-0190', 'After 1857 and the Pakistan Movement', 'Road to Pakistan', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: I. H. Qureshi, The Struggle for Pakistan; K. K. Aziz, The Making of Pakistan', 'The Radcliffe Award, fixing the Punjab and Bengal boundaries, was made public on:', '["15 July 1947", "17 August 1947", "14 August 1947", "3 June 1947"]', 1, 'The boundary award was published two days after independence.', '{"0": "That was before the award was complete.", "2": "Pakistan was created before the award was announced.", "3": "3 June was the partition plan."}'),
  ('PST-0191', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The first meeting of Pakistan''s Constituent Assembly on 10 August 1947 was chaired by:', '["Jogendra Nath Mandal", "Sir Zafarullah Khan", "Quaid-e-Azam", "Liaquat Ali Khan"]', 0, 'Jogendra Nath Mandal chaired the opening sitting; he became Pakistan''s first Law Minister.', '{"1": "He was not the chair.", "2": "Jinnah was elected President of the Assembly on 11 August.", "3": "Liaquat was not the chair."}'),
  ('PST-0192', 'Pakistan since 1947', 'Founding years', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan''s first Law Minister was:', '["Sardar Abdur Rab Nishtar", "Malik Ghulam Muhammad", "Jogendra Nath Mandal", "Sir Zafarullah Khan"]', 2, 'Jogendra Nath Mandal, a Scheduled Caste leader from Bengal, was the first Law and Labour Minister.', '{"0": "He was Communications Minister.", "1": "He was Finance Minister.", "3": "He was Foreign Minister."}'),
  ('PST-0193', 'Pakistan since 1947', 'Founding years', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan''s first Finance Minister was:', '["Chaudhry Muhammad Ali", "Liaquat Ali Khan", "I. I. Chundrigar", "Malik Ghulam Muhammad"]', 3, 'Malik Ghulam Muhammad was Finance Minister and later Governor-General.', '{"0": "He was Secretary-General, later Finance Minister.", "1": "Liaquat had been Finance Member in 1946, but was Prime Minister in 1947.", "2": "Chundrigar was Commerce Minister."}'),
  ('PST-0194', 'Pakistan since 1947', 'Founding years', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan''s first Foreign Minister was:', '["Sir Muhammad Zafarullah Khan", "Agha Shahi", "Liaquat Ali Khan", "Zulfikar Ali Bhutto"]', 0, 'Sir Zafarullah Khan was Foreign Minister from 1947 to 1954.', '{"1": "Agha Shahi served in the 1970s.", "2": "Liaquat was Prime Minister.", "3": "Bhutto was Foreign Minister in the 1960s."}'),
  ('PST-0195', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: United Nations', 'Pakistan became a member of the United Nations on:', '["24 October 1945", "23 March 1956", "30 September 1947", "14 August 1947"]', 2, 'Pakistan was admitted to the UN on 30 September 1947; only Afghanistan voted against.', '{"0": "That is when the UN was founded.", "1": "That is when Pakistan became a republic.", "3": "Pakistan had to apply and be admitted."}'),
  ('PST-0196', 'Pakistan since 1947', 'Founding years', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Quaid-e-Azam died on:', '["14 August 1948", "11 September 1948", "16 October 1951", "25 December 1948"]', 1, 'Quaid-e-Azam died in Karachi on 11 September 1948.', '{"0": "He saw the first anniversary of independence.", "2": "That is when Liaquat Ali Khan was assassinated.", "3": "25 December is his birthday."}'),
  ('PST-0197', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The Liaquat–Nehru Pact of April 1950 dealt with:', '["Trade tariffs", "The protection of minorities in both countries", "Kashmir ceasefire", "Sharing of river waters"]', 1, 'The pact gave guarantees to minorities after riots in Bengal.', '{"0": "It was about minorities.", "2": "That was the Karachi Agreement, 1949.", "3": "That was the Indus Waters Treaty, 1960."}'),
  ('PST-0198', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'In 1950 Liaquat Ali Khan made his first official foreign visit, choosing:', '["The United States", "Britain", "China", "The Soviet Union"]', 0, 'Liaquat''s 1950 tour of the USA set Pakistan''s early pro-Western course.', '{"1": "He chose the United States.", "2": "He did not visit China.", "3": "He accepted, then dropped, a Soviet invitation."}'),
  ('PST-0199', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The ''Rawalpindi Conspiracy'' of 1951 was a plot to overthrow the government, involving army officers and the poet:', '["Faiz Ahmed Faiz", "Habib Jalib", "Ahmad Faraz", "Josh Malihabadi"]', 0, 'Faiz was jailed for four years over the Rawalpindi Conspiracy case.', '{"1": "Jalib was jailed in other years.", "2": "Faraz was much younger.", "3": "Josh was not involved."}'),
  ('PST-0200', 'Pakistan since 1947', 'Founding years', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The first Constituent Assembly was dissolved on 24 October 1954 by Governor-General:', '["Iskander Mirza", "Ayub Khan", "Khawaja Nazimuddin", "Ghulam Muhammad"]', 3, 'Ghulam Muhammad dissolved the Assembly; the Federal Court upheld him in the Tamizuddin case.', '{"0": "Mirza became Governor-General in 1955.", "1": "Ayub took power in 1958.", "2": "Nazimuddin had been dismissed as PM in 1953."}'),
  ('PST-0201', 'Pakistan since 1947', 'Founding years', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The One Unit scheme, merging the provinces of West Pakistan, came into effect in:', '["1947", "1955", "1970", "1962"]', 1, 'One Unit was created on 14 October 1955 to balance East Pakistan.', '{"0": "Provinces were separate at independence.", "2": "1970 is when One Unit was abolished.", "3": "One Unit already existed in 1962."}'),
  ('PST-0202', 'Pakistan since 1947', 'Ayub and Yahya', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The Basic Democracies system of local councils was introduced by:', '["Ayub Khan", "Zia-ul-Haq", "Pervez Musharraf", "Zulfikar Ali Bhutto"]', 0, 'Ayub Khan''s Basic Democracies (1959) also served as the electoral college for President.', '{"1": "Zia held non-party elections in 1985.", "2": "Musharraf introduced the 2001 devolution plan.", "3": "Bhutto did not create this system."}'),
  ('PST-0203', 'Pakistan since 1947', 'Ayub and Yahya', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The Muslim Family Laws Ordinance of 1961 was issued under:', '["Yahya Khan", "Ayub Khan", "Liaquat Ali Khan", "Zia-ul-Haq"]', 1, 'The 1961 Ordinance regulated marriage, divorce and polygamy.', '{"0": "Yahya ruled from 1969.", "2": "Liaquat died in 1951.", "3": "Zia issued the Hudood Ordinances."}'),
  ('PST-0204', 'Pakistan since 1947', 'Ayub and Yahya', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'While Islamabad was being built, the interim capital of Pakistan was:', '["Abbottabad", "Rawalpindi", "Karachi", "Lahore"]', 1, 'Government moved to Rawalpindi from 1959 until Islamabad was ready.', '{"0": "Abbottabad was not the capital.", "2": "Karachi was the capital before the move.", "3": "Lahore was never the federal capital."}'),
  ('PST-0205', 'Pakistan since 1947', 'Ayub and Yahya', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The 1965 war between Pakistan and India began on:', '["6 September 1965", "16 December 1965", "23 March 1965", "28 May 1965"]', 0, 'Indian forces crossed the border towards Lahore on 6 September 1965, now Defence Day.', '{"1": "16 December is the 1971 surrender date.", "2": "23 March is Pakistan Day.", "3": "28 May is Youm-e-Takbeer (1998)."}'),
  ('PST-0206', 'Pakistan since 1947', 'Ayub and Yahya', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Major Raja Aziz Bhatti was awarded the Nishan-e-Haider for his bravery in the:', '["1948 Kashmir war", "1965 war", "1971 war", "Kargil conflict"]', 1, 'Major Aziz Bhatti was martyred defending the BRB Canal near Lahore in 1965.', '{"0": "Captain Sarwar was the hero of 1948.", "2": "Several Nishan-e-Haider were awarded in 1971, but not to Aziz Bhatti.", "3": "Kargil heroes include Captain Karnal Sher Khan."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
