FROM (VALUES
  ('PST-0227', 'Pakistan since 1947', 'Security operations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Operation Rah-e-Rast (2009) was carried out in:', '["Swat", "North Waziristan", "Kurram", "Karachi"]', 0, 'The army cleared Swat of militants in Operation Rah-e-Rast in 2009.', '{"1": "North Waziristan saw Zarb-e-Azb.", "2": "Kurram was not the main area of this operation.", "3": "Karachi saw a separate Rangers operation."}'),
  ('PST-0228', 'Pakistan since 1947', 'Security operations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Operation Zarb-e-Azb was launched in June 2014 in:', '["South Waziristan", "North Waziristan", "Swat", "Balochistan"]', 1, 'Zarb-e-Azb began on 15 June 2014 against militants in North Waziristan.', '{"0": "South Waziristan saw Rah-e-Nijat in 2009.", "2": "Swat saw Rah-e-Rast in 2009.", "3": "Zarb-e-Azb was mainly in North Waziristan."}'),
  ('PST-0229', 'Pakistan since 1947', 'Security operations', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Operation Radd-ul-Fasaad, a nationwide drive against militants, was launched in:', '["2014", "2009", "2001", "2017"]', 3, 'Radd-ul-Fasaad was launched on 22 February 2017.', '{"0": "2014 was Zarb-e-Azb.", "1": "2009 was Rah-e-Rast.", "2": "2001 was the start of the Afghan war."}'),
  ('PST-0230', 'Pakistan since 1947', 'Kashmir', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The ruler of Jammu and Kashmir in 1947 was:', '["Ranjit Singh", "Sheikh Abdullah", "Maharaja Hari Singh", "Gulab Singh"]', 2, 'Maharaja Hari Singh signed the disputed accession to India in October 1947.', '{"0": "Ranjit Singh ruled Punjab until 1839.", "1": "Abdullah was a political leader, not the ruler.", "3": "Gulab Singh founded the dynasty in 1846."}'),
  ('PST-0231', 'Pakistan since 1947', 'Kashmir', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Kashmiris observe ''Black Day'' on 27 October because on that day in 1947:', '["The Simla Agreement was signed", "Indian troops landed in Srinagar", "The Maharaja fled to Jammu", "The UN passed its first Kashmir resolution"]', 1, 'Indian forces were flown into Srinagar on 27 October 1947.', '{"0": "That was in 1972.", "2": "He fled earlier, on 25–26 October.", "3": "That was in 1948."}'),
  ('PST-0232', 'Pakistan since 1947', 'Kashmir', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The All Jammu and Kashmir National Conference was founded by:', '["Sardar Ibrahim Khan", "Chaudhry Ghulam Abbas", "Maharaja Hari Singh", "Sheikh Muhammad Abdullah"]', 3, 'Sheikh Abdullah renamed his Muslim Conference the National Conference in 1939.', '{"0": "Sardar Ibrahim was the first President of Azad Kashmir.", "1": "Ghulam Abbas led the Muslim Conference.", "2": "The Maharaja was the ruler."}'),
  ('PST-0233', 'Pakistan since 1947', 'Kashmir', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The Karachi Agreement of July 1949 between Pakistan and India fixed the:', '["Indus water shares", "Rann of Kutch border", "Exchange of prisoners after 1971", "Ceasefire line in Kashmir"]', 3, 'The Karachi Agreement drew the ceasefire line, later the Line of Control.', '{"0": "That was the 1960 treaty.", "1": "That was settled by tribunal in 1968.", "2": "That came under the Simla Agreement."}'),
  ('PST-0234', 'Pakistan since 1947', 'Kashmir', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: United Nations', 'The UN Representative who tried to arrange demilitarisation in Kashmir in 1950 was:', '["Frank Graham", "Trygve Lie", "Kofi Annan", "Sir Owen Dixon"]', 3, 'Australian judge Sir Owen Dixon was UN Representative in 1950.', '{"0": "Graham was the next UN Representative, from 1951.", "1": "Lie was UN Secretary-General.", "2": "Annan was UN Secretary-General decades later."}'),
  ('PST-0235', 'Pakistan since 1947', 'National symbols', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'The music of Pakistan''s national anthem was composed by:', '["Ahmed Ghulamali Chagla", "Mehdi Hassan", "Hafeez Jalandhari", "Nusrat Fateh Ali Khan"]', 0, 'Ahmed G. Chagla composed the tune in 1949; the words came in 1952.', '{"1": "Mehdi Hassan was a ghazal singer.", "2": "Hafeez wrote the words.", "3": "Nusrat was a qawwal."}'),
  ('PST-0236', 'Pakistan since 1947', 'National symbols', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Youm-e-Takbeer, marking Pakistan''s nuclear tests, is observed on:', '["23 March", "14 August", "28 May", "6 September"]', 2, 'Pakistan tested nuclear devices at Chagai on 28 May 1998.', '{"0": "23 March is Pakistan Day.", "1": "14 August is Independence Day.", "3": "6 September is Defence Day."}'),
  ('PST-0237', 'Constitutions of Pakistan', '1956 and 1962', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'The first Constitution of Pakistan came into force on:', '["14 August 1973", "23 March 1956", "8 June 1962", "14 August 1947"]', 1, 'The 1956 Constitution took effect on 23 March 1956 and was abrogated in October 1958.', '{"0": "That is the present Constitution.", "2": "That is the 1962 Constitution.", "3": "Pakistan ran under an adapted 1935 Act until 1956."}'),
  ('PST-0238', 'Constitutions of Pakistan', '1956 and 1962', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'The first President of Pakistan under the 1956 Constitution was:', '["Ayub Khan", "Fazal Elahi Chaudhry", "Ghulam Muhammad", "Iskander Mirza"]', 3, 'Iskander Mirza, the last Governor-General, became the first President in 1956.', '{"0": "Ayub became President in 1958.", "1": "He became President in 1973.", "2": "Ghulam Muhammad was Governor-General."}'),
  ('PST-0239', 'Constitutions of Pakistan', '1956 and 1962', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'Under the 1962 Constitution, Pakistan''s legislature was:', '["Tricameral", "Appointed entirely by the President", "Unicameral", "Bicameral"]', 2, 'The 1962 Constitution had a single National Assembly, elected through the Basic Democrats.', '{"0": "No Pakistani constitution had three houses.", "1": "The Assembly was indirectly elected.", "3": "The 1973 Constitution created a Senate."}'),
  ('PST-0240', 'Constitutions of Pakistan', '1973 Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'The Second Amendment to the 1973 Constitution, passed in 1974, dealt with:', '["The definition of a Muslim", "Merging FATA", "Provincial autonomy", "Removing the President''s power to dissolve the Assembly"]', 0, 'The Second Amendment (1974) declared Ahmadis non-Muslims for constitutional purposes.', '{"1": "That was the 25th Amendment (2018).", "2": "That was the 18th Amendment (2010).", "3": "That was the 13th Amendment (1997)."}'),
  ('PST-0241', 'Constitutions of Pakistan', '1973 Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'The Eighth Amendment of 1985 gave the President the power, under Article 58(2)(b), to:', '["Dissolve the National Assembly", "Declare war", "Appoint judges without consultation", "Amend the Constitution alone"]', 0, 'Article 58(2)(b) let the President dismiss governments; it was used in 1988, 1990, 1993 and 1996.', '{"1": "That is not 58(2)(b).", "2": "That was not the Eighth Amendment''s main change.", "3": "Amendments need Parliament."}'),
  ('PST-0242', 'Constitutions of Pakistan', '1973 Constitution', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'Which amendment of 1997 removed Article 58(2)(b)?', '["Eighth Amendment", "Twenty-first Amendment", "Thirteenth Amendment", "Seventeenth Amendment"]', 2, 'The 13th Amendment (1997) under Nawaz Sharif removed the President''s power to dissolve the Assembly.', '{"0": "The Eighth Amendment created it.", "1": "The 21st Amendment set up military courts.", "3": "The 17th Amendment (2003) restored it."}'),
  ('PST-0243', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'Under the 1973 Constitution, the head of the federal cabinet is the:', '["Prime Minister", "Chairman Senate", "President", "Chief Justice"]', 0, 'Pakistan is a parliamentary federation; the Prime Minister leads the cabinet.', '{"1": "The Chairman presides over the Senate.", "2": "The President is head of state.", "3": "The Chief Justice heads the judiciary."}'),
  ('PST-0244', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'The normal term of the National Assembly is:', '["Five years", "Four years", "Six years", "Three years"]', 0, 'The National Assembly sits for five years from its first meeting unless dissolved earlier (Article 52).', '{"1": "The term is five years.", "2": "Six years is a Senator''s term.", "3": "The term is five years."}'),
  ('PST-0245', 'Constitutions of Pakistan', '1973 Constitution', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Constitution of the Islamic Republic of Pakistan; Hamid Khan, Constitutional and Political History of Pakistan', 'Pakistan''s Parliament (Majlis-e-Shoora) has how many houses?', '["One", "Three", "Four", "Two"]', 3, 'Majlis-e-Shoora consists of the President, the National Assembly and the Senate (Article 50).', '{"0": "There is a Senate and a National Assembly.", "1": "There are only two.", "2": "There are only two."}'),
  ('PST-0246', 'Geography of Pakistan', 'Mountains', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Nanga Parbat lies in which mountain range?', '["Sulaiman", "Karakoram", "Hindu Kush", "Himalaya"]', 3, 'Nanga Parbat (8,126 m) is the western anchor of the Himalaya.', '{"0": "The Sulaiman range is in the south-west.", "1": "K2 is in the Karakoram.", "2": "Tirich Mir is in the Hindu Kush."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
