FROM (VALUES
  ('PST-0247', 'Geography of Pakistan', 'Mountains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Nanga Parbat is the world''s ___ highest mountain.', '["Twelfth", "Fifth", "Ninth", "Second"]', 2, 'At 8,126 m, Nanga Parbat ranks ninth in the world.', '{"0": "Broad Peak is twelfth.", "1": "Makalu is fifth.", "3": "K2 is second."}'),
  ('PST-0248', 'Geography of Pakistan', 'Mountains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'How many of the world''s 14 peaks above 8,000 metres are in Pakistan?', '["Five", "Three", "Two", "Seven"]', 0, 'K2, Nanga Parbat, Gasherbrum I, Broad Peak and Gasherbrum II are in Pakistan.', '{"1": "There are more.", "2": "There are more.", "3": "There are fewer."}'),
  ('PST-0249', 'Geography of Pakistan', 'Mountains', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The highest peak of the Sulaiman Range is:', '["Sakesar", "Tirich Mir", "Rakaposhi", "Takht-e-Sulaiman"]', 3, 'Takht-e-Sulaiman (about 3,487 m) is the top of the Sulaiman Range.', '{"0": "Sakesar is in the Salt Range.", "1": "Tirich Mir is in the Hindu Kush.", "2": "Rakaposhi is in the Karakoram."}'),
  ('PST-0250', 'Geography of Pakistan', 'Mountains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The highest point of the Salt Range is:', '["Margalla Hills", "Sakesar", "Takht-e-Sulaiman", "Tilla Jogian"]', 1, 'Sakesar (about 1,522 m) is the highest peak of the Salt Range.', '{"0": "The Margallas are near Islamabad.", "2": "That is in the Sulaiman Range.", "3": "Tilla Jogian is a lower peak in the range."}'),
  ('PST-0251', 'Geography of Pakistan', 'Mountains', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Margalla Hills near Islamabad are foothills of the:', '["Himalaya", "Karakoram", "Kirthar Range", "Hindu Kush"]', 0, 'The Margallas form part of the Himalayan foothills.', '{"1": "The Karakoram is far to the north.", "2": "The Kirthar is in Sindh.", "3": "The Hindu Kush is to the north-west."}'),
  ('PST-0252', 'Geography of Pakistan', 'Mountains', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Kirthar Range separates the Indus plain of Sindh from:', '["Gilgit-Baltistan", "India", "Punjab", "Balochistan"]', 3, 'The Kirthar Range runs north–south along the Sindh–Balochistan border.', '{"0": "That is in the far north.", "1": "The Kirthar is in the west.", "2": "Punjab lies to the north-east."}'),
  ('PST-0253', 'Geography of Pakistan', 'Passes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Shandur Pass, home of the famous polo festival, links:', '["Dir and Chitral", "Quetta and Sibi", "Peshawar and Kabul", "Chitral and Gilgit"]', 3, 'Shandur (about 3,700 m) connects Chitral with Gilgit.', '{"0": "That is the Lowari Pass.", "1": "That is the Bolan Pass.", "2": "That is the Khyber Pass."}'),
  ('PST-0254', 'Geography of Pakistan', 'Passes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Lowari Pass (now with a tunnel) links Dir with:', '["Kabul", "Swat", "Chitral", "Gilgit"]', 2, 'The Lowari Pass and tunnel connect Upper Dir with Chitral.', '{"0": "Kabul is reached by the Khyber Pass.", "1": "Swat is reached by the Malakand Pass.", "3": "Gilgit is reached from Chitral by Shandur."}'),
  ('PST-0255', 'Geography of Pakistan', 'Passes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Babusar Pass links the Kaghan Valley with:', '["Muzaffarabad", "Swat", "Chitral", "Chilas"]', 3, 'Babusar Top joins the Kaghan Valley to Chilas on the Karakoram Highway.', '{"0": "Muzaffarabad is reached by other roads.", "1": "Swat is not reached by Babusar.", "2": "Chitral is reached by Lowari or Shandur."}'),
  ('PST-0256', 'Geography of Pakistan', 'Passes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Tochi Pass links Bannu with which part of Afghanistan?', '["Kandahar", "Ghazni", "Badakhshan", "Kabul"]', 1, 'The Tochi Pass connects Bannu, through North Waziristan, to Ghazni.', '{"0": "Kandahar is reached via Chaman.", "2": "Badakhshan is in the far north-east.", "3": "Kabul is reached by the Khyber Pass."}'),
  ('PST-0257', 'Geography of Pakistan', 'Passes', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Khunjerab Pass on the Karakoram Highway is known as:', '["Pakistan''s lowest pass", "One of the highest paved border crossings in the world", "The route to Iran", "A pass in Balochistan"]', 1, 'At about 4,693 m, Khunjerab is one of the world''s highest paved border crossings.', '{"0": "It is about 4,700 m high.", "2": "It leads to China.", "3": "It is in Gilgit-Baltistan."}'),
  ('PST-0258', 'Geography of Pakistan', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The River Indus rises in:', '["Kashmir", "Gilgit-Baltistan", "Tibet", "Afghanistan"]', 2, 'The Indus rises in Tibet near Lake Mansarovar.', '{"0": "The Jhelum rises in Kashmir.", "1": "The Indus enters Gilgit-Baltistan from Ladakh.", "3": "The Kabul River rises in Afghanistan."}'),
  ('PST-0259', 'Geography of Pakistan', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The River Indus is also called:', '["Neelum", "Sindhu Nadi only in Punjab", "Abaseen", "Panjnad"]', 2, 'Abaseen means ''father of rivers'' in Pashto.', '{"0": "Neelum is a separate river.", "1": "Its local Pashto name is Abaseen.", "3": "Panjnad is where five rivers meet."}'),
  ('PST-0260', 'Geography of Pakistan', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Panjnad is the place where:', '["The Jhelum and Chenab meet", "The Indus enters the sea", "The Kabul River joins the Indus", "The five rivers of Punjab join before meeting the Indus"]', 3, 'The Jhelum, Chenab, Ravi, Beas and Sutlej combine as the Panjnad and join the Indus near Mithankot.', '{"0": "That is at Trimmu.", "1": "That is near Keti Bandar.", "2": "That is at Attock."}'),
  ('PST-0261', 'Geography of Pakistan', 'Rivers', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The Kabul River joins the Indus at:', '["Kalabagh", "Mithankot", "Thatta", "Attock"]', 3, 'The Kabul River meets the Indus at Attock.', '{"0": "Kalabagh is downstream.", "1": "The Panjnad joins near Mithankot.", "2": "Thatta is near the sea."}'),
  ('PST-0262', 'Geography of Pakistan', 'Rivers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The land between the Jhelum and Chenab rivers is called the:', '["Chaj Doab", "Rechna Doab", "Bari Doab", "Sindh Sagar Doab"]', 0, 'Chaj = CHenab + JhelUM; a doab is land between two rivers.', '{"1": "Rechna Doab lies between the Ravi and Chenab.", "2": "Bari Doab lies between the Beas and Ravi.", "3": "Sindh Sagar Doab lies between the Indus and Jhelum."}'),
  ('PST-0263', 'Geography of Pakistan', 'Rivers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The land between the Ravi and Chenab rivers is called the:', '["Thal", "Chaj Doab", "Bari Doab", "Rechna Doab"]', 3, 'Rechna = RAvi + CheNAb.', '{"0": "Thal lies between the Indus and Jhelum.", "1": "Chaj Doab lies between the Jhelum and Chenab.", "2": "Bari Doab lies between the Beas and Ravi."}'),
  ('PST-0264', 'Geography of Pakistan', 'Lakes', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'The largest natural freshwater lake in Pakistan is:', '["Manchar Lake", "Saiful Muluk", "Hamun-e-Mashkel", "Rawal Lake"]', 0, 'Manchar Lake in Jamshoro district, Sindh, is the largest freshwater lake in Pakistan.', '{"1": "Saiful Muluk is a small mountain lake.", "2": "Hamun-e-Mashkel is a salt lake.", "3": "Rawal Lake is a reservoir."}'),
  ('PST-0265', 'Geography of Pakistan', 'Lakes', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Lake Saiful Muluk is in the:', '["Skardu", "Swat Valley", "Hunza Valley", "Kaghan Valley"]', 3, 'Saiful Muluk is near Naran in the Kaghan Valley.', '{"0": "Skardu has Satpara and Kachura lakes.", "1": "Swat has Mahodand Lake.", "2": "Hunza has Attabad Lake."}'),
  ('PST-0266', 'Geography of Pakistan', 'Lakes', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Hamun-e-Mashkel, a large seasonal salt lake, is in:', '["Gilgit-Baltistan", "Sindh", "Punjab", "Balochistan"]', 3, 'Hamun-e-Mashkel lies in the Kharan–Chagai area near the Iran border.', '{"0": "Its lakes are freshwater mountain lakes.", "1": "Sindh''s big lakes are Manchar and Keenjhar.", "2": "Punjab has Uchhali, a salt lake in the Soon Valley."}')
