  ('PST-0290', 'Economy, resources and culture', 'Minerals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Economic Survey; Pakistan Studies (compulsory), PTB', 'The Saindak project in Chagai is mainly for:', '["Natural gas", "Copper and gold", "Coal", "Iron ore"]', 1, 'Saindak, run with a Chinese company, produces copper with gold and silver.', '{"0": "Gas comes from Sui and elsewhere.", "2": "Coal comes mainly from Thar.", "3": "Iron ore deposits are at Kalabagh and Chiniot."}'),
  ('PST-0291', 'Economy, resources and culture', 'Minerals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Muslim Bagh in Balochistan is known for deposits of:', '["Chromite", "Coal", "Salt", "Copper"]', 0, 'Muslim Bagh (formerly Hindu Bagh) is a major chromite area.', '{"1": "Balochistan''s coal comes from Sor Range and elsewhere.", "2": "Salt is mined in the Salt Range.", "3": "Copper is at Saindak and Reko Diq."}'),
  ('PST-0292', 'Economy, resources and culture', 'Minerals', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Geography, Economy and People (Fazle Karim Khan); Pakistan Bureau of Statistics', 'Pakistan''s famous emeralds are mined mainly in:', '["Hunza", "Chagai", "Swat", "Thar"]', 2, 'Swat''s Mingora mines produce fine emeralds.', '{"0": "Hunza is famous for rubies.", "1": "Chagai has copper and gold.", "3": "Thar has coal."}'),
