  ('PST-0294', 'Economy, resources and culture', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Economic Survey; Pakistan Studies (compulsory), PTB', 'Pakistan''s financial (fiscal) year begins on:', '["1 July", "14 August", "1 January", "1 April"]', 0, 'Pakistan''s fiscal year runs from 1 July to 30 June.', '{"1": "That is Independence Day.", "2": "The calendar year begins on 1 January.", "3": "India''s financial year begins on 1 April."}'),
  ('PST-0295', 'Economy, resources and culture', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Bureau of Statistics', 'The first census of Pakistan was held in:', '["1947", "1961", "1972", "1951"]', 3, 'The first census took place in 1951.', '{"0": "No census was held in 1947.", "1": "1961 was the second census.", "2": "1972 was the third census."}'),
  ('PST-0296', 'Economy, resources and culture', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan''s highest civil award is the:', '["Nishan-e-Haider", "Sitara-e-Imtiaz", "Nishan-e-Pakistan", "Tamgha-e-Basalat"]', 2, 'Nishan-e-Pakistan is the highest civil honour.', '{"0": "Nishan-e-Haider is the highest military gallantry award.", "1": "Sitara-e-Imtiaz is a lower civil award.", "3": "Tamgha-e-Basalat is a military award."}'),
  ('PST-0297', 'Economy, resources and culture', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Pakistan Economic Survey; Pakistan Studies (compulsory), PTB', 'Pakistan''s first Five-Year Plan began in:', '["1978", "1947", "1965", "1955"]', 3, 'The First Five-Year Plan covered 1955–60.', '{"0": "1978 began the fifth plan.", "1": "Planning began later.", "2": "1965 began the third plan."}'),
  ('PST-0298', 'Economy, resources and culture', 'Economy', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: State Bank of Pakistan', 'The first woman Governor of the State Bank of Pakistan was:', '["Hina Rabbani Khar", "Dr Shamshad Akhtar", "Benazir Bhutto", "Fehmida Mirza"]', 1, 'Dr Shamshad Akhtar was SBP Governor from 2006 to 2009.', '{"0": "Khar was Foreign Minister.", "2": "Benazir was Prime Minister.", "3": "Mirza was Speaker of the National Assembly."}'),
