INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Pakistan Studies', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('PST-0307', 'Foreign relations', 'Alliances', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan joined SEATO in:', '["1947", "1955", "1954", "1964"]', 2, 'Pakistan signed the Manila Pact, creating SEATO, in September 1954.', '{"0": "SEATO did not exist then.", "1": "1955 is when Pakistan joined the Baghdad Pact.", "3": "1964 is when RCD was set up."}'),
  ('PST-0308', 'Foreign relations', 'Alliances', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan left CENTO in:', '["1972", "1979", "1989", "1958"]', 1, 'Pakistan withdrew from CENTO in March 1979, after Iran''s revolution.', '{"0": "In 1972 Pakistan left the Commonwealth and SEATO.", "2": "In 1989 Pakistan rejoined the Commonwealth.", "3": "Pakistan was a member in 1958."}'),
  ('PST-0309', 'Foreign relations', 'Alliances', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: Ian Talbot, Pakistan: A New History; Pakistan Studies (compulsory), PTB', 'Pakistan joined the Non-Aligned Movement in:', '["1954", "1979", "2001", "1961"]', 1, 'Pakistan joined NAM at the Havana summit in 1979, after leaving CENTO.', '{"0": "In 1954 Pakistan joined SEATO.", "2": "Pakistan was already a member.", "3": "Pakistan did not join at NAM''s founding."}'),
  ('PST-0310', 'Foreign relations', 'UN', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Pakistan Studies. Checked against: United Nations', 'Sir Zafarullah Khan presided over the UN General Assembly''s 17th session in:', '["1947", "1971", "1962", "1990"]', 2, 'Sir Zafarullah Khan was President of the General Assembly in 1962–63, and later a judge of the ICJ.', '{"0": "Pakistan had just joined the UN.", "1": "1971 was a war year.", "3": "Zafarullah died in 1985."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO bank_questions (bank, question_id, subject, chapter)
SELECT 'lat', id, subject, chapter FROM questions WHERE id LIKE 'PST-%';

INSERT INTO question_counters (prefix, n) VALUES ('PST', 310) ON CONFLICT (prefix) DO UPDATE SET n = max(n, 310);

-- Islamiat ISL-0093 onwards

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0093', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah of the Holy Quran is named after the tribe of the Holy Prophet (PBUH)?', '["Al-Ahzab", "Al-Hujurat", "Quraysh", "Saba"]', 2, 'Surah Quraysh (106) reminds the Quraysh of Allah''s favours: safe winter and summer trade journeys, food and security.', '{"0": "Al-Ahzab is named after the allied tribes that besieged Madinah.", "1": "Al-Hujurat is named after the private rooms of the Holy Prophet (PBUH).", "3": "Saba is named after the ancient kingdom of Sheba in Yemen."}'),
  ('ISL-0094', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah is known as Umm-ul-Kitab (the Mother of the Book)?', '["Yasin", "Ar-Rahman", "Al-Fatihah", "Al-Ikhlas"]', 2, 'Al-Fatihah sums up the whole message of the Quran and is recited in every rak''ah, so it is called Umm-ul-Kitab.', '{"0": "Yasin is called the heart of the Quran.", "1": "Ar-Rahman is called the bride of the Quran.", "3": "Al-Ikhlas is said to equal one third of the Quran."}'),
  ('ISL-0095', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Surah Al-Ahzab takes its name from:', '["the Battle of Badr", "the conquest of Makkah", "the allied tribes who besieged Madinah in the Battle of the Ditch", "the Treaty of Hudaybiyyah"]', 2, '''Al-Ahzab'' means ''the confederates'', the tribes that joined to attack Madinah in 5 AH.', '{"0": "Badr is the subject of Surah Al-Anfal.", "1": "Surah An-Nasr is linked with the conquest of Makkah.", "3": "Surah Al-Fath was revealed after Hudaybiyyah."}'),
  ('ISL-0096', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'In which surah is the Holy Prophet (PBUH) foretold by the name ''Ahmad''?', '["Al-Fath", "Al-Ahzab", "Muhammad", "As-Saff"]', 3, 'In As-Saff 61:6 Hazrat Isa (AS) gives glad tidings of a messenger after him ''whose name is Ahmad''.', '{"0": "Al-Fath names him ''Muhammad'' (48:29).", "1": "Al-Ahzab 33:40 calls him ''Muhammad'', the Seal of the Prophets.", "2": "Surah Muhammad uses the name ''Muhammad'' (47:2)."}'),
  ('ISL-0097', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The name ''Muhammad'' appears in the Holy Quran how many times?', '["Four", "Seven", "Two", "Ten"]', 0, 'The name Muhammad appears four times: Al-Imran 3:144, Al-Ahzab 33:40, Muhammad 47:2 and Al-Fath 48:29.', '{"1": "There are four places, not seven.", "2": "It appears in 3:144, 33:40, 47:2 and 48:29, which is more than two.", "3": "There are four places, not ten."}'),
  ('ISL-0098', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah repeats the verse ''Which, then, of the favours of your Lord will you deny?''', '["Al-Mulk", "Al-Qamar", "Al-Waqi''ah", "Ar-Rahman"]', 3, 'Ar-Rahman (55) repeats this verse 31 times, which is why it is called the bride (Arus) of the Quran.', '{"0": "Al-Mulk is about Allah''s control over creation.", "1": "Al-Qamar repeats a different verse about the Quran being made easy to remember.", "2": "Al-Waqi''ah describes the Day of Judgement and the three groups of people."}'),
  ('ISL-0099', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The story of the People of the Cave (Ashab-e-Kahf) is told in Surah:', '["Al-Fil", "Al-Buruj", "Yusuf", "Al-Kahf"]', 3, 'Surah Al-Kahf (18) tells of young believers who slept in a cave for many years; it also has the stories of Musa (AS) with Khidr and of Dhul-Qarnayn.', '{"0": "Al-Fil tells of the People of the Elephant.", "1": "Al-Buruj tells of the People of the Ditch (Ashab-ul-Ukhdud).", "2": "Yusuf tells the story of Hazrat Yusuf (AS)."}'),
  ('ISL-0100', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah tells the whole story of one prophet in a single continuous account and calls it ''the best of stories''?', '["Maryam", "Nuh", "Al-Qasas", "Yusuf"]', 3, 'Surah Yusuf (12:3) says ''We relate to you the best of stories'', and the whole surah tells Yusuf''s (AS) story.', '{"0": "Maryam tells of several prophets, not one in a single story.", "1": "Surah Nuh is about Nuh''s call to his people, not a full life story.", "2": "Al-Qasas tells the story of Musa (AS) but is not called the best of stories."}'),
  ('ISL-0101', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Abraha''s attack on the Kaaba with elephants is described in Surah:', '["Al-Fil", "Al-Ma''un", "Quraysh", "Al-Humazah"]', 0, 'Al-Fil (105) describes how Allah destroyed Abraha''s army with birds throwing stones, in the year the Holy Prophet (PBUH) was born.', '{"1": "Al-Ma''un condemns those who neglect orphans and prayer.", "2": "Quraysh comes right after Al-Fil but is about the Quraysh''s trade journeys.", "3": "Al-Humazah condemns slanderers and hoarders of wealth."}'),
  ('ISL-0102', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Surah Al-Baqarah is named after:', '["the animals of Nuh''s (AS) ark", "a camel of Prophet Salih (AS)", "a cow that Bani Israel were told to slaughter", "a calf worshipped by Bani Israel"]', 2, 'Al-Baqarah 2:67-73 tells how Musa (AS) told Bani Israel to slaughter a cow, and how they kept asking questions to delay.', '{"0": "The ark is described in Surah Hud and Surah Nuh.", "1": "The she-camel of Salih (AS) is mentioned in other surahs, such as Ash-Shams.", "3": "The golden calf is mentioned in Al-Baqarah, but the surah is named after the cow of verses 67-73."}'),
  ('ISL-0103', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah sets out rules of modesty and the punishment for falsely accusing chaste women?', '["Al-Hujurat", "An-Nur", "At-Talaq", "Al-Mumtahanah"]', 1, 'An-Nur (24) gives the rules on hijab, slander (qazf) and the incident of Ifk, when Hazrat Aisha (RA) was cleared.', '{"0": "Al-Hujurat deals with manners, backbiting and spying.", "2": "At-Talaq deals with the rules of divorce.", "3": "Al-Mumtahanah deals with women who migrated from Makkah."}'),
  ('ISL-0104', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah forbids mocking, backbiting and spying on others?', '["Al-Mulk", "Al-Hujurat", "Al-Fil", "Al-Kawthar"]', 1, 'Al-Hujurat 49:11-12 forbids mocking, name-calling, suspicion, spying and backbiting, which it compares to eating a dead brother''s flesh.', '{"0": "Al-Mulk is about Allah''s power over creation and the Hereafter.", "2": "Al-Fil is about Abraha''s army.", "3": "Al-Kawthar is about the abundance given to the Holy Prophet (PBUH)."}'),
  ('ISL-0105', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The advice of a wise man to his son, including ''do not associate anything with Allah'', is given in Surah:', '["Ibrahim", "Al-Kahf", "Yusuf", "Luqman"]', 3, 'Luqman 31:13-19 records Luqman''s advice to his son: avoid shirk, honour parents, pray, be patient and be humble.', '{"0": "Ibrahim contains Hazrat Ibrahim''s (AS) prayer for Makkah.", "1": "Al-Kahf has the dialogue of the two garden owners.", "2": "Yusuf contains Yaqub''s (AS) advice to his sons but is mainly Yusuf''s story."}'),
  ('ISL-0106', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The verse ''This day I have perfected your religion for you'' is in Surah:', '["Al-Baqarah", "An-Nasr", "Al-Ma''idah", "Al-Imran"]', 2, 'Al-Ma''idah 5:3 was revealed at Arafat during the Farewell Hajj, declaring the religion complete.', '{"0": "Al-Baqarah contains Ayat al-Kursi and the longest verse, not this one.", "1": "An-Nasr mentions people entering Islam in crowds.", "3": "Al-Imran 3:19 says the religion with Allah is Islam, but not this verse."}'),
  ('ISL-0107', 'The Quran', 'Verses', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The longest verse of the Holy Quran is about:', '["the shares of inheritance", "Ayat al-Kursi", "writing down loans and debts", "the rules of fasting"]', 2, 'Al-Baqarah 2:282 (Ayat al-Dayn) tells believers to write down debts in front of witnesses; it is the longest verse.', '{"0": "The inheritance verses are in An-Nisa and are shorter.", "1": "Ayat al-Kursi (2:255) is the greatest verse, not the longest.", "3": "The fasting verses are 2:183-187."}'),
  ('ISL-0108', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah says the Night of Decree is better than a thousand months?', '["Al-Layl", "Ad-Dukhan", "Al-Fajr", "Al-Qadr"]', 3, 'Al-Qadr 97:3: ''The Night of Decree is better than a thousand months.''', '{"0": "Al-Layl swears by the night as it covers.", "1": "Ad-Dukhan mentions a ''blessed night'' but not the thousand months.", "2": "Al-Fajr swears by the dawn and ten nights."}'),
  ('ISL-0109', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah says all people are in loss except those who believe, do good and urge one another to truth and patience?', '["Al-Kawthar", "Al-Asr", "Al-Ikhlas", "At-Takathur"]', 1, 'Al-Asr (103) is three verses long and sums up the way to success.', '{"0": "Al-Kawthar is about the abundance given to the Holy Prophet (PBUH).", "2": "Al-Ikhlas states the Oneness of Allah.", "3": "At-Takathur warns against competing in worldly gain."}'),
  ('ISL-0110', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Al-Mu''awwidhatayn, the two surahs recited to seek Allah''s protection, are:', '["Al-Falaq and An-Nas", "Yasin and Ar-Rahman", "Al-Ikhlas and Al-Kafirun", "Al-Fatihah and Al-Baqarah"]', 0, 'Both begin ''Say: I seek refuge with the Lord...'', so they are called the two surahs of seeking refuge.', '{"1": "These are long Makkan surahs, not the protection surahs.", "2": "These two are about Tauheed and rejecting disbelief.", "3": "These are the first two surahs of the Quran."}'),
  ('ISL-0111', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah is named after the honeybee?', '["An-Naml", "Al-Ankabut", "Al-Fil", "An-Nahl"]', 3, 'An-Nahl (16:68-69) says Allah inspired the bee to build homes and that honey is a healing for people.', '{"0": "An-Naml means ''the ant''.", "1": "Al-Ankabut means ''the spider''.", "2": "Al-Fil means ''the elephant''."}'),
  ('ISL-0112', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The meeting of Hazrat Sulaiman (AS) with the Queen of Sheba is described in Surah:', '["Al-Anbiya", "Sad", "An-Naml", "Saba"]', 2, 'An-Naml 27:20-44 tells of the hoopoe''s news, Sulaiman''s letter and the Queen''s visit; the same surah has the ant''s warning.', '{"0": "Al-Anbiya mentions Sulaiman (AS) and the wind briefly.", "1": "Sad mentions Sulaiman''s (AS) horses and his trial.", "3": "Saba describes the people of Sheba and their broken dam, not the Queen''s meeting."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0113', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah is named after a metal and says it has ''great strength and benefits for people''?', '["Saba", "Al-Kahf", "Al-Hadid", "Al-Ma''idah"]', 2, 'Al-Hadid (57:25) means ''Iron'' and says Allah sent down iron with great strength and benefits.', '{"0": "Saba mentions iron made soft for Dawud (AS), but is named after a kingdom.", "1": "Al-Kahf mentions iron in Dhul-Qarnayn''s wall, but is named after the cave.", "3": "Al-Ma''idah means ''the table spread''."}'),
  ('ISL-0114', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which surah is named after a single Arabic letter?', '["Qaf", "Al-Qalam", "Al-Asr", "Al-Mulk"]', 0, 'Qaf (50) and Sad (38) are named after the single letters that open them.', '{"1": "Al-Qalam opens with the letter Nun but is named ''the Pen''.", "2": "Al-Asr means ''time''.", "3": "Al-Mulk means ''the dominion''."}'),
  ('ISL-0115', 'The Quran', 'Surahs', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'A woman who argued with the Holy Prophet (PBUH) about her husband''s zihar is the subject of Surah:', '["Al-Mujadilah", "Al-Mumtahanah", "At-Talaq", "At-Tahrim"]', 0, 'Al-Mujadilah (58:1-4) means ''the woman who disputes''; Hazrat Khawlah bint Tha''labah''s complaint led to the ruling on zihar.', '{"1": "Al-Mumtahanah is about testing women who migrated.", "2": "At-Talaq is about the waiting period after divorce.", "3": "At-Tahrim is about a matter within the Prophet''s household."}'),
  ('ISL-0116', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Surah At-Tawbah is also known as:', '["Bani Isra''il", "Al-Hamd", "Bara''ah", "Al-Mu''min"]', 2, 'At-Tawbah opens with ''Bara''ah'' (a declaration of disassociation) and is the only surah without Bismillah at its start.', '{"0": "Bani Isra''il is the other name of Surah Al-Isra.", "1": "Al-Hamd is another name of Al-Fatihah.", "3": "Al-Mu''min is another name of Surah Ghafir."}'),
  ('ISL-0117', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The Holy Prophet''s (PBUH) night journey from Masjid al-Haram to Masjid al-Aqsa is described at the start of Surah:', '["Al-Anfal", "Al-Kahf", "An-Najm", "Al-Isra"]', 3, 'Al-Isra 17:1 begins ''Glory be to Him who took His servant by night from Al-Masjid al-Haram to Al-Masjid al-Aqsa''.', '{"0": "Al-Anfal is about the Battle of Badr.", "1": "Al-Kahf starts with praise of Allah for sending down the Book.", "2": "An-Najm describes what he saw during the Mi''raj, but not the journey to Al-Aqsa."}'),
  ('ISL-0118', 'The Quran', 'Surahs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Abu Lahab and his wife are condemned by name in Surah:', '["Al-Humazah", "Al-Kawthar", "Al-Kafirun", "Al-Masad (Al-Lahab)"]', 3, 'Al-Masad (111) is the only surah that condemns an opponent of the Prophet (PBUH) by name.', '{"0": "Al-Humazah condemns slanderers in general.", "1": "Al-Kawthar answers those who mocked the Prophet (PBUH) for having no surviving son.", "2": "Al-Kafirun is the reply to the Quraysh''s offer of compromise."}'),
  ('ISL-0119', 'The Quran', 'Surahs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'After the Treaty of Hudaybiyyah, the Quran called the treaty ''a clear victory'' in Surah:', '["Al-Hashr", "Al-Fath", "Al-Anfal", "An-Nasr"]', 1, 'Al-Fath 48:1 ''Indeed, We have given you a clear victory'' was revealed on the way back from Hudaybiyyah.', '{"0": "Al-Hashr is about the expulsion of Banu Nadir.", "2": "Al-Anfal is about Badr.", "3": "An-Nasr is about the conquest of Makkah and people joining Islam."}'),
  ('ISL-0120', 'The Quran', 'Structure of the Quran', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'According to the usual count, how many surahs of the Holy Quran are Makki?', '["70", "114", "86", "28"]', 2, 'Surahs revealed before the Hijrah are Makki; by the usual count, 86 are Makki and 28 Madani.', '{"0": "The usual count is 86 Makki and 28 Madani.", "1": "114 is the total number of surahs.", "3": "28 is the usual count of Madani surahs."}'),
  ('ISL-0121', 'The Quran', 'Structure of the Quran', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'For reciting the whole Quran in a week, it is divided into seven:', '["paras", "rukus", "manzils", "hizbs"]', 2, 'The Quran is divided into seven manzils so that it can be read in seven days.', '{"0": "There are 30 paras, not seven.", "1": "A ruku is a short section of verses, used to mark readings in prayer.", "3": "There are 60 hizbs (two in each para)."}'),
  ('ISL-0122', 'The Quran', 'Structure of the Quran', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Al-Hidayah, Book of Prayer; The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'According to the Hanafi school, how many verses of prostration (sajdah tilawat) are there in the Holy Quran?', '["7", "30", "10", "14"]', 3, 'Hanafis count 14 places where a reader and listener must prostrate.', '{"0": "There are more than seven; for example in Al-A''raf, Ar-Ra''d, An-Nahl and Al-Isra.", "1": "30 is the number of paras.", "2": "The Hanafi count is 14."}'),
  ('ISL-0123', 'The Quran', 'Compilation', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, Book of the Virtues of the Quran, hadith 4986 and 4987', 'Which companion led the work of collecting the Holy Quran under Hazrat Abu Bakr (RA) and of making the standard copies under Hazrat Uthman (RA)?', '["Hazrat Bilal (RA)", "Hazrat Abdullah bin Abbas (RA)", "Hazrat Abu Hurairah (RA)", "Hazrat Zaid bin Thabit (RA)"]', 3, 'Zaid bin Thabit, a scribe of revelation, gathered the Quran after the Battle of Yamamah and later headed Uthman''s committee.', '{"0": "Bilal was the first muezzin.", "1": "Ibn Abbas is known as the great interpreter of the Quran, not as its compiler.", "2": "Abu Hurairah is known for narrating hadith."}'),
  ('ISL-0124', 'The Quran', 'Compilation', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 4987', 'The written copy of the Quran collected under Hazrat Abu Bakr (RA) was later kept with:', '["Hazrat Fatimah (RA)", "Hazrat Hafsah (RA)", "Hazrat Ali (RA)", "Hazrat Aisha (RA)"]', 1, 'After Abu Bakr and Umar, the sheets passed to Hafsah (RA); Uthman (RA) borrowed them to make the standard copies.', '{"0": "Fatimah (RA) died within months of the Holy Prophet (PBUH).", "2": "The copy passed from Umar (RA) to his daughter Hafsah (RA).", "3": "Aisha (RA) was a great narrator of hadith, but the copy was kept with Hafsah (RA)."}'),
  ('ISL-0125', 'The Quran', 'Translation', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: S. M. Ikram, Muslim Civilization in India; The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Shah Waliullah translated the Holy Quran into which language?', '["Persian", "Sindhi", "English", "Urdu"]', 0, 'Shah Waliullah''s Persian translation, Fath-ur-Rahman, made the Quran readable for educated Muslims of 18th-century India.', '{"1": "Sindhi translations came from other scholars.", "2": "Early English translations came from Europe and later from scholars such as Pickthall.", "3": "The first Urdu translations were made by his sons Shah Rafiuddin and Shah Abdul Qadir."}'),
  ('ISL-0126', 'The Quran', 'Translation', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: S. M. Ikram, Muslim Civilization in India', 'The early Urdu translations of the Holy Quran were made by:', '["Shah Rafiuddin and Shah Abdul Qadir", "Sir Syed Ahmad Khan and Shibli Nomani", "Allama Iqbal and Maulana Jauhar", "Abul Kalam Azad and Maududi"]', 0, 'These two sons of Shah Waliullah made Urdu translations around 1790-1800, carrying on their father''s work.', '{"1": "Sir Syed wrote a commentary later; Shibli was a historian.", "2": "They were poet and journalist of the 20th century.", "3": "Their Quran works came in the 20th century."}'),
  ('ISL-0127', 'Hadith and Sunnah', 'Books of hadith', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'Sahih Muslim was compiled by:', '["Imam Tirmidhi", "Imam Malik", "Imam Bukhari", "Imam Muslim bin al-Hajjaj"]', 3, 'Imam Muslim (died 875) compiled Sahih Muslim, counted with Bukhari as the two most authentic books.', '{"0": "Imam Tirmidhi compiled Jami'' at-Tirmidhi.", "1": "Imam Malik compiled Al-Muwatta.", "2": "Imam Bukhari compiled Sahih al-Bukhari; Muslim was his student."}'),
  ('ISL-0128', 'Hadith and Sunnah', 'Books of hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'Which of these is one of the Sihah Sittah (six major books of hadith)?', '["Al-Hidayah", "Fatawa-e-Alamgiri", "Ihya Ulum al-Din", "Sunan Abu Dawud"]', 3, 'The six are Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasa''i and Ibn Majah.', '{"0": "Al-Hidayah is a book of Hanafi fiqh.", "1": "Fatawa-e-Alamgiri is a collection of Hanafi rulings made under Aurangzeb.", "2": "Ihya Ulum al-Din is Imam Ghazali''s book on spiritual life."}'),
  ('ISL-0129', 'Hadith and Sunnah', 'Books of hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'Musnad, a large collection of hadith arranged by companion, was compiled by:', '["Imam Ahmad bin Hanbal", "Imam Abu Hanifa", "Imam Nasa''i", "Imam Ghazali"]', 0, 'The Musnad of Imam Ahmad has around 27,000 hadith, arranged under each companion who narrated them.', '{"1": "Abu Hanifa founded the Hanafi school; he left no musnad of this kind himself.", "2": "Imam Nasa''i compiled the Sunan an-Nasa''i.", "3": "Imam Ghazali was a theologian and Sufi, not a hadith compiler."}'),
  ('ISL-0130', 'Hadith and Sunnah', 'Books of hadith', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'Mishkat al-Masabih, a popular selection of hadith, was compiled by:', '["Imam Nawawi", "Ibn Majah", "Imam Malik", "Al-Khatib al-Tabrizi"]', 3, 'Al-Tabrizi expanded al-Baghawi''s Masabih al-Sunnah in 1337 into Mishkat al-Masabih, widely taught in South Asia.', '{"0": "Imam Nawawi compiled Riyad as-Salihin and the Forty Hadith.", "1": "Ibn Majah compiled one of the six major books.", "2": "Imam Malik compiled Al-Muwatta."}'),
  ('ISL-0131', 'Hadith and Sunnah', 'Types of hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'A hadith narrated by so many people at every stage that they could not have agreed on a lie is called:', '["Da''if", "Mutawatir", "Mursal", "Ahad"]', 1, 'A mutawatir hadith gives certain knowledge because of its very large number of narrators.', '{"0": "Da''if means weak.", "2": "Mursal is one where the companion is missing from the chain.", "3": "Ahad is narrated by fewer people than mutawatir."}'),
  ('ISL-0132', 'Hadith and Sunnah', 'Types of hadith', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'A hadith with a weak or broken chain of narrators is called:', '["Sahih", "Qudsi", "Hasan", "Da''if"]', 3, 'Da''if means weak: the chain has a gap or a narrator who is not reliable.', '{"0": "Sahih means sound, the strongest grade.", "1": "Qudsi describes the content (Allah''s words), not the strength of the chain.", "2": "Hasan means good, slightly below sahih but still accepted."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0133', 'Hadith and Sunnah', 'Types of hadith', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'In hadith studies, the actual text or wording of a hadith is called the:', '["Isnad", "Matn", "Rawi", "Sharh"]', 1, 'Every hadith has two parts: the isnad (chain) and the matn (text).', '{"0": "The isnad is the chain of narrators.", "2": "A rawi is a narrator.", "3": "A sharh is a commentary on a book of hadith."}'),
  ('ISL-0134', 'Hadith and Sunnah', 'Narrators', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Muhammad Zubayr Siddiqi, Hadith Literature; Islamiat (compulsory), PTB', 'Which woman narrated the largest number of hadith?', '["Hazrat Fatimah (RA)", "Hazrat Khadijah (RA)", "Hazrat Hafsah (RA)", "Hazrat Aisha (RA)"]', 3, 'Hazrat Aisha (RA) narrated more than 2,000 hadith and taught many companions and successors.', '{"0": "Fatimah (RA) died within months of the Holy Prophet (PBUH).", "1": "Khadijah (RA) died before the Hijrah, so few hadith come through her.", "2": "Hafsah (RA) narrated far fewer hadith than Aisha (RA)."}'),
  ('ISL-0135', 'Hadith and Sunnah', 'Sunnah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The Holy Prophet''s (PBUH) Farewell Sermon was delivered at:', '["Mount Safa", "Quba", "Arafat", "Masjid Nabawi"]', 2, 'The sermon was given on 9 Dhul Hijjah 10 AH at Arafat, setting out the sanctity of life, property and honour and the equality of people.', '{"0": "On Mount Safa the Holy Prophet (PBUH) first called the Quraysh openly.", "1": "Quba is where the first mosque was built.", "3": "Masjid Nabawi is in Madinah; the sermon was given during Hajj."}'),
  ('ISL-0136', 'Hadith and Sunnah', 'Sunnah', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan Abu Dawud, Book of Judgements, hadith 3592; Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'When the Holy Prophet (PBUH) sent Hazrat Muadh bin Jabal (RA) to Yemen, Muadh said he would judge by the Quran, then the Sunnah, and then:', '["the opinion of the governor of Makkah", "his own reasoning (ijtihad)", "the Torah", "the customs of Yemen"]', 1, 'The hadith of Muadh is the classic basis for ijtihad when the Quran and Sunnah give no direct answer.', '{"0": "No such authority is mentioned in the report.", "2": "Earlier scriptures were not named as a source.", "3": "He did not name local custom as a source."}'),
  ('ISL-0137', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The Holy Prophet''s (PBUH) mother, Hazrat Aminah, died when he was about six years old, at:', '["Taif", "Badr", "Abwa", "Hudaybiyyah"]', 2, 'Aminah died at Abwa, between Madinah and Makkah, on the way back from visiting relatives in Yathrib.', '{"0": "Taif is where the Holy Prophet (PBUH) went to preach after the Year of Sorrow.", "1": "Badr is the site of the first battle, in 2 AH.", "3": "Hudaybiyyah is where the treaty of 6 AH was made."}'),
  ('ISL-0138', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The Holy Prophet''s (PBUH) father was:', '["Abu Talib", "Abdul Muttalib", "Hamza", "Abdullah"]', 3, 'His father Abdullah bin Abdul Muttalib died before he was born.', '{"0": "Abu Talib was his uncle who raised him.", "1": "Abdul Muttalib was his grandfather.", "2": "Hamza (RA) was his uncle and foster brother."}'),
  ('ISL-0139', 'Life of the Holy Prophet', 'Early life', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'On a trade journey to Syria with Abu Talib, the young Holy Prophet (PBUH) was recognised as a future prophet by the monk:', '["Negus", "Waraqah bin Nawfal", "Bahira", "Salman Farsi"]', 2, 'The Christian monk Bahira, at Busra, saw signs of prophethood and advised Abu Talib to protect the boy.', '{"0": "The Negus was the king of Abyssinia.", "1": "Waraqah was Khadijah''s (RA) cousin who confirmed the first revelation.", "3": "Salman Farsi (RA) became a companion in Madinah."}'),
  ('ISL-0140', 'Life of the Holy Prophet', 'Early life', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Hilf al-Fudul, which the young Holy Prophet (PBUH) joined, was a pact to:', '["protect trade caravans to Syria", "expel the idols from the Kaaba", "rebuild the Kaaba", "help anyone in Makkah who was wronged"]', 3, 'Some Quraysh clans pledged to stand with any wronged person, local or foreign; he later said he would join such a pact again.', '{"0": "It was a pledge for justice, not a trade agreement.", "1": "Idols were removed only at the conquest of Makkah.", "2": "The Kaaba was rebuilt later, when he was 35."}'),
  ('ISL-0141', 'Life of the Holy Prophet', 'Early life', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'How old was the Holy Prophet (PBUH) when he married Hazrat Khadijah (RA)?', '["40", "25", "35", "20"]', 1, 'He married Khadijah (RA) at 25 after managing her trade caravan to Syria honestly.', '{"0": "He received the first revelation at 40.", "2": "At 35 he settled the dispute over the Black Stone.", "3": "He married at 25, not 20."}'),
  ('ISL-0142', 'Life of the Holy Prophet', 'Makkah', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The first free adult man to accept Islam was:', '["Hazrat Zaid bin Harithah (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Abu Bakr (RA)"]', 3, 'The first to believe were Khadijah (RA), Abu Bakr (RA), Ali (RA) and Zaid (RA): first woman, man, child and freed slave.', '{"0": "Zaid (RA) was the first freed slave to accept Islam.", "1": "Umar (RA) accepted Islam about six years after the first revelation.", "2": "Ali (RA) was the first child to accept Islam."}'),
  ('ISL-0143', 'Life of the Holy Prophet', 'Makkah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'In the early secret years of Islam in Makkah, the Muslims met to learn and pray at the house of:', '["Hazrat Abu Ayyub Ansari (RA)", "Hazrat Arqam (RA)", "Abu Talib", "Abu Sufyan"]', 1, 'Dar al-Arqam, near Safa, was the centre of the early Muslims until Islam was preached openly.', '{"0": "Abu Ayyub (RA) hosted the Holy Prophet (PBUH) in Madinah.", "2": "Abu Talib protected the Holy Prophet (PBUH) but his house was not the meeting place.", "3": "Abu Sufyan opposed Islam until the conquest of Makkah."}'),
  ('ISL-0144', 'Life of the Holy Prophet', 'Makkah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The Holy Prophet (PBUH) first called the Quraysh openly to Islam from:', '["Mina", "Cave Hira", "Mount Safa", "Mount Uhud"]', 2, 'He climbed Safa, called each clan of Quraysh and warned them; Abu Lahab cursed him, which led to Surah Al-Masad.', '{"0": "Mina is a valley used during Hajj.", "1": "Cave Hira is where the first revelation came.", "3": "Uhud is near Madinah."}'),
  ('ISL-0145', 'Life of the Holy Prophet', 'Makkah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'After the Year of Sorrow, the Holy Prophet (PBUH) went to preach to the people of which town, who stoned him?', '["Taif", "Jeddah", "Khaybar", "Yathrib"]', 0, 'In about the tenth year of prophethood he went to Taif; its leaders rejected him and set boys to throw stones at him.', '{"1": "Jeddah was not where he went to preach.", "2": "Khaybar was a Jewish settlement conquered in 7 AH.", "3": "The people of Yathrib welcomed him and invited him to their city."}'),
  ('ISL-0146', 'Life of the Holy Prophet', 'Hijrah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The pledges by which people of Yathrib accepted Islam and promised to protect the Holy Prophet (PBUH) are called the Pledges of:', '["Mawakhat", "Ridwan", "Aqabah", "Hilf al-Fudul"]', 2, 'At Aqabah, near Mina, people of Yathrib pledged loyalty in two successive years, opening the way for the Hijrah.', '{"0": "Mawakhat was the brotherhood set up in Madinah.", "1": "Bai''at al-Ridwan was given at Hudaybiyyah in 6 AH.", "3": "Hilf al-Fudul was an earlier Makkan pact for justice."}'),
  ('ISL-0147', 'Life of the Holy Prophet', 'Hijrah', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'On the night of the Hijrah, who slept in the Holy Prophet''s (PBUH) bed?', '["Hazrat Bilal (RA)", "Hazrat Ali (RA)", "Hazrat Zaid bin Harithah (RA)", "Hazrat Abu Bakr (RA)"]', 1, 'Ali (RA) slept in his bed and stayed to return the goods that people had left with the Holy Prophet (PBUH) for safekeeping.', '{"0": "Bilal (RA) had already migrated.", "2": "Zaid (RA) was not the one left behind that night.", "3": "Abu Bakr (RA) travelled with the Holy Prophet (PBUH)."}'),
  ('ISL-0148', 'Life of the Holy Prophet', 'Hijrah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'In Madinah, the Holy Prophet (PBUH) stayed at first in the house of:', '["Hazrat Abdullah bin Ubayy", "Hazrat Saad bin Muadh (RA)", "Hazrat Uthman (RA)", "Hazrat Abu Ayyub Ansari (RA)"]', 3, 'His camel knelt near Abu Ayyub''s (RA) house, and he stayed there until his own rooms by the mosque were built.', '{"0": "Abdullah bin Ubayy later led the hypocrites.", "1": "Saad bin Muadh (RA) was a chief of the Aws, but he was not the host.", "2": "Uthman (RA) was a Muhajir from Makkah."}'),
  ('ISL-0149', 'Life of the Holy Prophet', 'Madinah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The written agreement among the Muslims, Jews and other tribes of Madinah, often called the first written constitution, is the:', '["Charter of Madinah (Misaq-e-Madinah)", "Treaty of Hudaybiyyah", "Farewell Sermon", "Pledge of Aqabah"]', 0, 'Soon after the Hijrah, the Charter made Madinah''s groups one community for defence, with disputes referred to the Holy Prophet (PBUH).', '{"1": "Hudaybiyyah was a truce with the Quraysh of Makkah.", "2": "The Farewell Sermon was a speech, not an agreement among tribes.", "3": "Aqabah was a pledge of faith before the Hijrah."}'),
  ('ISL-0150', 'Life of the Holy Prophet', 'Battles', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Roughly how many Muslims fought in the Battle of Badr?', '["3,000", "10,000", "1,000", "313"]', 3, 'About 313 lightly armed Muslims defeated around 1,000 Quraysh at Badr in Ramadan 2 AH.', '{"0": "3,000 was the Quraysh army at Uhud.", "1": "About 10,000 Muslims marched to conquer Makkah.", "2": "About 1,000 was the size of the Quraysh army."}'),
  ('ISL-0151', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Which leader of the Quraysh was killed in the Battle of Badr?', '["Abu Jahl", "Abu Sufyan", "Abu Lahab", "Khalid bin Walid"]', 0, 'Abu Jahl, the fiercest enemy of Islam in Makkah, was killed at Badr.', '{"1": "Abu Sufyan led the caravan and later the Quraysh at Uhud; he accepted Islam in 8 AH.", "2": "Abu Lahab did not fight at Badr and died soon after in Makkah.", "3": "Khalid fought for the Quraysh at Uhud and accepted Islam later."}'),
  ('ISL-0152', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'In the Battle of Uhud, the Muslims suffered losses mainly because:', '["the Muslims had no cavalry at all", "the Jews of Madinah attacked from behind", "it was fought during a sandstorm", "archers left their post on the hill against orders"]', 3, 'Most of the archers placed on the hill under Abdullah bin Jubair (RA) left to collect spoils; Khalid bin Walid''s cavalry attacked from behind.', '{"0": "The setback came from the archers leaving their post, not from lacking cavalry.", "1": "No such attack happened at Uhud.", "2": "Weather was not the cause."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0153', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Hazrat Ali (RA) is called ''Fatih-e-Khaybar'' because he:', '["won the Battle of Badr alone", "conquered Makkah in 8 AH", "captured the fort of Qamus at Khaybar in 7 AH", "led the army to Tabuk"]', 2, 'After others failed, the Holy Prophet (PBUH) gave Ali (RA) the flag at Khaybar and he took the fort of Qamus.', '{"0": "Badr was won by the whole Muslim army.", "1": "Makkah was conquered under the Holy Prophet (PBUH).", "3": "The Holy Prophet (PBUH) led the Tabuk expedition; Ali (RA) stayed in Madinah."}'),
  ('ISL-0154', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'At Hudaybiyyah, the companions pledged under a tree to stand by the Holy Prophet (PBUH). This pledge is called:', '["Bai''at al-Aqabah", "Bai''at al-Khilafah", "Bai''at al-Ridwan", "Hilf al-Fudul"]', 2, 'When it was rumoured that Uthman (RA) had been killed, the companions gave this pledge; Allah declared His pleasure with them in Al-Fath 48:18.', '{"0": "The Aqabah pledges came before the Hijrah.", "1": "This is not the name of a pledge in the Prophet''s lifetime.", "3": "Hilf al-Fudul was an older Makkan pact."}'),
  ('ISL-0155', 'Life of the Holy Prophet', 'Letters to rulers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Which ruler tore up the Holy Prophet''s (PBUH) letter inviting him to Islam?', '["Heraclius, the Byzantine emperor", "Negus, the king of Abyssinia", "Muqawqis, the ruler of Egypt", "Khusro Parvez, the Persian emperor"]', 3, 'Khusro Parvez tore the letter; the Holy Prophet (PBUH) said his kingdom would be torn apart in the same way.', '{"0": "Heraclius received the letter respectfully and questioned Abu Sufyan about the Prophet.", "1": "The Negus accepted Islam.", "2": "Muqawqis replied politely and sent gifts."}'),
  ('ISL-0156', 'Life of the Holy Prophet', 'Letters to rulers', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Which ruler sent gifts in reply to the Holy Prophet''s (PBUH) letter, including Hazrat Mariyah Qibtiyyah (RA)?', '["Muqawqis of Egypt", "Harith of Ghassan", "Heraclius of Byzantium", "Khusro Parvez of Persia"]', 0, 'Mariyah (RA) became the mother of the Holy Prophet''s (PBUH) son Ibrahim, who died in infancy.', '{"1": "The Ghassanid ruler threatened to attack.", "2": "Heraclius sent no such gift.", "3": "Khusro tore up the letter."}'),
  ('ISL-0157', 'Life of the Holy Prophet', 'Battles', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'In the Battle of Mu''tah (8 AH), the three appointed commanders were martyred one after another. They were Zaid bin Harithah, Ja''far bin Abi Talib and:', '["Hamza (RA)", "Abu Ubaidah (RA)", "Khalid bin Walid (RA)", "Abdullah bin Rawahah (RA)"]', 3, 'Mu''tah, against a large Byzantine-allied force, was the first clash with the Byzantines; Khalid (RA) earned the title Saifullah there.', '{"0": "Hamza (RA) was martyred at Uhud in 3 AH.", "1": "Abu Ubaidah (RA) was not a commander at Mu''tah.", "2": "Khalid (RA) took command after the three were martyred and brought the army back."}'),
  ('ISL-0158', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The last expedition in which the Holy Prophet (PBUH) himself led the army was:', '["Mu''tah", "Tabuk", "Khaybar", "Hunain"]', 1, 'In 9 AH he led about 30,000 men to Tabuk against a Byzantine threat; no battle took place.', '{"0": "The Holy Prophet (PBUH) did not go to Mu''tah himself.", "2": "Khaybar was in 7 AH.", "3": "Hunain (8 AH) came before Tabuk."}'),
  ('ISL-0159', 'Life of the Holy Prophet', 'Battles', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan at-Tirmidhi, hadith 3675', 'For the Tabuk expedition, which companion gave all of his wealth?', '["Hazrat Abu Hurairah (RA)", "Hazrat Umar (RA)", "Hazrat Abdur Rahman bin Awf (RA)", "Hazrat Abu Bakr (RA)"]', 3, 'Abu Bakr (RA) brought everything he had; when asked what he left for his family, he said ''Allah and His Messenger''.', '{"0": "Abu Hurairah (RA) was poor and among the Ashab-e-Suffah.", "1": "Umar (RA) gave half of his wealth.", "2": "He gave generously but not all he owned."}'),
  ('ISL-0160', 'Life of the Holy Prophet', 'Madinah', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', '9 AH is called Aam al-Wufud (the Year of Delegations) because:', '["tribes from across Arabia sent delegations to accept Islam", "the Muslims sent envoys to the Roman emperor", "the Quraysh sent envoys to make peace", "the Holy Prophet (PBUH) visited every tribe"]', 0, 'After the conquest of Makkah and Tabuk, delegations came to Madinah from all over Arabia.', '{"1": "The letters to rulers were sent around 6-7 AH.", "2": "That was at Hudaybiyyah in 6 AH.", "3": "The tribes came to Madinah, not the other way round."}'),
  ('ISL-0161', 'Life of the Holy Prophet', 'Family', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'Which of the Holy Prophet''s (PBUH) daughters outlived him?', '["Hazrat Zainab (RA)", "Hazrat Ruqayyah (RA)", "Hazrat Fatimah (RA)", "Hazrat Umm Kulthum (RA)"]', 2, 'Fatimah (RA) was the only child alive when he passed away; she died a few months later.', '{"0": "Zainab (RA) died in 8 AH.", "1": "Ruqayyah (RA) died in 2 AH, around the time of Badr.", "3": "Umm Kulthum (RA) died in 9 AH."}'),
  ('ISL-0162', 'Life of the Holy Prophet', 'Family', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The Holy Prophet''s (PBUH) wives are given the title:', '["Ummahat-ul-Momineen (Mothers of the Believers)", "Ansar", "Ashara Mubashara", "Ashab-e-Suffah"]', 0, 'Al-Ahzab 33:6 says ''his wives are their mothers'', so they are called Mothers of the Believers.', '{"1": "The Ansar were the Muslims of Madinah.", "2": "These are ten companions promised Paradise.", "3": "The Ashab-e-Suffah were poor companions who lived at the mosque."}'),
  ('ISL-0163', 'Life of the Holy Prophet', 'Final days', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The Holy Prophet (PBUH) was buried:', '["in Jannat al-Baqi", "near the Kaaba", "at Uhud", "in the room of Hazrat Aisha (RA), beside Masjid Nabawi"]', 3, 'He was buried where he died, in Aisha''s (RA) room; Abu Bakr (RA) and Umar (RA) were later buried beside him.', '{"0": "Jannat al-Baqi is Madinah''s main graveyard, where many companions are buried.", "1": "He passed away and was buried in Madinah.", "2": "The martyrs of Uhud are buried there."}'),
  ('ISL-0164', 'Beliefs and worship', 'Angels', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Belief in angels', 'Which angel is in charge of rain and provision?', '["Hazrat Israfil (AS)", "Hazrat Izrail (AS)", "Hazrat Jibrail (AS)", "Hazrat Mikail (AS)"]', 3, 'Mikail (AS) is one of the four great angels and is in charge of rain and sustenance.', '{"0": "Israfil (AS) will blow the trumpet on the Day of Judgement.", "1": "Izrail (AS) is the angel of death.", "2": "Jibrail (AS) brought revelation to the prophets."}'),
  ('ISL-0165', 'Beliefs and worship', 'Angels', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan at-Tirmidhi, hadith 1071', 'The two angels who question the dead in the grave are:', '["Kiraman and Katibin", "Munkar and Nakir", "Harut and Marut", "Ridwan and Malik"]', 1, 'Munkar and Nakir ask the dead: who is your Lord, what is your religion, and who is this man (the Prophet)?', '{"0": "Kiraman Katibin are the noble scribes who record deeds.", "2": "Harut and Marut are the two angels at Babylon in Al-Baqarah 2:102.", "3": "Ridwan keeps Paradise and Malik keeps Hell."}'),
  ('ISL-0166', 'Beliefs and worship', 'Angels', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The angels who write down every person''s good and bad deeds are called:', '["Zabaniyah", "Hamalat al-Arsh", "Munkar and Nakir", "Kiraman Katibin"]', 3, 'Al-Infitar 82:10-12 speaks of ''noble writers'' who know whatever you do.', '{"0": "They are the guards of Hell.", "1": "They carry the Throne of Allah.", "2": "They question the dead in the grave."}'),
  ('ISL-0167', 'Beliefs and worship', 'Angels', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The angel who guards Hell is named in the Quran as:', '["Mikail", "Nakir", "Malik", "Ridwan"]', 2, 'Az-Zukhruf 43:77: the people of Hell will call out ''O Malik, let your Lord put an end to us''.', '{"0": "Mikail is in charge of rain and provision.", "1": "Nakir is one of the angels of the grave.", "3": "Ridwan is the keeper of Paradise."}'),
  ('ISL-0168', 'Beliefs and worship', 'Angels', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'In the Holy Quran, ''Ruh-ul-Quds'' and ''Ruh-ul-Amin'' are titles of:', '["Hazrat Mikail (AS)", "Hazrat Jibrail (AS)", "the human soul", "Hazrat Isa (AS)"]', 1, 'Ash-Shu''ara 26:193 says the Quran was brought down by ''Ar-Ruh al-Amin'' (the trustworthy spirit), that is, Jibrail.', '{"0": "Mikail (AS) is not given these titles.", "2": "The titles refer to the angel of revelation.", "3": "Isa (AS) is called Ruhullah (a spirit from Allah), which is a different title."}'),
  ('ISL-0169', 'Beliefs and worship', 'Revealed books', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The Injil was revealed to:', '["Hazrat Isa (AS)", "Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Dawud (AS)"]', 0, 'The four revealed books are the Tawrat, Zabur, Injil and Quran.', '{"1": "Ibrahim (AS) was given scrolls (suhuf).", "2": "The Tawrat was revealed to Musa (AS).", "3": "The Zabur was revealed to Dawud (AS)."}'),
  ('ISL-0170', 'Beliefs and worship', 'Revealed books', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The Holy Quran mentions ''the scrolls (suhuf) of Ibrahim and Musa'' in Surah:', '["Al-Ikhlas", "Al-Kawthar", "Al-A''la", "Al-Fatihah"]', 2, 'Al-A''la 87:18-19: ''This is in the earlier scrolls, the scrolls of Ibrahim and Musa.''', '{"0": "Al-Ikhlas is about Allah''s Oneness.", "1": "Al-Kawthar is about the abundance given to the Prophet (PBUH).", "3": "Al-Fatihah mentions no earlier books."}'),
  ('ISL-0171', 'Beliefs and worship', 'Beliefs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB', 'The three basic beliefs of Islam are Tauheed, Risalat and:', '["Ijma", "Zakat", "Jihad", "Akhirat"]', 3, 'Belief in the Oneness of Allah, in prophethood and in the life after death are the foundation of faith.', '{"0": "Ijma is a source of Islamic law.", "1": "Zakat is a pillar of practice, not one of the three basic beliefs.", "2": "Jihad is a duty, not one of the three basic beliefs."}'),
  ('ISL-0172', 'Beliefs and worship', 'Beliefs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Pretending to be a Muslim while hiding disbelief is called:', '["Nifaq", "Bid''ah", "Riya", "Shirk"]', 0, 'Nifaq (hypocrisy) is condemned in Surah Al-Munafiqun and at the start of Al-Baqarah.', '{"1": "Bid''ah is innovation in religion.", "2": "Riya is showing off good deeds, a lesser fault than hiding disbelief.", "3": "Shirk is associating partners with Allah."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0173', 'Beliefs and worship', 'Prayer', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Salat', 'How many fard rak''ahs are there in the five daily prayers together?', '["5", "20", "12", "17"]', 3, 'Fajr 2, Zuhr 4, Asr 4, Maghrib 3 and Isha 4 make 17 fard rak''ahs.', '{"0": "5 is the number of prayers, not rak''ahs.", "1": "20 is the Hanafi count of Taraweeh rak''ahs.", "2": "The total of fard rak''ahs is 17."}'),
  ('ISL-0174', 'Beliefs and worship', 'Prayer', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan Abu Dawud, hadith 499', 'The adhan (call to prayer) was started in Madinah after a dream seen by:', '["Hazrat Ali (RA)", "Hazrat Abdullah bin Zaid (RA)", "Hazrat Bilal (RA)", "Hazrat Abu Hurairah (RA)"]', 1, 'Abdullah bin Zaid (RA) saw the words of the adhan in a dream; Umar (RA) had seen the same; the Holy Prophet (PBUH) approved it.', '{"0": "Ali (RA) is not linked with the dream.", "2": "Bilal (RA) was chosen to call the adhan because of his strong voice.", "3": "Abu Hurairah (RA) accepted Islam years later, in 7 AH."}'),
  ('ISL-0175', 'Beliefs and worship', 'Prayer', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which prayer takes the place of Zuhr on Friday?', '["Eid prayer", "Salat al-Duha", "Jumu''ah", "Tahajjud"]', 2, 'Al-Jumu''ah 62:9 tells believers to hurry to the remembrance of Allah when called on Friday.', '{"0": "Eid prayer is offered twice a year in the morning.", "1": "Duha is a voluntary forenoon prayer.", "3": "Tahajjud is a voluntary night prayer."}'),
  ('ISL-0176', 'Beliefs and worship', 'Prayer', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Al-Hidayah, Book of Prayer', 'In the Hanafi school, the Eid prayer is:', '["Mustahab", "Fard", "Wajib", "Mubah"]', 2, 'Hanafis hold the two Eid prayers to be wajib; other schools treat them as an emphasised sunnah or a communal duty.', '{"0": "Mustahab is lower than wajib.", "1": "Fard is for the five daily prayers and Jumu''ah.", "3": "Mubah means merely permitted."}'),
  ('ISL-0177', 'Beliefs and worship', 'Prayer', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'In the Hanafi school, how many acts are fard in wudu?', '["Four", "Three", "Two", "Seven"]', 0, 'Al-Ma''idah 5:6 names washing the face, arms to the elbows, wiping the head and washing the feet.', '{"1": "There are four: face, arms, wiping the head and feet.", "2": "There are four.", "3": "Seven is too many."}'),
  ('ISL-0178', 'Beliefs and worship', 'Fasting', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih Ibn Khuzaymah, hadith 1887 (as commonly taught)', 'The first ten days of Ramadan are called the Ashra of:', '["I''tikaf", "Nijat (freedom from Hell)", "Maghfirat (forgiveness)", "Rahmat (mercy)"]', 3, 'Ramadan is divided into three ashras: mercy, forgiveness and freedom from the Fire.', '{"0": "I''tikaf is the retreat in the mosque in the last ten days.", "1": "Nijat is the last ten days.", "2": "Maghfirat is the second ten days."}'),
  ('ISL-0179', 'Beliefs and worship', 'Fasting', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 2026', 'Staying in the mosque for worship during the last ten days of Ramadan is called:', '["Fidyah", "Sahri", "Taraweeh", "I''tikaf"]', 3, 'The Holy Prophet (PBUH) observed i''tikaf in the last ten days of Ramadan every year in Madinah.', '{"0": "Fidyah is compensation for a missed fast.", "1": "Sahri is the meal before dawn.", "2": "Taraweeh is the night prayer of Ramadan."}'),
  ('ISL-0180', 'Beliefs and worship', 'Fasting', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 1936', 'Under Hanafi law, the kaffarah for deliberately breaking a Ramadan fast without excuse is, if one cannot free a slave:', '["paying zakat twice", "giving one day''s food to a poor person", "fasting one extra day", "fasting 60 days in a row"]', 3, 'The kaffarah is to free a slave, or fast 60 days without a break, or feed 60 poor people if one cannot fast.', '{"0": "Zakat has nothing to do with kaffarah.", "1": "That is fidyah, for those who cannot fast at all.", "2": "One day of qada is also owed, but the kaffarah is far heavier."}'),
  ('ISL-0181', 'Beliefs and worship', 'Fasting', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 1503', 'Sadaqat al-Fitr should be paid:', '["before the Eid al-Fitr prayer", "on the first day of Ramadan", "once in a lifetime", "after Eid al-Adha"]', 0, 'The Holy Prophet (PBUH) ordered it to be paid before people go out to the Eid prayer, so the poor can share in Eid.', '{"1": "It may be paid early, but it falls due at the end of Ramadan.", "2": "It is paid every year.", "3": "It is linked with Eid al-Fitr."}'),
  ('ISL-0182', 'Beliefs and worship', 'Zakat', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'How many categories of people may receive zakat, according to Surah At-Tawbah?', '["Four", "Ten", "Five", "Eight"]', 3, 'At-Tawbah 9:60: the poor, the needy, zakat workers, those whose hearts are to be won, slaves, debtors, in the way of Allah, and travellers.', '{"0": "At-Tawbah 9:60 lists eight.", "1": "The list has eight categories.", "2": "Five is the number of pillars of Islam."}'),
  ('ISL-0183', 'Beliefs and worship', 'Zakat', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Zakat', 'The nisab (minimum wealth) for zakat on gold is:', '["7.5 tolas (about 87.5 grams)", "52.5 tolas", "1 tola", "20 tolas"]', 0, 'The nisab of gold is 20 mithqal, about 7.5 tolas or 87.5 grams; zakat at 2.5% is due after one lunar year.', '{"1": "52.5 tolas is the nisab for silver.", "2": "1 tola is far below the nisab.", "3": "The traditional nisab for gold is 20 mithqal, which is about 7.5 tolas, not 20 tolas."}'),
  ('ISL-0184', 'Beliefs and worship', 'Zakat', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 1483', 'Ushr on the produce of land watered by rain is:', '["one fortieth", "one tenth", "one twentieth", "one fifth"]', 1, 'The Holy Prophet (PBUH) set one tenth for land watered by rain or springs and half of that for land watered by effort.', '{"0": "One fortieth (2.5%) is zakat on cash and gold.", "2": "One twentieth (5%) is for land watered artificially.", "3": "One fifth (khums) applies to spoils of war and buried treasure."}'),
  ('ISL-0185', 'Beliefs and worship', 'Hajj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Hajj', 'The special dress and state that a pilgrim enters before Hajj or Umrah is called:', '["Tawaf", "Rami", "Ihram", "Wuquf"]', 2, 'Pilgrims put on ihram at the miqat; men wear two unstitched sheets.', '{"0": "Tawaf is walking round the Kaaba.", "1": "Rami is stoning the pillars at Mina.", "3": "Wuquf is standing at Arafat."}'),
  ('ISL-0186', 'Beliefs and worship', 'Hajj', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 1524', 'The fixed points around Makkah where pilgrims must enter ihram are called:', '["Miqat", "Haram", "Multazam", "Muzdalifah"]', 0, 'The Holy Prophet (PBUH) fixed miqat points such as Dhul Hulayfah for people coming from Madinah.', '{"1": "The Haram is the sacred area itself.", "2": "The Multazam is the part of the Kaaba''s wall between the door and the Black Stone.", "3": "Muzdalifah is where pilgrims spend the night after Arafat."}'),
  ('ISL-0187', 'Beliefs and worship', 'Hajj', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Hajj', 'The day of standing at Arafat falls on:', '["27 Ramadan", "9 Dhul Hijjah", "1 Muharram", "10 Dhul Hijjah"]', 1, 'Standing at Arafat on 9 Dhul Hijjah is the most essential act of Hajj.', '{"0": "27 Ramadan is often thought to be Laylat al-Qadr.", "2": "1 Muharram is the start of the Islamic year.", "3": "10 Dhul Hijjah is Eid al-Adha."}'),
  ('ISL-0188', 'Beliefs and worship', 'Hajj', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Hajj', 'Stoning the pillars (Rami al-Jamarat) during Hajj takes place at:', '["Muzdalifah", "Masjid Nabawi", "Arafat", "Mina"]', 3, 'At Mina pilgrims stone the pillars, remembering how Ibrahim (AS) rejected Satan.', '{"0": "At Muzdalifah pilgrims spend the night and collect pebbles.", "1": "Masjid Nabawi is in Madinah.", "2": "At Arafat pilgrims stand in prayer."}'),
  ('ISL-0189', 'Beliefs and worship', 'Hajj', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB, Hajj', 'Umrah differs from Hajj in that it:', '["can be performed at any time of the year", "does not need ihram", "does not include tawaf", "is performed only in Madinah"]', 0, 'Umrah, the ''lesser pilgrimage'', has ihram, tawaf, sa''i and shaving or cutting hair, and has no fixed dates.', '{"1": "Umrah also needs ihram.", "2": "Tawaf is a main part of Umrah.", "3": "Umrah is performed in Makkah."}'),
  ('ISL-0190', 'Beliefs and worship', 'Festivals', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Eid al-Adha remembers the readiness of which prophet to sacrifice his son?', '["Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Nuh (AS)", "Hazrat Yaqub (AS)"]', 0, 'As-Saffat 37:102-107 tells how Allah ransomed Ibrahim''s (AS) son with a great sacrifice.', '{"1": "Musa (AS) is remembered for leading Bani Israel out of Egypt.", "2": "Nuh (AS) is remembered for the Ark.", "3": "Yaqub (AS) is remembered for his patience over Yusuf (AS)."}'),
  ('ISL-0191', 'Beliefs and worship', 'Calendar', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB', 'The first month of the Islamic calendar is:', '["Dhul Hijjah", "Rabi-ul-Awwal", "Muharram", "Ramadan"]', 2, 'The Hijri year begins with Muharram and ends with Dhul Hijjah.', '{"0": "Dhul Hijjah is the twelfth and last month.", "1": "Rabi-ul-Awwal is the third month.", "3": "Ramadan is the ninth month."}'),
  ('ISL-0192', 'Beliefs and worship', 'Calendar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 4662', 'Which of these is one of the four sacred months in Islam?', '["Rajab", "Safar", "Shaban", "Ramadan"]', 0, 'At-Tawbah 9:36 mentions four sacred months; the hadith names them as Dhul Qa''dah, Dhul Hijjah, Muharram and Rajab.', '{"1": "Safar is not one of them.", "2": "Shaban is not one of them.", "3": "Ramadan is the month of fasting, but not one of the four sacred months."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0193', 'Beliefs and worship', 'Calendar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Islamiat (compulsory), PTB', 'An Islamic (lunar) year has about how many days?', '["365", "360", "340", "354"]', 3, 'Twelve lunar months of 29 or 30 days give about 354 days, so Islamic dates move about 11 days earlier each solar year.', '{"0": "365 days is the solar year.", "1": "The lunar year is about 354 or 355 days.", "2": "That is too short."}'),
  ('ISL-0194', 'The Rightly Guided Caliphs', 'Hazrat Abu Bakr', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Hazrat Abu Bakr (RA) was caliph from:', '["644 to 656 AD", "634 to 644 AD", "632 to 634 AD", "656 to 661 AD"]', 2, 'Abu Bakr (RA) ruled for about two years and three months, until his death in 634.', '{"0": "That was Hazrat Uthman''s (RA) caliphate.", "1": "That was Hazrat Umar''s (RA) caliphate.", "3": "That was Hazrat Ali''s (RA) caliphate."}'),
  ('ISL-0195', 'The Rightly Guided Caliphs', 'Hazrat Abu Bakr', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 4986', 'The heavy loss of huffaz in which battle led Hazrat Abu Bakr (RA) to have the Quran collected in one copy?', '["Yarmouk", "Yamamah", "Qadisiyyah", "Badr"]', 1, 'At Yamamah (632) against Musaylimah the false prophet, many reciters were martyred; Umar (RA) urged that the Quran be collected.', '{"0": "Yarmouk was fought against the Byzantines in 636.", "2": "Qadisiyyah was fought against the Persians in 636.", "3": "Badr was in the Holy Prophet''s (PBUH) lifetime."}'),
  ('ISL-0196', 'The Rightly Guided Caliphs', 'Hazrat Abu Bakr', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Hazrat Abu Bakr''s (RA) given name was:', '["Abdur Rahman", "Atiq", "Abdullah", "Uthman"]', 2, 'His name was Abdullah bin Uthman; Abu Bakr was his kunya and As-Siddiq his title.', '{"0": "Abdur Rahman was the name of his son.", "1": "Atiq was a title meaning ''freed (from the Fire)''.", "3": "Uthman bin Amir (Abu Quhafa) was his father."}'),
  ('ISL-0197', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Hazrat Umar (RA) is known by the title:', '["Zun-Nurain", "As-Siddiq", "Asadullah", "Al-Faruq"]', 3, 'Al-Faruq means ''the one who distinguishes truth from falsehood''.', '{"0": "Zun-Nurain is the title of Uthman (RA).", "1": "As-Siddiq is the title of Abu Bakr (RA).", "2": "Asadullah is a title of Ali (RA) (and of Hamza (RA))."}'),
  ('ISL-0198', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Which caliph set up the Diwan, a register of soldiers and citizens entitled to state stipends?', '["Hazrat Ali (RA)", "Hazrat Uthman (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Umar (RA)"]', 3, 'Umar (RA) organised the state: the Diwan, provinces with governors, judges, police and the Hijri calendar.', '{"0": "Ali (RA) inherited the Diwan.", "1": "Uthman (RA) kept the system Umar (RA) had set up.", "2": "Abu Bakr''s (RA) short rule was spent on the Riddah wars."}'),
  ('ISL-0199', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The Battle of Qadisiyyah (636), which opened Iraq to the Muslims, was led by:', '["Hazrat Amr bin al-As (RA)", "Hazrat Abu Ubaidah (RA)", "Hazrat Saad bin Abi Waqqas (RA)", "Hazrat Khalid bin Walid (RA)"]', 2, 'Saad (RA) defeated the Sasanian army under Rustam at Qadisiyyah; the Persian capital Ctesiphon fell soon after.', '{"0": "Amr (RA) conquered Egypt.", "1": "Abu Ubaidah (RA) commanded in Syria.", "3": "Khalid (RA) led the Muslims at Yarmouk against the Byzantines."}'),
  ('ISL-0200', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The Battle of Yarmouk (636) was fought between the Muslims and the:', '["Byzantines", "Persians", "Quraysh", "Mongols"]', 0, 'At Yarmouk, Khalid bin Walid (RA) defeated the Byzantine army, opening Syria to the Muslims.', '{"1": "The Persians were fought at Qadisiyyah and Nahavand.", "2": "Battles with the Quraysh ended with the conquest of Makkah in 8 AH.", "3": "The Mongols came six centuries later."}'),
  ('ISL-0201', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The Battle of Nahavand (642), which broke Persian power, is known as:', '["Yaum al-Furqan", "Aam al-Fil", "Dhat al-Sawari", "Fath al-Futuh (the victory of victories)"]', 3, 'After Nahavand, the Sasanian empire could no longer field a large army.', '{"0": "Yaum al-Furqan is the Quran''s name for Badr.", "1": "Aam al-Fil is the Year of the Elephant.", "2": "Dhat al-Sawari was a naval battle under Uthman (RA)."}'),
  ('ISL-0202', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Which of these cities was founded as a garrison town during Hazrat Umar''s (RA) caliphate?', '["Baghdad", "Cordoba", "Kufa", "Damascus"]', 2, 'Kufa and Basra in Iraq and Fustat in Egypt were founded as army towns under Umar (RA).', '{"0": "Baghdad was founded by the Abbasid caliph Al-Mansur in 762.", "1": "Cordoba was a Roman city, later the Umayyad capital in Spain.", "3": "Damascus is an ancient city, later the Umayyad capital."}'),
  ('ISL-0203', 'The Rightly Guided Caliphs', 'Hazrat Umar', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Hazrat Umar (RA) was martyred by:', '["Abu Lu''lu''ah Firoz", "Ibn Muljam", "Musaylimah", "Abu Jahl"]', 0, 'A Persian slave, Abu Lu''lu''ah, stabbed Umar (RA) during the Fajr prayer in 644.', '{"1": "Ibn Muljam martyred Ali (RA).", "2": "Musaylimah was a false prophet killed at Yamamah.", "3": "Abu Jahl was killed at Badr."}'),
  ('ISL-0204', 'The Rightly Guided Caliphs', 'Hazrat Uthman', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The first Muslim navy was built during the caliphate of Hazrat Uthman (RA) by the governor of Syria:', '["Hazrat Khalid bin Walid (RA)", "Hazrat Amr bin al-As (RA)", "Hazrat Saad bin Abi Waqqas (RA)", "Hazrat Muawiyah (RA)"]', 3, 'Muawiyah''s (RA) fleet took Cyprus and, with Egypt''s fleet, beat the Byzantines at Dhat al-Sawari (655).', '{"0": "Khalid (RA) died in 642.", "1": "Amr (RA) was governor of Egypt.", "2": "Saad (RA) was governor of Kufa."}'),
  ('ISL-0205', 'The Rightly Guided Caliphs', 'Hazrat Uthman', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sunan at-Tirmidhi, hadith 3703', 'Before his caliphate, Hazrat Uthman (RA) bought the Well of Rumah in Madinah and:', '["kept it for his own family", "sold its water to travellers", "gave it to the Jews of Madinah", "gave it free for all Muslims to use"]', 3, 'The Holy Prophet (PBUH) promised Paradise to whoever bought Rumah for the Muslims; Uthman (RA) did so.', '{"0": "He gave it to the community.", "1": "He bought it so that its water would be free.", "2": "Its earlier owner was the one who sold the water."}'),
  ('ISL-0206', 'The Rightly Guided Caliphs', 'Hazrat Ali', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 441', 'Which kunya (nickname) did the Holy Prophet (PBUH) give Hazrat Ali (RA), and which Ali loved most?', '["Abu Bakr", "Abu Turab", "Abu Hafs", "Abu Hurairah"]', 1, 'Finding Ali (RA) asleep with dust on him, the Holy Prophet (PBUH) called him ''Abu Turab'' (father of dust).', '{"0": "Abu Bakr is the kunya of the first caliph.", "2": "Abu Hafs is a kunya of Umar (RA).", "3": "Abu Hurairah (''father of the kitten'') is the kunya of the famous narrator."}'),
  ('ISL-0207', 'The Rightly Guided Caliphs', 'Hazrat Ali', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The Battle of Siffin (657) was fought between Hazrat Ali (RA) and:', '["Hazrat Aisha (RA)", "the Kharijites", "Hazrat Muawiyah (RA)", "the Byzantines"]', 2, 'Siffin ended in arbitration, which a group rejected; they became the Kharijites.', '{"0": "Aisha (RA) was on the other side at the Battle of the Camel (656).", "1": "Ali (RA) fought the Kharijites at Nahrawan.", "3": "Siffin was a war among Muslims."}'),
  ('ISL-0208', 'The Rightly Guided Caliphs', 'Hazrat Ali', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'The Kharijites were defeated by Hazrat Ali (RA) at the Battle of:', '["Jamal", "Nahrawan", "Karbala", "Siffin"]', 1, 'In 658 Ali (RA) defeated the Kharijites at Nahrawan; one of them, Ibn Muljam, later martyred him.', '{"0": "Jamal (the Camel) was fought in 656, before the Kharijites appeared.", "2": "Karbala was in 680, after Ali''s (RA) death.", "3": "The Kharijites broke away after Siffin."}'),
  ('ISL-0209', 'The Rightly Guided Caliphs', 'Hazrat Ali', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Hazrat Ali (RA) was martyred in 661 in the mosque of:', '["Makkah", "Kufa", "Damascus", "Madinah"]', 1, 'Ibn Muljam struck him with a poisoned sword at Fajr in the mosque of Kufa.', '{"0": "He was not in Makkah.", "2": "Damascus was Muawiyah''s (RA) capital.", "3": "Ali (RA) had moved his capital from Madinah to Kufa."}'),
  ('ISL-0210', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'The Umayyad dynasty was founded in 661 by Hazrat Muawiyah (RA) with its capital at:', '["Damascus", "Kufa", "Baghdad", "Cairo"]', 0, 'The Umayyads ruled from Damascus until 750.', '{"1": "Kufa was Hazrat Ali''s (RA) capital.", "2": "Baghdad was the Abbasid capital.", "3": "Cairo was the Fatimid capital."}'),
  ('ISL-0211', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'The Umayyad caliphate ended in 750 when it was overthrown by the:', '["Abbasids", "Mongols", "Fatimids", "Ottomans"]', 0, 'The Abbasids defeated the Umayyads at the Battle of the Zab in 750; one Umayyad prince escaped to found a state in Spain.', '{"1": "The Mongols destroyed Abbasid Baghdad in 1258.", "2": "The Fatimids rose in North Africa in 909.", "3": "The Ottomans rose in the 14th century."}'),
  ('ISL-0212', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Bait-ul-Hikmah, the great centre of translation and learning in Baghdad, flourished under the Abbasid caliph:', '["Al-Ma''mun", "Umar bin Abdul Aziz", "Al-Musta''sim", "Al-Mansur"]', 0, 'Al-Ma''mun (813-833) expanded the House of Wisdom, where Greek works were translated into Arabic.', '{"1": "Umar bin Abdul Aziz was an Umayyad caliph.", "2": "Al-Musta''sim was the last caliph, killed by the Mongols in 1258.", "3": "Al-Mansur founded Baghdad itself in 762."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0213', 'The Rightly Guided Caliphs', 'After the caliphs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Baghdad was sacked by the Mongols under Halaku Khan in:', '["1453", "1492", "1258", "1099"]', 2, 'Halaku destroyed Baghdad and killed the last Abbasid caliph there.', '{"0": "1453 is when the Ottomans took Constantinople.", "1": "1492 is when Granada, the last Muslim state in Spain, fell.", "3": "1099 is when the Crusaders took Jerusalem."}'),
  ('ISL-0214', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Which Umayyad caliph is often called the ''fifth rightly guided caliph'' for his justice and piety?', '["Harun al-Rashid", "Yazid bin Muawiyah", "Umar bin Abdul Aziz", "Walid bin Abdul Malik"]', 2, 'Umar bin Abdul Aziz (717-720) ended unjust taxes and ordered hadith to be written down officially.', '{"0": "Harun al-Rashid was an Abbasid caliph.", "1": "Yazid''s rule is remembered for Karbala.", "3": "Walid''s reign is known for conquests in Sindh and Spain."}'),
  ('ISL-0215', 'The Rightly Guided Caliphs', 'After the caliphs', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Jerusalem was recaptured from the Crusaders in 1187 by:', '["Tariq bin Ziyad", "Salahuddin Ayyubi", "Sultan Mehmed II", "Mahmud of Ghazni"]', 1, 'Salahuddin defeated the Crusaders at Hattin and then took Jerusalem in 1187.', '{"0": "Tariq led the conquest of Spain in 711.", "2": "Mehmed II took Constantinople in 1453.", "3": "Mahmud of Ghazni raided India in the 11th century."}'),
  ('ISL-0216', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'The conquest of Spain began in 711 under the commander:', '["Uqbah bin Nafi", "Musa bin Nusayr", "Muhammad bin Qasim", "Tariq bin Ziyad"]', 3, 'Tariq crossed from Africa to the rock that is still named after him, Gibraltar (Jabal al-Tariq).', '{"0": "Uqbah conquered much of North Africa earlier.", "1": "Musa was the governor who sent Tariq and joined him later.", "2": "Muhammad bin Qasim conquered Sindh in 711-712."}'),
  ('ISL-0217', 'The Rightly Guided Caliphs', 'After the caliphs', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'The tragedy of Karbala took place on 10 Muharram in the year:', '["11 AH (632 AD)", "132 AH (750 AD)", "40 AH (661 AD)", "61 AH (680 AD)"]', 3, 'Hazrat Husain (RA), grandson of the Holy Prophet (PBUH), was martyred at Karbala by Yazid''s army.', '{"0": "11 AH is the year the Holy Prophet (PBUH) passed away.", "1": "132 AH is when the Umayyads fell.", "2": "40 AH is the year Hazrat Ali (RA) was martyred."}'),
  ('ISL-0218', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'How many prophets are named in the Holy Quran?', '["25", "313", "12", "124,000"]', 0, 'The Quran names 25 prophets, from Adam (AS) to Muhammad (PBUH).', '{"1": "313 is the number at Badr (and a narration''s count of messengers).", "2": "More than 12 are named.", "3": "A narration gives about 124,000 prophets in all, but only 25 are named."}'),
  ('ISL-0219', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which of these is NOT one of the Ulul Azm (prophets of great resolve)?', '["Hazrat Yusuf (AS)", "Hazrat Isa (AS)", "Hazrat Musa (AS)", "Hazrat Nuh (AS)"]', 0, 'The five are usually listed as Nuh, Ibrahim, Musa, Isa and Muhammad (peace be upon them), based on Al-Ahzab 33:7 and Ash-Shura 42:13.', '{"1": "Isa (AS) is one of the five.", "2": "Musa (AS) is one of the five.", "3": "Nuh (AS) is one of the five."}'),
  ('ISL-0220', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Hazrat Isa (AS) is given which title?', '["Ruhullah", "Kalimullah", "Khalilullah", "Zabihullah"]', 0, 'An-Nisa 4:171 calls Isa (AS) ''a word from Allah and a spirit from Him''.', '{"1": "Kalimullah is Musa (AS).", "2": "Khalilullah is Ibrahim (AS).", "3": "Zabihullah is Ismail (AS)."}'),
  ('ISL-0221', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which prophet is called Zabihullah?', '["Hazrat Adam (AS)", "Hazrat Yahya (AS)", "Hazrat Ismail (AS)", "Hazrat Ishaq (AS)"]', 2, 'Zabihullah means ''the one offered for sacrifice to Allah''.', '{"0": "Adam (AS) is called Abul Bashar (father of mankind).", "1": "Yahya (AS) was the son of Zakariya (AS).", "3": "Ishaq (AS) was Ibrahim''s (AS) other son, born to Sarah."}'),
  ('ISL-0222', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which prophet was given control of the wind and could understand the speech of birds and ants?', '["Hazrat Dawud (AS)", "Hazrat Sulaiman (AS)", "Hazrat Hud (AS)", "Hazrat Yunus (AS)"]', 1, 'An-Naml 27:16-19 and Saba 34:12 describe these gifts given to Sulaiman (AS).', '{"0": "Dawud (AS) was given the Zabur and could shape iron.", "2": "Hud (AS) was sent to the people of ''Ad.", "3": "Yunus (AS) was swallowed by a fish."}'),
  ('ISL-0223', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'For which prophet did Allah make iron soft, so he could make coats of mail?', '["Hazrat Dawud (AS)", "Hazrat Idris (AS)", "Hazrat Nuh (AS)", "Hazrat Sulaiman (AS)"]', 0, 'Saba 34:10-11: ''We made iron soft for him: make full coats of mail''.', '{"1": "No such miracle is given for Idris (AS).", "2": "Nuh (AS) built the Ark of wood.", "3": "For Sulaiman (AS) a spring of molten copper was made to flow."}'),
  ('ISL-0224', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Which prophet is the model of patience in illness and loss?', '["Hazrat Lut (AS)", "Hazrat Ayyub (AS)", "Hazrat Shu''aib (AS)", "Hazrat Salih (AS)"]', 1, 'Sad 38:44: ''We found him patient; an excellent servant''.', '{"0": "Lut (AS) is known for warning his sinful people.", "2": "Shu''aib (AS) told his people to give full measure.", "3": "Salih (AS) is known for the she-camel."}'),
  ('ISL-0225', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Prophet Salih (AS) was sent to the people of Thamud, whose sign was:', '["a staff that turned into a snake", "a great flood", "a she-camel", "a cow"]', 2, 'Thamud were told not to harm the she-camel; they killed it and were destroyed (Hud 11:64-67).', '{"0": "That was a miracle of Musa (AS).", "1": "The flood was the punishment of Nuh''s (AS) people.", "3": "The cow was in the story of Bani Israel."}'),
  ('ISL-0226', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Prophet Hud (AS) was sent to the people of:', '["Thamud", "Madyan", "Sodom", "''Ad"]', 3, '''Ad were a proud and powerful people destroyed by a fierce wind (Al-Haqqah 69:6-7).', '{"0": "Salih (AS) was sent to Thamud.", "1": "Shu''aib (AS) was sent to Madyan.", "2": "Lut (AS) was sent to Sodom."}'),
  ('ISL-0227', 'Prophets and companions', 'Prophets', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Prophet Shu''aib (AS) warned his people especially against:', '["cheating in weights and measures", "worshipping a golden calf", "building idols of saints", "killing a she-camel"]', 0, 'Hud 11:84-85: Shu''aib (AS) told Madyan to give full measure and weight.', '{"1": "That was Bani Israel in the time of Musa (AS).", "2": "That was the sin of Nuh''s (AS) people.", "3": "That was Thamud."}'),
  ('ISL-0228', 'Prophets and companions', 'Prophets', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Hazrat Yahya (AS) was the son of:', '["Hazrat Ishaq (AS)", "Hazrat Ibrahim (AS)", "Hazrat Zakariya (AS)", "Hazrat Imran"]', 2, 'Maryam 19:7: Zakariya (AS) was given the good news of a son named Yahya, a name given to no one before.', '{"0": "Ishaq''s (AS) son was Yaqub (AS).", "1": "Ibrahim''s (AS) sons were Ismail (AS) and Ishaq (AS).", "3": "Imran was the father of Maryam (AS)."}'),
  ('ISL-0229', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 453', 'Which companion was known as the poet of the Holy Prophet (PBUH)?', '["Hazrat Abdullah bin Masud (RA)", "Hazrat Hassan bin Thabit (RA)", "Hazrat Zaid bin Thabit (RA)", "Hazrat Abu Dharr (RA)"]', 1, 'Hassan (RA) answered the poets of the Quraysh with verses defending Islam.', '{"0": "Ibn Masud (RA) was a great reciter and jurist.", "2": "Zaid (RA) was a scribe of revelation.", "3": "Abu Dharr (RA) was known for his simple life."}'),
  ('ISL-0230', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 143', 'Hazrat Abdullah bin Abbas (RA) is called ''Tarjuman al-Quran'' because he:', '["wrote down the first copy of the Quran", "was the first to memorise the Quran", "translated the Quran into Persian", "was the greatest early interpreter of the Quran"]', 3, 'The Holy Prophet (PBUH) prayed for him to be given understanding of the religion and interpretation.', '{"0": "Zaid bin Thabit (RA) led the writing.", "1": "Many memorised it before him.", "2": "Translation into Persian came centuries later."}'),
  ('ISL-0231', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Shibli Nomani, Al-Faruq; Islamiat (compulsory), PTB; Encyclopaedia of Islam', 'Egypt was conquered in the time of Hazrat Umar (RA) by:', '["Hazrat Khalid bin Walid (RA)", "Hazrat Saad bin Abi Waqqas (RA)", "Hazrat Amr bin al-As (RA)", "Hazrat Muawiyah (RA)"]', 2, 'Amr (RA) took Egypt in 640-642 and founded Fustat, the forerunner of Cairo.', '{"0": "Khalid (RA) fought in Iraq and Syria.", "1": "Saad (RA) conquered Iraq.", "3": "Muawiyah (RA) was governor of Syria."}'),
  ('ISL-0232', 'Prophets and companions', 'Companions', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 3728', 'The first Muslim to shoot an arrow in the way of Allah was:', '["Hazrat Zubair (RA)", "Hazrat Ali (RA)", "Hazrat Hamza (RA)", "Hazrat Saad bin Abi Waqqas (RA)"]', 3, 'Saad (RA) said he was the first Arab to shoot an arrow in Allah''s way.', '{"0": "Zubair (RA) is remembered as the Prophet''s ''disciple'' (hawari).", "1": "Ali (RA) is not the one recorded for this.", "2": "Hamza (RA) is the leader of the martyrs."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0233', 'Prophets and companions', 'Companions', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Sahih al-Bukhari, hadith 3624', 'Hazrat Fatimah (RA) is given the title:', '["As-Siddiqah", "Az-Zahra", "At-Tahirah", "Umm-ul-Masakin"]', 1, 'Fatimah (RA) is called Az-Zahra (the radiant) and the leader of the women of Paradise.', '{"0": "As-Siddiqah is a title of Aisha (RA).", "2": "At-Tahirah was a title of Khadijah (RA).", "3": "Umm-ul-Masakin (mother of the poor) was Zainab bint Khuzaymah (RA)."}'),
  ('ISL-0234', 'Prophets and companions', 'Companions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Safiur Rahman Mubarakpuri, Ar-Raheeq Al-Makhtum; Martin Lings, Muhammad: His Life Based on the Earliest Sources', 'The poor companions who lived on a raised platform at Masjid Nabawi and spent their time learning were called:', '["Muhajirun", "Ashab-e-Suffah", "Ansar", "Ashab-e-Kahf"]', 1, 'Abu Hurairah (RA) was one of them, which is why he heard so many hadith.', '{"0": "The Muhajirun were all who migrated from Makkah, rich and poor.", "2": "The Ansar were the Muslims of Madinah, with their own homes.", "3": "The Ashab-e-Kahf were the sleepers in the cave."}'),
  ('ISL-0235', 'Islamic law and society', 'Punishments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'In Islamic law, punishments fixed by the Quran or Sunnah for certain crimes are called:', '["Kaffarah", "Diyat", "Ta''zir", "Hudood"]', 3, 'Hudood (singular hadd) cover theft, zina, qazf, drinking and hirabah; Pakistan''s Hudood Ordinances date from 1979.', '{"0": "Kaffarah is an act of expiation, such as fasting.", "1": "Diyat is blood money paid as compensation.", "2": "Ta''zir punishments are left to the judge''s discretion."}'),
  ('ISL-0236', 'Islamic law and society', 'Punishments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'Punishments in Islamic law that are left to the judge or state to decide are called:', '["Khul''", "Hadd", "Qisas", "Ta''zir"]', 3, 'Ta''zir covers offences that have no fixed punishment; the amount is set by the court or by law.', '{"0": "Khul'' is a form of divorce.", "1": "Hadd punishments are fixed by the texts.", "2": "Qisas is equal retaliation for murder or injury."}'),
  ('ISL-0237', 'Islamic law and society', 'Punishments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Compensation paid to the heirs of a person who was killed, in place of retaliation, is called:', '["Jizya", "Qisas", "Mahr", "Diyat"]', 3, 'Al-Baqarah 2:178 allows heirs to forgive and accept compensation; Pakistan''s Qisas and Diyat law dates from 1990.', '{"0": "Jizya was a tax on non-Muslim citizens.", "1": "Qisas is retaliation itself.", "2": "Mahr is the dower paid to a wife."}'),
  ('ISL-0238', 'Islamic law and society', 'Punishments', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Qisas means:', '["a fixed punishment for theft", "blood money", "forgiveness by the victim", "equal retaliation for killing or injury"]', 3, 'Al-Ma''idah 5:45: a life for a life, an eye for an eye, with forgiveness praised.', '{"0": "That is a hadd.", "1": "Blood money is diyat.", "2": "Forgiveness (afw) ends the right to qisas."}'),
  ('ISL-0239', 'Islamic law and society', 'Family', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The waiting period of a widow before she may remarry is:', '["one year", "three menstrual cycles", "four months and ten days", "forty days"]', 2, 'Al-Baqarah 2:234 sets four months and ten days; a pregnant widow''s iddat ends at delivery.', '{"0": "The Quran replaced a year with four months and ten days.", "1": "Three cycles is the iddat after divorce.", "3": "Forty days is not the iddat in any case."}'),
  ('ISL-0240', 'Islamic law and society', 'Family', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The gift that a husband must give his wife at marriage is called:', '["Walimah", "Jahez", "Mahr", "Nafaqah"]', 2, 'An-Nisa 4:4: ''Give women their mahr as a free gift.''', '{"0": "Walimah is the marriage feast.", "1": "Jahez (dowry) is goods from the bride''s family; it is a custom, not an Islamic duty.", "3": "Nafaqah is maintenance during marriage."}'),
  ('ISL-0241', 'Islamic law and society', 'Family', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Constitution of the Islamic Republic of Pakistan; Pakistan Code (pakistancode.gov.pk)', 'In Pakistan, the Muslim Family Laws Ordinance, which requires marriages to be registered and controls polygamy, was passed in:', '["1961", "1973", "1949", "1979"]', 0, 'The Muslim Family Laws Ordinance 1961, passed under Ayub Khan, needs a council''s permission for a second marriage.', '{"1": "1973 is the year of the present Constitution.", "2": "1949 is the year of the Objectives Resolution.", "3": "1979 is the year of the Hudood Ordinances."}'),
  ('ISL-0242', 'Islamic law and society', 'Inheritance', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'Under Islamic inheritance law, a son''s share is:', '["equal to a daughter''s share", "twice a daughter''s share", "half a daughter''s share", "the whole estate"]', 1, 'An-Nisa 4:11: ''for the male, the like of the share of two females'', since the man carries the duty of maintenance.', '{"0": "An-Nisa 4:11 gives the son double.", "2": "It is the other way round.", "3": "Daughters, parents and spouse also have shares."}'),
  ('ISL-0243', 'Islamic law and society', 'Inheritance', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'A wife''s share of her husband''s estate when he leaves children is:', '["one third", "one half", "one eighth", "one quarter"]', 2, 'An-Nisa 4:12 gives the wife one quarter, or one eighth if there are children.', '{"0": "One third is the limit for bequests.", "1": "One half is a husband''s share if his wife leaves no children.", "3": "One quarter is her share if he leaves no children."}'),
  ('ISL-0244', 'Islamic law and society', 'Islamic finance', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'A partnership in which one party gives the capital and the other gives the work, sharing profit by agreement, is called:', '["Takaful", "Ijarah", "Mudarabah", "Murabahah"]', 2, 'In mudarabah, loss of capital falls on the investor unless the worker was negligent; profit is shared.', '{"0": "Takaful is mutual insurance.", "1": "Ijarah is leasing.", "3": "Murabahah is a sale at cost plus a stated profit."}'),
  ('ISL-0245', 'Islamic law and society', 'Islamic finance', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: State Bank of Pakistan, Islamic banking glossary', 'In Islamic banking, a sale in which the bank buys goods and sells them to the client at cost plus a disclosed profit is called:', '["Murabahah", "Musharakah", "Mudarabah", "Sukuk"]', 0, 'Murabahah is the most common financing contract in Islamic banks.', '{"1": "Musharakah is a joint venture where both partners give capital.", "2": "Mudarabah is capital from one side and work from the other.", "3": "Sukuk are Islamic investment certificates."}'),
  ('ISL-0246', 'Islamic law and society', 'Islamic finance', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Federal Shariat Court, Riba judgment, 28 April 2022; Constitution of the Islamic Republic of Pakistan; Pakistan Code (pakistancode.gov.pk)', 'In 2022 the Federal Shariat Court ordered that riba be removed from Pakistan''s economy by the end of:', '["2030", "2025", "2047", "2027"]', 3, 'In April 2022 the court held interest to be riba and gave the government until 31 December 2027; the 26th Amendment (2024) also names 1 January 2028 for removing riba.', '{"0": "The date set was 2027.", "1": "The court gave five years, to December 2027.", "2": "2047 is not the date set by the court."}'),
  ('ISL-0247', 'Islamic law and society', 'Courts and institutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Constitution of the Islamic Republic of Pakistan; Pakistan Code (pakistancode.gov.pk)', 'The Federal Shariat Court of Pakistan was set up in:', '["1991", "1980", "1956", "1973"]', 1, 'Chapter 3A was added to the Constitution in 1980 to set up the Federal Shariat Court, which can strike down laws against Islam.', '{"0": "1991 is when the court gave its first major riba decision.", "2": "The 1956 Constitution had no such court.", "3": "The 1973 Constitution did not have it at first; it was added later."}'),
  ('ISL-0248', 'Islamic law and society', 'Courts and institutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Constitution of the Islamic Republic of Pakistan; Pakistan Code (pakistancode.gov.pk)', 'The constitutional body that advises Parliament on whether laws agree with Islam is the:', '["Council of Islamic Ideology", "Senate", "Supreme Judicial Council", "Federal Shariat Court"]', 0, 'Articles 227-231 of the Constitution set up the Council of Islamic Ideology.', '{"1": "The Senate is the upper house of Parliament.", "2": "The Supreme Judicial Council hears complaints against judges.", "3": "The Federal Shariat Court is a court that can strike down laws, not an advisory council."}'),
  ('ISL-0249', 'Islamic law and society', 'Courts and institutions', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Constitution of the Islamic Republic of Pakistan; Pakistan Code (pakistancode.gov.pk)', 'The office that hears public complaints against government departments in Pakistan, based on the old Islamic office of the muhtasib, is the:', '["Attorney-General", "Wafaqi Mohtasib (Federal Ombudsman)", "Auditor-General", "Election Commission"]', 1, 'The Wafaqi Mohtasib was set up by the Establishment of the Office of Wafaqi Mohtasib (Ombudsman) Order 1983.', '{"0": "The Attorney-General is the government''s chief lawyer.", "2": "The Auditor-General checks public accounts.", "3": "The Election Commission runs elections."}'),
  ('ISL-0250', 'Islamic law and society', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'Imam Abu Yusuf, the student of Imam Abu Hanifa, is known for being:', '["the first chief judge (Qadi al-Qudat) and author of Kitab al-Kharaj", "the compiler of Sahih al-Bukhari", "the builder of Bait-ul-Hikmah", "the founder of the Maliki school"]', 0, 'Abu Yusuf served Harun al-Rashid as chief judge and wrote Kitab al-Kharaj on taxation and public finance.', '{"1": "That was Imam Bukhari.", "2": "Bait-ul-Hikmah grew under the Abbasid caliphs.", "3": "That was Imam Malik."}'),
  ('ISL-0251', 'Islamic law and society', 'Jurisprudence', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: S. M. Ikram, Muslim Civilization in India', 'Fatawa-e-Alamgiri, a large collection of Hanafi rulings, was compiled under the Mughal emperor:', '["Babur", "Shah Jahan", "Akbar", "Aurangzeb"]', 3, 'Aurangzeb (Alamgir) had scholars compile it in the late 17th century as a guide for judges.', '{"0": "Babur founded the Mughal empire.", "1": "Shah Jahan is known for his buildings.", "2": "Akbar''s reign is known for Din-e-Ilahi, not this collection."}'),
  ('ISL-0252', 'Islamic law and society', 'Jurisprudence', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'Al-Hidayah, a standard textbook of Hanafi law still taught in South Asia, was written by:', '["Burhanuddin al-Marghinani", "Imam Ghazali", "Imam Shafi''i", "Ibn Khaldun"]', 0, 'Al-Marghinani (died 1197) wrote Al-Hidayah; it was translated into English under the British for use in courts.', '{"1": "Ghazali was a Shafi''i theologian; his best-known work is Ihya Ulum al-Din.", "2": "Imam Shafi''i wrote Al-Risalah on legal theory.", "3": "Ibn Khaldun wrote the Muqaddimah."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, mdcat, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Islamiat', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('ISL-0253', 'Islamic law and society', 'Jurisprudence', 'hard', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'The Hanafi principle of setting aside strict analogy in favour of a ruling that better serves fairness is called:', '["Istishab", "Istihsan", "Ijma", "Taqlid"]', 1, 'Istihsan (juristic preference) is used mainly by Hanafis; Malikis use a similar idea called maslahah.', '{"0": "Istishab is the presumption that a known state continues.", "2": "Ijma is the consensus of scholars.", "3": "Taqlid is following a school''s established opinion."}'),
  ('ISL-0254', 'Islamic law and society', 'Jurisprudence', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'An act that is neither rewarded nor punished, and is left to choice, is called:', '["Mubah", "Wajib", "Mustahab", "Makruh"]', 0, 'Acts are ranked fard/wajib, mustahab, mubah, makruh and haram.', '{"1": "Wajib is obligatory.", "2": "Mustahab is recommended and rewarded.", "3": "Makruh is disliked; avoiding it is rewarded."}'),
  ('ISL-0255', 'Islamic law and society', 'Society', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: The Holy Quran (translation by Muhammad Taqi Usmani); Islamiat (compulsory), PTB', 'The Quran''s instruction that Muslims run their affairs by mutual consultation is in Surah:', '["Ash-Shura", "Al-Kahf", "Al-Fil", "Al-Qadr"]', 0, 'Ash-Shura 42:38 praises those ''whose affairs are settled by consultation among them''.', '{"1": "Al-Kahf does not set this rule.", "2": "Al-Fil is about Abraha''s army.", "3": "Al-Qadr is about the Night of Decree."}'),
  ('ISL-0256', 'Islamic law and society', 'Society', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'In early Islamic states, a tax paid by able non-Muslim citizens in place of military service was called:', '["Khums", "Jizya", "Zakat", "Ushr"]', 1, 'Women, children, the old, the poor and monks were exempt; those who served in the army were usually excused.', '{"0": "Khums is one fifth of spoils of war.", "2": "Zakat is paid by Muslims.", "3": "Ushr was a tithe on the produce of Muslims'' land."}'),
  ('ISL-0257', 'Islamic law and society', 'Society', 'easy', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Mohammad Hashim Kamali, Principles of Islamic Jurisprudence; Islamiat (compulsory), PTB', 'Property given permanently for religious or charitable use, such as a mosque, school or well, is called:', '["Wasiyyah", "Mahr", "Riba", "Waqf"]', 3, 'Once property is made waqf it cannot be sold or inherited; its income goes to the stated purpose.', '{"0": "Wasiyyah is a will; a waqf can be made in one, but they are different.", "1": "Mahr is the dower paid to a wife.", "2": "Riba is interest."}'),
  ('ISL-0258', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Kitab al-Hind, a study of Indian religion and science, was written by:', '["Ibn Battuta", "Al-Biruni", "Al-Ghazali", "Ibn Rushd"]', 1, 'Al-Biruni came to India with Mahmud of Ghazni and learned Sanskrit to write his book (about 1030).', '{"0": "Ibn Battuta wrote a travel book, the Rihla.", "2": "Al-Ghazali wrote on theology and spiritual life.", "3": "Ibn Rushd wrote on philosophy and law."}'),
  ('ISL-0259', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Ihya Ulum al-Din (The Revival of the Religious Sciences) was written by:', '["Ibn Sina", "Shah Waliullah", "Imam Bukhari", "Imam Ghazali"]', 3, 'Al-Ghazali (died 1111) wrote it after leaving his teaching post in Baghdad for a life of devotion.', '{"0": "Ibn Sina wrote the Canon of Medicine.", "1": "Shah Waliullah wrote Hujjatullah al-Balighah.", "2": "Imam Bukhari compiled hadith."}'),
  ('ISL-0260', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: S. M. Ikram, Muslim Civilization in India', 'Kashf al-Mahjub, one of the earliest books on Sufism in Persian, was written in Lahore by:', '["Khwaja Moinuddin Chishti", "Baba Farid", "Hazrat Ali Hujwiri (Data Ganj Bakhsh)", "Bahauddin Zakariya"]', 2, 'Ali Hujwiri (died about 1072) settled in Lahore; his shrine is Data Darbar.', '{"0": "Khwaja Moinuddin is buried in Ajmer and left no such book.", "1": "Baba Farid is known for his Punjabi verses.", "3": "Bahauddin Zakariya founded the Suhrawardi order in Multan."}'),
  ('ISL-0261', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Which Muslim scholar is known in Europe as Averroes and wrote famous commentaries on Aristotle?', '["Al-Kindi", "Ibn Rushd", "Al-Farabi", "Ibn Sina"]', 1, 'Ibn Rushd (died 1198) of Cordoba was also a judge and wrote a major book on comparative fiqh, Bidayat al-Mujtahid.', '{"0": "Al-Kindi was an earlier Arab philosopher.", "2": "Al-Farabi is called the ''Second Teacher'' after Aristotle.", "3": "Ibn Sina is known as Avicenna."}'),
  ('ISL-0262', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Philip K. Hitti, History of the Arabs; Encyclopaedia of Islam', 'Which Muslim scientist did pioneering work on light and vision in his Book of Optics?', '["Ibn Battuta", "Al-Razi", "Jabir bin Hayyan", "Ibn al-Haytham"]', 3, 'Ibn al-Haytham (died about 1040) showed that we see because light enters the eye, and used experiments to test ideas.', '{"0": "Ibn Battuta was a traveller.", "1": "Al-Razi is known for medicine.", "2": "Jabir is known for chemistry."}'),
  ('ISL-0263', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: S. M. Ikram, Muslim Civilization in India', 'Hujjatullah al-Balighah, a major work on the wisdom behind Islamic law, was written by:', '["Mujaddid Alf Sani", "Sir Syed Ahmad Khan", "Shah Waliullah", "Allama Iqbal"]', 2, 'Shah Waliullah (1703-1762) of Delhi explained the purposes behind the rules of the Shariah.', '{"0": "Mujaddid Alf Sani is known for his letters (Maktubat).", "1": "Sir Syed wrote on reform and Muslim education.", "3": "Iqbal wrote The Reconstruction of Religious Thought in Islam."}'),
  ('ISL-0264', 'Islamic law and society', 'Muslim scholars', 'moderate', 'Markhor Prep original question. HEC Law Admission Test (LAT) Part I, Islamiat. Checked against: Allama Iqbal, The Reconstruction of Religious Thought in Islam (1930)', 'The Reconstruction of Religious Thought in Islam, a set of lectures, was written by:', '["Shibli Nomani", "Allama Muhammad Iqbal", "Maulana Maududi", "Sir Syed Ahmad Khan"]', 1, 'Iqbal gave these lectures in Madras, Hyderabad and Aligarh; they were published in 1930.', '{"0": "Shibli wrote Al-Faruq and Sirat-un-Nabi.", "2": "Maududi wrote Tafhim-ul-Quran.", "3": "Sir Syed founded Aligarh College."}')
) AS s
